      </div>

      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white flex justify-between items-center">
        <div>
          <p className="text-blue-100 text-sm mb-1 font-medium">إجمالي الفترة المختارة</p>
          <h3 className="text-2xl font-bold tabular-nums">{total.toLocaleString('ar-SA')} ريال</h3>
        </div>
        <div className="p-3 bg-white/20 rounded-2xl">
          <TrendingUp size={24} />
        </div>
      </div>

      <div className="flex justify-between items-center">
        <h4 className="font-bold text-slate-400">سجل المصروفات</h4>
        <div className="flex gap-2">
