      const element = reportRef.current;
      if (!element) return;

      // إظهار العنصر في مكان بعيد بدلاً من display: none لضمان الرندرة الصحيحة
      element.style.display = 'block';
      element.style.visibility = 'visible';

      // ننتظر رندرة الصور والبيانات بشكل كامل
      await new Promise(resolve => setTimeout(resolve, 800));

      const canvas = await html2canvas(element, {
        scale: 2, 
        useCORS: true,
        logging: false,
        backgroundColor: '#ffffff',
        allowTaint: true
      });

      element.style.display = 'none';

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4'
      });

      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`sarf_report_${fromDate}_to_${toDate}.pdf`);
    } catch (error) {
      console.error('PDF Generation failed', error);
      alert('عذراً، حدث خطأ أثناء إنشاء الملف.');
    } finally {
      setIsGenerating(false);
    }
  };

  const total = expenses.reduce((acc, curr) => acc + curr.amount, 0);

  return (
    <div className="space-y-6 pb-10">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1">من تاريخ</label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={fromDate}
            onChange={(e) => setFromDate(e.target.value)}
          />
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1">إلى تاريخ</label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={toDate}
            onChange={(e) => setToDate(e.target.value)}
          />
        </div>
      </div>

      <div className="flex gap-2 overflow-x-auto no-scrollbar py-1">
        <button 
          onClick={() => setSelectedCategoryId('all')}
          className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === 'all' ? 'bg-blue-600 text-white' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
        >
          الكل
        </button>
        {categories.map(cat => (
          <button 
            key={cat.id}
            onClick={() => setSelectedCategoryId(cat.id)}
            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === cat.id ? 'bg-blue-600 text-white' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
          >
            {cat.name}
          </button>
        ))}
      </div>

      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white flex justify-between items-center">
        <div>
          <p className="text-blue-100 text-sm mb-1 font-medium">إجمالي الفترة المختارة</p>
          <h3 className="text-2xl font-bold tabular-nums">{total.toLocaleString('ar-SA')} ريال</h3>
        </div>
        <div className="p-3 bg-white/20 rounded-2xl">
          <TrendingUp size={24} />
        </div>
      </div>

      <div className="flex justify-between items-center">
        <h4 className="font-bold text-slate-400">سجل المصروفات</h4>
        <div className="flex gap-2">
          <button 
            onClick={() => setSortBy(sortBy === 'date' ? 'amount' : 'date')}
            className="px-3 py-2 bg-slate-900 border border-slate-800 rounded-xl text-xs text-blue-400 font-bold active:scale-95 transition-transform"
          >
            {sortBy === 'date' ? 'ترتيب: التاريخ' : 'ترتيب: المبلغ'}
          </button>
          <button 
            disabled={expenses.length === 0 || isGenerating}
            onClick={generatePDF}
            className={`px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 transition-all active:scale-95 ${isGenerating ? 'bg-slate-800 text-slate-500' : 'bg-green-600 text-white hover:bg-green-700'}`}
          >
            {isGenerating ? (
              <Loader2 size={16} className="animate-spin" />
            ) : (
              <FileDown size={16} />
            )}
            <span>تحميل PDF</span>
          </button>
        </div>
      </div>

      <div className="space-y-3">
        {expenses.map((exp, i) => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div key={exp.id} className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30">
