import Dexie from 'dexie';
import type { Table } from 'dexie';
import { Category, Expense, AppSettings } from './types';

// Define the database class extending Dexie
export class SarfDB extends Dexie {
  categories!: Table<Category>;
  expenses!: Table<Expense>;
  settings!: Table<AppSettings>;

  constructor() {
    super('SarfDB');
  }
}

export const db = new SarfDB();

// Fix: Moving the schema definition out of the constructor and using default import for Dexie 
// resolves the TypeScript error where 'version' was not correctly recognized as a method of SarfDB.
db.version(2).stores({
  categories: 'id, name, order',
  expenses: 'id, categoryId, date, createdAt',
  settings: '' 
});

export async function initializeDb() {
  const count = await db.categories.count();
  if (count === 0) {
    await db.categories.add({
      id: 'default_general',
      name: 'عام',
      color: '#3b82f6',
      order: 0,
      isDefault: true
    });
  }

  const settingsCount = await db.settings.count();
  if (settingsCount === 0) {
    await db.settings.put({
      showImages: true,
      showNotes: true
    }, 'app_settings');
  }
}

export interface Category {
  id: string;
  name: string;
  color: string;
  order: number;
  phoneNumber?: string; // حقل اختياري لرقم الهاتف
  isDefault?: boolean;
}

export interface Expense {
  id: string;
  categoryId: string;
  amount: number;
  date: string;
  notes?: string;
  image?: string; // base64
  createdAt: number;
}

export interface AppSettings {
  showImages: boolean;
  showNotes: boolean;
}

export enum ViewState {
  HOME = 'HOME',
  ADD_EXPENSE = 'ADD_EXPENSE',
  EDIT_EXPENSE = 'EDIT_EXPENSE',
  REPORTS = 'REPORTS',
  SETTINGS = 'SETTINGS',
  CATEGORY_DETAIL = 'CATEGORY_DETAIL'
}

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Category } from '../types';
import { 
  FolderPlus, 
  Trash2, 
  Phone,
  Plus
} from 'lucide-react';

interface HomeViewProps {
  onAdd: () => void;
  onCategorySelect: (cat: Category) => void;
}

const HomeView: React.FC<HomeViewProps> = ({ onAdd, onCategorySelect }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [categoryTotals, setCategoryTotals] = useState<Record<string, number>>({});
  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryPhone, setNewCategoryPhone] = useState('');
  const [totalExpenses, setTotalExpenses] = useState(0);

  const loadData = async () => {
    const cats = await db.categories.toArray();
    cats.sort((a, b) => a.order - b.order);
    setCategories(cats);

    const expenses = await db.expenses.toArray();
    const totals: Record<string, number> = {};
    let grandTotal = 0;

    expenses.forEach(exp => {
      totals[exp.categoryId] = (totals[exp.categoryId] || 0) + exp.amount;
      grandTotal += exp.amount;
    });

    setCategoryTotals(totals);
    setTotalExpenses(grandTotal);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleAddCategory = async () => {
    if (!newCategoryName.trim()) return;
    const id = Date.now().toString();
    const order = categories.length;
    await db.categories.add({
      id,
      name: newCategoryName,
      phoneNumber: newCategoryPhone.trim() || undefined,
      color: '#3b82f6',
      order
    });
    setNewCategoryName('');
    setNewCategoryPhone('');
    setIsAddingCategory(false);
    loadData();
  };

  const handleDeleteCategory = async (cat: Category) => {
    if (cat.isDefault) {
      alert('لا يمكن حذف القسم العام');
      return;
    }

    const count = await db.expenses.where('categoryId').equals(cat.id).count();
    if (count > 0) {
      const confirmMove = window.confirm(`هذا القسم يحتوي على ${count} مصروفات. هل تريد نقلها للقسم العام وحذف القسم؟`);
      if (confirmMove) {
        await db.expenses.where('categoryId').equals(cat.id).modify({ categoryId: 'default_general' });
        await db.categories.delete(cat.id);
        loadData();
      }
    } else {
      await db.categories.delete(cat.id);
      loadData();
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white text-center">
        <p className="text-blue-100 text-sm mb-1 font-medium">إجمالي المصاريف</p>
        <h2 className="text-4xl font-bold mb-2 tabular-nums">
          {totalExpenses.toLocaleString('ar-SA')} 
          <span className="text-lg mr-2 opacity-80">ريال</span>
        </h2>
      </div>

      <div className="flex justify-between items-center px-1">
        <h3 className="text-lg font-bold text-slate-300">الأقسام</h3>
        <button 
          onClick={() => setIsAddingCategory(true)}
          className="text-blue-500 hover:bg-blue-500/10 p-2 rounded-full transition-colors flex items-center gap-1"
        >
          <FolderPlus size={20} />
          <span className="text-sm font-medium">قسم جديد</span>
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {categories.map((cat) => (
          <div 
            key={cat.id}
            className="bg-slate-900 border border-slate-800 rounded-2xl p-4 active:scale-95 transition-transform group relative cursor-pointer flex flex-col justify-between h-full"
            onClick={() => onCategorySelect(cat)}
          >
            <div>
              <div className="flex justify-between items-start mb-2">
                <div 
                  className="w-3 h-3 rounded-full mt-1" 
                  style={{ backgroundColor: cat.color }} 
                />
                {!cat.isDefault && (
                  <button 
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteCategory(cat);
                    }}
                    className="text-slate-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <Trash2 size={16} />
                  </button>
                )}
              </div>
              <h4 className="font-bold text-slate-200 truncate">{cat.name}</h4>
              {cat.phoneNumber && (
                <div className="flex items-center gap-1 text-[10px] text-slate-500 mt-1">
                  <Phone size={10} />
                  <span>{cat.phoneNumber}</span>
                </div>
              )}
            </div>
            <p className="text-blue-400 font-bold text-sm mt-3 tabular-nums">
              {categoryTotals[cat.id] ? categoryTotals[cat.id].toLocaleString('ar-SA') : '٠'} ريال
            </p>
          </div>
        ))}
      </div>

      {isAddingCategory && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 w-full rounded-2xl p-6 shadow-2xl space-y-4">
            <h3 className="text-xl font-bold">إضافة قسم جديد</h3>

            <div className="space-y-3">
              <div>
                <label className="text-xs text-slate-500 block mb-1">اسم القسم</label>
                <input 
                  autoFocus
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                  placeholder="مثال: بقالة، كهرباء..."
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                />
              </div>

              <div>
                <label className="text-xs text-slate-500 block mb-1">رقم الهاتف (اختياري)</label>
                <input 
                  type="tel"
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none tabular-nums"
                  placeholder="05xxxxxxx"
                  value={newCategoryPhone}
                  onChange={(e) => setNewCategoryPhone(e.target.value)}
                />
              </div>
            </div>

            <div className="flex gap-3 pt-2">
              <button 
                onClick={handleAddCategory}
                className="flex-grow bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 transition-colors"
              >
                إضافة
              </button>
              <button 
                onClick={() => setIsAddingCategory(false)}
                className="flex-grow bg-slate-800 text-slate-300 font-bold py-3 rounded-xl hover:bg-slate-700 transition-colors"
              >
                إلغاء
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HomeView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { 
  FileDown, 
  TrendingUp,
  BarChart3,
  Loader2,
  Calendar,
  Receipt
} from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

const ReportsView: React.FC = () => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [sortBy, setSortBy] = useState<'date' | 'amount'>('date');
  const [isGenerating, setIsGenerating] = useState(false);

  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);

      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();

      if (selectedCategoryId !== 'all') {
        results = results.filter(e => e.categoryId === selectedCategoryId);
      }

      if (sortBy === 'date') {
        results.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()); // تصاعدي للتقرير
      } else {
        results.sort((a, b) => a.amount - b.amount);
      }

      setExpenses(results);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId, sortBy]);

  const generatePDF = async () => {
    if (expenses.length === 0 || isGenerating) return;

    setIsGenerating(true);
    try {
      const element = reportRef.current;
      if (!element) return;

      // تهيئة العنصر للالتقاط
      element.style.display = 'block';
      element.style.visibility = 'visible';
      element.style.position = 'fixed';
      element.style.top = '0';
      element.style.left = '0';
      element.style.zIndex = '-9999';

      // انتظار رندرة الصور بالكامل
      await new Promise(resolve => setTimeout(resolve, 1500));

      const canvas = await html2canvas(element, {
        scale: 2.5, // دقة أعلى
        useCORS: true,
        allowTaint: true,
        backgroundColor: '#ffffff',
        logging: false,
      });

      element.style.display = 'none';

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4'
      });

      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`كشف_صرف_${fromDate}_إلى_${toDate}.pdf`);
    } catch (error) {
      console.error('PDF Generation failed', error);
      alert('حدث خطأ أثناء إنشاء التقرير. يرجى المحاولة مرة أخرى.');
    } finally {
      setIsGenerating(false);
    }
  };

  const total = expenses.reduce((acc, curr) => acc + curr.amount, 0);

  return (
    <div className="space-y-6 pb-10">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1 flex items-center gap-1">
            <Calendar size={12} />
            من تاريخ
          </label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={fromDate}
            onChange={(e) => setFromDate(e.target.value)}
          />
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1 flex items-center gap-1">
            <Calendar size={12} />
            إلى تاريخ
          </label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={toDate}
            onChange={(e) => setToDate(e.target.value)}
          />
        </div>
      </div>

      <div className="flex gap-2 overflow-x-auto no-scrollbar py-1">
        <button 
          onClick={() => setSelectedCategoryId('all')}
          className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === 'all' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
        >
          الكل
        </button>
        {categories.map(cat => (
          <button 
            key={cat.id}
            onClick={() => setSelectedCategoryId(cat.id)}
            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === cat.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
          >
            {cat.name}
          </button>
        ))}
      </div>

      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white flex justify-between items-center">
        <div>
          <p className="text-blue-100 text-sm mb-1 font-medium">الإجمالي الحالي</p>
          <h3 className="text-2xl font-bold tabular-nums">{total.toLocaleString('ar-SA')} ريال</h3>
        </div>
        <div className="p-3 bg-white/20 rounded-2xl">
          <TrendingUp size={24} />
        </div>
      </div>

      <div className="flex justify-between items-center">
        <h4 className="font-bold text-slate-400">سجل المصروفات</h4>
        <div className="flex gap-2">
          <button 
            disabled={expenses.length === 0 || isGenerating}
            onClick={generatePDF}
            className={`px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 transition-all active:scale-95 ${isGenerating ? 'bg-slate-800 text-slate-500 cursor-not-allowed' : 'bg-green-600 text-white hover:bg-green-700 shadow-lg shadow-green-900/20'}`}
          >
            {isGenerating ? (
              <Loader2 size={16} className="animate-spin" />
            ) : (
              <FileDown size={16} />
            )}
            <span>تحميل PDF</span>
          </button>
        </div>
      </div>

      <div className="space-y-3">
        {expenses.slice().reverse().map((exp, i) => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div key={exp.id} className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30">
              <div className="flex gap-4 items-center overflow-hidden">
                <div className="w-8 h-8 flex-shrink-0 rounded-lg bg-slate-800 flex items-center justify-center text-[10px] text-slate-500 font-mono">
                  {expenses.length - i}
                </div>
                <div className="overflow-hidden">
                  <p className="font-bold tabular-nums text-slate-200">{exp.amount.toLocaleString('ar-SA')} ريال</p>
                  <p className="text-[10px] text-slate-500 mt-0.5 truncate">{exp.date} • {cat?.name || 'عام'}</p>
                </div>
              </div>
              {exp.notes && (
                <div className="text-[10px] px-2 py-1 bg-blue-500/10 text-blue-400 rounded-lg max-w-[100px] truncate ml-2">
                  {exp.notes}
                </div>
              )}
            </div>
          );
        })}
        {expenses.length === 0 && (
          <div className="text-center py-20 text-slate-600 flex flex-col items-center gap-4">
            <BarChart3 size={48} className="opacity-10" />
            <p className="font-medium">لا توجد مصروفات في هذه الفترة</p>
          </div>
        )}
      </div>

      {/* قالب الـ PDF التفصيلي - مخفي */}
      <div 
        ref={reportRef} 
        dir="rtl"
        style={{ 
          display: 'none', 
          width: '210mm', 
          padding: '20mm', 
          backgroundColor: 'white', 
          color: 'black',
          fontFamily: "'Tajawal', sans-serif"
        }}
      >
        {/* هيدر التقرير */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', borderBottom: '2px solid #3b82f6', paddingBottom: '20px', marginBottom: '20px' }}>
          <div>
            <h1 style={{ margin: 0, color: '#3b82f6', fontSize: '28px', fontWeight: 'bold' }}>كشف مصروفات تفصيلي</h1>
            <p style={{ margin: '5px 0 0 0', color: '#64748b', fontSize: '12px' }}>تم الاستخراج من تطبيق "صرف" بتاريخ: {new Date().toLocaleDateString('ar-SA')}</p>
          </div>
          <div style={{ textAlign: 'left' }}>
            <p style={{ margin: 0, fontWeight: 'bold', fontSize: '14px' }}>الفترة الزمنية:</p>
            <p style={{ margin: 0, fontSize: '12px', color: '#1e293b' }}>من: {fromDate}</p>
            <p style={{ margin: 0, fontSize: '12px', color: '#1e293b' }}>إلى: {toDate}</p>
          </div>
        </div>

        {/* جدول العمليات المرتب */}
        <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '30px' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={{ padding: '12px', textAlign: 'center', border: '1px solid #e2e8f0', fontSize: '12px' }}>#</th>
              <th style={{ padding: '12px', textAlign: 'right', border: '1px solid #e2e8f0', fontSize: '12px' }}>التاريخ</th>
              <th style={{ padding: '12px', textAlign: 'right', border: '1px solid #e2e8f0', fontSize: '12px' }}>القسم</th>
              <th style={{ padding: '12px', textAlign: 'right', border: '1px solid #e2e8f0', fontSize: '12px' }}>الملاحظات</th>
              <th style={{ padding: '12px', textAlign: 'center', border: '1px solid #e2e8f0', fontSize: '12px' }}>المستند</th>
              <th style={{ padding: '12px', textAlign: 'left', border: '1px solid #e2e8f0', fontSize: '12px' }}>المبلغ</th>
            </tr>
          </thead>
          <tbody>
            {expenses.map((exp, idx) => {
              const cat = categories.find(c => c.id === exp.categoryId);
              return (
                <tr key={exp.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                  <td style={{ padding: '10px', textAlign: 'center', fontSize: '11px', border: '1px solid #e2e8f0' }}>{idx + 1}</td>
                  <td style={{ padding: '10px', textAlign: 'right', fontSize: '11px', border: '1px solid #e2e8f0', whiteSpace: 'nowrap' }}>{exp.date}</td>
                  <td style={{ padding: '10px', textAlign: 'right', fontSize: '11px', border: '1px solid #e2e8f0' }}>{cat?.name || 'عام'}</td>
                  <td style={{ padding: '10px', textAlign: 'right', fontSize: '10px', border: '1px solid #e2e8f0', maxWidth: '200px', wordBreak: 'break-word' }}>{exp.notes || '-'}</td>
                  <td style={{ padding: '5px', textAlign: 'center', border: '1px solid #e2e8f0' }}>
                    {exp.image ? (
                      <img 
                        src={exp.image} 
                        style={{ width: '45px', height: '45px', objectFit: 'cover', borderRadius: '4px', border: '1px solid #e2e8f0' }} 
                        alt="receipt"
                      />
                    ) : (
                      <span style={{ color: '#cbd5e1', fontSize: '9px' }}>لا يوجد</span>
                    )}
                  </td>
                  <td style={{ padding: '10px', textAlign: 'left', fontSize: '12px', fontWeight: 'bold', border: '1px solid #e2e8f0' }}>{exp.amount.toLocaleString('ar-SA')} ر.س</td>
                </tr>
              );
            })}
          </tbody>
        </table>

        {/* الإجمالي النهائي في الأسفل كما طلب المستخدم */}
        <div style={{ display: 'flex', justifyContent: 'flex-start', alignItems: 'center', marginTop: '40px', borderTop: '2px dashed #3b82f6', paddingTop: '20px' }}>
          <div style={{ backgroundColor: '#eff6ff', padding: '20px 40px', borderRadius: '15px', border: '1px solid #bfdbfe' }}>
            <p style={{ margin: '0 0 5px 0', fontSize: '14px', color: '#1e40af', fontWeight: 'bold' }}>إجمالي المصروفات للفترة:</p>
            <h2 style={{ margin: 0, fontSize: '32px', fontWeight: 'bold', color: '#1e3a8a' }}>{total.toLocaleString('ar-SA')} ريال سعودي</h2>
            <p style={{ margin: '10px 0 0 0', fontSize: '12px', color: '#64748b' }}>إجمالي عدد العمليات: {expenses.length}</p>
          </div>
        </div>

        {/* الفوتر */}
        <div style={{ marginTop: 'auto', paddingTop: '50px', textAlign: 'center' }}>
          <p style={{ fontSize: '10px', color: '#94a3b8' }}>تم استخراج هذا التقرير آلياً عبر نظام "صرف".</p>
        </div>
      </div>
    </div>
  );
};

