import { Dexie } from 'dexie';
import type { Table } from 'dexie';
import { Category, Expense, AppSettings } from './types';

// Define the database class extending Dexie
// Standardizing inheritance by using named import and constructor-based configuration
// to resolve TypeScript error where 'version' was not recognized.
export class SarfDB extends Dexie {
  categories!: Table<Category>;
  expenses!: Table<Expense>;
  settings!: Table<AppSettings>;

  constructor() {
    super('SarfDB');
    // Define the schema inside the constructor as recommended for Dexie with TypeScript.
    this.version(2).stores({
      categories: 'id, name, order',
      expenses: 'id, categoryId, date, createdAt',
      settings: '' 
    });
  }
}

export const db = new SarfDB();

export async function initializeDb() {
  const count = await db.categories.count();
  if (count === 0) {
    await db.categories.add({
      id: 'default_general',
      name: 'عام',
      color: '#3b82f6',
      order: 0,
      isDefault: true
    });
  }

  const settingsCount = await db.settings.count();
  if (settingsCount === 0) {
    await db.settings.put({
      showImages: true,
      showNotes: true
    }, 'app_settings');
  }
}

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Category } from '../types';
import { 
  FolderPlus, 
  Trash2, 
  Phone,
  Plus
} from 'lucide-react';

interface HomeViewProps {
  onAdd: () => void;
  onCategorySelect: (cat: Category) => void;
}

const HomeView: React.FC<HomeViewProps> = ({ onAdd, onCategorySelect }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [categoryTotals, setCategoryTotals] = useState<Record<string, number>>({});
  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryPhone, setNewCategoryPhone] = useState('');
  const [totalExpenses, setTotalExpenses] = useState(0);

  const loadData = async () => {
    const cats = await db.categories.toArray();
    cats.sort((a, b) => a.order - b.order);
    setCategories(cats);

    const expenses = await db.expenses.toArray();
    const totals: Record<string, number> = {};
    let grandTotal = 0;

    expenses.forEach(exp => {
      totals[exp.categoryId] = (totals[exp.categoryId] || 0) + exp.amount;
      grandTotal += exp.amount;
    });

    setCategoryTotals(totals);
    setTotalExpenses(grandTotal);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleAddCategory = async () => {
    if (!newCategoryName.trim()) return;
    const id = Date.now().toString();
    const order = categories.length;

    // تنظيف رقم الهاتف من أي رموز زائدة
    let phone = newCategoryPhone.trim().replace(/\D/g, '');
    // إذا بدأ بصفر، نحذفه لأن المفتاح الدولي سيضاف
    if (phone.startsWith('0')) phone = phone.substring(1);

    await db.categories.add({
      id,
      name: newCategoryName,
      phoneNumber: phone || undefined,
      color: '#3b82f6',
      order
    });
    setNewCategoryName('');
    setNewCategoryPhone('');
    setIsAddingCategory(false);
    loadData();
  };

  const handleDeleteCategory = async (cat: Category) => {
    if (cat.isDefault) {
      alert('لا يمكن حذف القسم العام');
      return;
    }

    const count = await db.expenses.where('categoryId').equals(cat.id).count();
    if (count > 0) {
      const confirmMove = window.confirm(`هذا القسم يحتوي على ${count} مصروفات. هل تريد نقلها للقسم العام وحذف القسم؟`);
      if (confirmMove) {
        await db.expenses.where('categoryId').equals(cat.id).modify({ categoryId: 'default_general' });
        await db.categories.delete(cat.id);
        loadData();
      }
    } else {
      await db.categories.delete(cat.id);
      loadData();
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white text-center">
        <p className="text-blue-100 text-sm mb-1 font-medium">إجمالي المصاريف</p>
        <h2 className="text-4xl font-bold mb-2 tabular-nums">
          {totalExpenses.toLocaleString('ar-SA')} 
          <span className="text-lg mr-2 opacity-80">ريال</span>
        </h2>
      </div>

      <div className="flex justify-between items-center px-1">
        <h3 className="text-lg font-bold text-slate-300">الأقسام</h3>
        <button 
          onClick={() => setIsAddingCategory(true)}
          className="text-blue-500 hover:bg-blue-500/10 p-2 rounded-full transition-colors flex items-center gap-1"
        >
          <FolderPlus size={20} />
          <span className="text-sm font-medium">قسم جديد</span>
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {categories.map((cat) => (
          <div 
            key={cat.id}
            className="bg-slate-900 border border-slate-800 rounded-2xl p-4 active:scale-95 transition-transform group relative cursor-pointer flex flex-col justify-between h-full"
            onClick={() => onCategorySelect(cat)}
          >
            <div>
              <div className="flex justify-between items-start mb-2">
                <div 
                  className="w-3 h-3 rounded-full mt-1" 
                  style={{ backgroundColor: cat.color }} 
                />
                {!cat.isDefault && (
                  <button 
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteCategory(cat);
                    }}
                    className="text-slate-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <Trash2 size={16} />
                  </button>
                )}
              </div>
              <h4 className="font-bold text-slate-200 truncate">{cat.name}</h4>
              {cat.phoneNumber && (
                <div className="flex items-center gap-1 text-[10px] text-slate-500 mt-1">
                  <Phone size={10} />
                  <span dir="ltr">+967 {cat.phoneNumber}</span>
                </div>
              )}
            </div>
            <p className="text-blue-400 font-bold text-sm mt-3 tabular-nums">
              {categoryTotals[cat.id] ? categoryTotals[cat.id].toLocaleString('ar-SA') : '٠'} ريال
            </p>
          </div>
        ))}
      </div>

      {isAddingCategory && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 w-full rounded-2xl p-6 shadow-2xl space-y-4">
            <h3 className="text-xl font-bold">إضافة قسم جديد</h3>

            <div className="space-y-3">
              <div>
                <label className="text-xs text-slate-500 block mb-1">اسم القسم</label>
                <input 
                  autoFocus
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                  placeholder="مثال: بقالة، كهرباء..."
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                />
              </div>

              <div>
                <label className="text-xs text-slate-500 block mb-1">رقم الهاتف (اختياري)</label>
                <div className="relative">
                  <span className="absolute left-4 top-3.5 text-slate-500 text-sm font-bold" dir="ltr">+967</span>
                  <input 
                    type="tel"
                    className="w-full bg-slate-800 border border-slate-700 rounded-xl pl-16 pr-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none tabular-nums"
                    placeholder="7xxxxxxxx"
                    value={newCategoryPhone}
                    onChange={(e) => setNewCategoryPhone(e.target.value)}
                  />
                </div>
                <p className="text-[10px] text-slate-600 mt-1">سيتم استخدام هذا الرقم لمشاركة التقارير عبر واتساب</p>
              </div>
            </div>

            <div className="flex gap-3 pt-2">
              <button 
                onClick={handleAddCategory}
                className="flex-grow bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 transition-colors"
              >
                إضافة
              </button>
              <button 
                onClick={() => setIsAddingCategory(false)}
                className="flex-grow bg-slate-800 text-slate-300 font-bold py-3 rounded-xl hover:bg-slate-700 transition-colors"
              >
                إلغاء
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HomeView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { 
  FileDown, 
  TrendingUp,
  BarChart3,
  Loader2,
  Calendar,
  MessageCircle
} from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

const ReportsView: React.FC = () => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [sortBy, setSortBy] = useState<'date' | 'amount'>('date');
  const [isGenerating, setIsGenerating] = useState(false);

  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);

      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();

      if (selectedCategoryId !== 'all') {
        results = results.filter(e => e.categoryId === selectedCategoryId);
      }

      if (sortBy === 'date') {
        results.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
      } else {
        results.sort((a, b) => a.amount - b.amount);
      }

      setExpenses(results);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId, sortBy]);

  const generatePDF = async () => {
    if (expenses.length === 0 || isGenerating) return;

    setIsGenerating(true);
    try {
      const element = reportRef.current;
      if (!element) return;

      element.style.display = 'block';
      element.style.visibility = 'visible';
      element.style.position = 'fixed';
      element.style.top = '0';
      element.style.left = '0';
      element.style.zIndex = '-9999';

      await new Promise(resolve => setTimeout(resolve, 1500));

      const canvas = await html2canvas(element, {
        scale: 2.5,
        useCORS: true,
        allowTaint: true,
        backgroundColor: '#ffffff',
        logging: false,
      });

      element.style.display = 'none';

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4'
      });

      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`كشف_صرف_${fromDate}_إلى_${toDate}.pdf`);
      return true;
    } catch (error) {
      console.error('PDF Generation failed', error);
      alert('حدث خطأ أثناء إنشاء التقرير.');
      return false;
    } finally {
      setIsGenerating(false);
    }
  };

  const shareViaWhatsApp = () => {
    const category = categories.find(c => c.id === selectedCategoryId);
