import { Dexie, type Table } from 'dexie';
import { Category, Expense, AppSettings } from './types';

// Define the database class extending Dexie
// Using the named import for Dexie is the most compatible way to ensure 
// inherited methods like 'version' are correctly recognized by the TypeScript compiler.
export class SarfDB extends Dexie {
  categories!: Table<Category>;
  expenses!: Table<Expense>;
  settings!: Table<AppSettings>;

  constructor() {
    super('SarfDB');
    // Define the schema inside the constructor as recommended for Dexie with TypeScript.
    // Using this.version() to define the database version and schema.
    this.version(2).stores({
      categories: 'id, name, order',
      expenses: 'id, categoryId, date, createdAt',
      settings: '' 
    });
  }
}

export const db = new SarfDB();

export async function initializeDb() {
  const count = await db.categories.count();
  if (count === 0) {
    await db.categories.add({
      id: 'default_general',
      name: 'عام',
      color: '#3b82f6',
      order: 0,
      isDefault: true
    });
  }

  const settingsCount = await db.settings.count();
  if (settingsCount === 0) {
    await db.settings.put({
      showImages: true,
      showNotes: true
    }, 'app_settings');
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { 
  FileDown, 
  TrendingUp,
  BarChart3,
  Loader2,
  Calendar,
  MessageCircle,
  ChevronRight
} from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface ReportsViewProps {
  onExpenseSelect?: (exp: Expense) => void;
}

const ReportsView: React.FC<ReportsViewProps> = ({ onExpenseSelect }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [sortBy, setSortBy] = useState<'date' | 'amount'>('date');
  const [isGenerating, setIsGenerating] = useState(false);

  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);

      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();

      if (selectedCategoryId !== 'all') {
        results = results.filter(e => e.categoryId === selectedCategoryId);
      }

      if (sortBy === 'date') {
        results.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
      } else {
        results.sort((a, b) => a.amount - b.amount);
      }

      setExpenses(results);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId, sortBy]);

  const generatePDF = async () => {
    if (expenses.length === 0 || isGenerating) return;

    setIsGenerating(true);
    try {
      const element = reportRef.current;
      if (!element) return;

      element.style.display = 'block';
      element.style.visibility = 'visible';
      element.style.position = 'fixed';
      element.style.top = '0';
      element.style.left = '0';
      element.style.zIndex = '-9999';

      await new Promise(resolve => setTimeout(resolve, 1500));

      const canvas = await html2canvas(element, {
        scale: 2.5,
        useCORS: true,
        allowTaint: true,
        backgroundColor: '#ffffff',
        logging: false,
      });

      element.style.display = 'none';

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4'
      });

      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`كشف_صرف_${fromDate}_إلى_${toDate}.pdf`);
      return true;
    } catch (error) {
      console.error('PDF Generation failed', error);
      alert('حدث خطأ أثناء إنشاء التقرير.');
      return false;
    } finally {
      setIsGenerating(false);
    }
  };

  const shareViaWhatsApp = () => {
    const category = categories.find(c => c.id === selectedCategoryId);
    if (!category || !category.phoneNumber) {
      alert('يجب اختيار قسم يحتوي على رقم هاتف مفعل لاستخدام هذه الميزة');
      return;
    }

    const total = expenses.reduce((acc, curr) => acc + curr.amount, 0);
    const message = `*كشف مصروفات - تطبيق صرف*\n\nالقسم: ${category.name}\nالفترة: من ${fromDate} إلى ${toDate}\nإجمالي المصروفات: ${total.toLocaleString('ar-SA')} ريال\nعدد العمليات: ${expenses.length}\n\n_تم الإرسال عبر تطبيق صرف_`;

    const whatsappUrl = `https://wa.me/967${category.phoneNumber}?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');

    setTimeout(() => {
      alert('سيتم فتح واتساب الآن. يرجى إرسال الرسالة ثم إرفاق ملف الـ PDF يدوياً من جهازك.');
    }, 500);
  };

  const total = expenses.reduce((acc, curr) => acc + curr.amount, 0);

  return (
    <div className="space-y-6 pb-10">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1 flex items-center gap-1">
            <Calendar size={12} />
            من تاريخ
          </label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={fromDate}
            onChange={(e) => setFromDate(e.target.value)}
          />
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1 flex items-center gap-1">
            <Calendar size={12} />
            إلى تاريخ
          </label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={toDate}
            onChange={(e) => setToDate(e.target.value)}
          />
        </div>
      </div>

      <div className="flex gap-2 overflow-x-auto no-scrollbar py-1">
        <button 
          onClick={() => setSelectedCategoryId('all')}
          className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === 'all' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
        >
          الكل
        </button>
        {categories.map(cat => (
          <button 
            key={cat.id}
            onClick={() => setSelectedCategoryId(cat.id)}
            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === cat.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
