            <h1 style={{ margin: 0, color: '#3b82f6', fontSize: '28px', fontWeight: 'bold' }}>كشف مصروفات تفصيلي</h1>
            <p style={{ margin: '5px 0 0 0', color: '#64748b', fontSize: '12px' }}>تم الاستخراج من تطبيق "صرف" بتاريخ: {new Date().toLocaleDateString('ar-SA')}</p>
