import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Category } from '../types';
import { 
  FolderPlus, 
  Trash2, 
  Phone,
  Search,
  X,
  Edit2,
  Check
} from 'lucide-react';

interface HomeViewProps {
  onAdd: () => void;
  onCategorySelect: (cat: Category) => void;
}

const PREDEFINED_COLORS = [
  '#3b82f6', // Blue
  '#6366f1', // Indigo
  '#a855f7', // Purple
  '#ec4899', // Pink
  '#ef4444', // Red
  '#f97316', // Orange
  '#f59e0b', // Amber
  '#22c55e', // Green
  '#10b981', // Emerald
  '#14b8a6', // Teal
  '#06b6d4', // Cyan
  '#0ea5e9', // Sky
];

const HomeView: React.FC<HomeViewProps> = ({ onAdd, onCategorySelect }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [categoryTotals, setCategoryTotals] = useState<Record<string, number>>({});
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);

  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryPhone, setNewCategoryPhone] = useState('');
  const [newCategoryColor, setNewCategoryColor] = useState(PREDEFINED_COLORS[0]);

  const [totalExpenses, setTotalExpenses] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');

  const loadData = async () => {
    const cats = await db.categories.toArray();
    cats.sort((a, b) => a.order - b.order);
    setCategories(cats);

    const expenses = await db.expenses.toArray();
    const totals: Record<string, number> = {};
    let grandTotal = 0;

    expenses.forEach(exp => {
      totals[exp.categoryId] = (totals[exp.categoryId] || 0) + exp.amount;
      grandTotal += exp.amount;
    });

    setCategoryTotals(totals);
    setTotalExpenses(grandTotal);
  };

  useEffect(() => {
    loadData();
  }, []);

  const openAddModal = () => {
    setEditingCategory(null);
    setNewCategoryName('');
    setNewCategoryPhone('');
    setNewCategoryColor(PREDEFINED_COLORS[0]);
    setIsModalOpen(true);
  };

  const openEditModal = (cat: Category, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingCategory(cat);
    setNewCategoryName(cat.name);
    setNewCategoryPhone(cat.phoneNumber || '');
    setNewCategoryColor(cat.color);
    setIsModalOpen(true);
  };

  const handleSaveCategory = async () => {
    if (!newCategoryName.trim()) return;

    let phone = newCategoryPhone.trim().replace(/\D/g, '');
    if (phone.startsWith('0')) phone = phone.substring(1);

    if (editingCategory) {
      await db.categories.update(editingCategory.id, {
        name: newCategoryName,
        phoneNumber: phone || undefined,
        color: newCategoryColor
      });
    } else {
      const id = Date.now().toString();
      const order = categories.length;
      await db.categories.add({
        id,
        name: newCategoryName,
        phoneNumber: phone || undefined,
        color: newCategoryColor,
        order
      });
    }

    setIsModalOpen(false);
    loadData();
  };

  const handleDeleteCategory = async (cat: Category, e: React.MouseEvent) => {
    e.stopPropagation();
    if (cat.isDefault) {
      alert('لا يمكن حذف القسم العام');
      return;
    }

    const count = await db.expenses.where('categoryId').equals(cat.id).count();
    if (count > 0) {
      const confirmMove = window.confirm(`هذا القسم يحتوي على ${count} مصروفات. هل تريد نقلها للقسم العام وحذف القسم؟`);
      if (confirmMove) {
        await db.expenses.where('categoryId').equals(cat.id).modify({ categoryId: 'default_general' });
        await db.categories.delete(cat.id);
        loadData();
      }
    } else {
      await db.categories.delete(cat.id);
      loadData();
    }
  };

  const filteredCategories = categories.filter(cat => 
    cat.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white text-center">
        <p className="text-blue-100 text-sm mb-1 font-medium">إجمالي المصاريف</p>
        <h2 className="text-4xl font-bold mb-2 tabular-nums">
          {totalExpenses.toLocaleString('ar-SA')} 
          <span className="text-lg mr-2 opacity-80">ريال يمني</span>
        </h2>
      </div>

      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18} />
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-10 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
          placeholder="بحث عن قسم..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
        {searchQuery && (
          <button 
            onClick={() => setSearchQuery('')}
            className="absolute left-3 top-3.5 text-slate-500 hover:text-white"
          >
            <X size={18} />
          </button>
        )}
      </div>

      <div className="flex justify-between items-center px-1">
        <h3 className="text-lg font-bold text-slate-300">الأقسام</h3>
        <button 
          onClick={openAddModal}
          className="text-blue-500 hover:bg-blue-500/10 p-2 rounded-full transition-colors flex items-center gap-1"
        >
          <FolderPlus size={20} />
          <span className="text-sm font-medium">قسم جديد</span>
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {filteredCategories.map((cat) => (
          <div 
            key={cat.id}
            className="bg-slate-900 border border-slate-800 rounded-2xl p-4 active:scale-95 transition-transform group relative cursor-pointer flex flex-col justify-between h-40"
            onClick={() => onCategorySelect(cat)}
            style={{ borderRight: `4px solid ${cat.color}` }}
          >
            <div>
              <div className="flex justify-between items-start mb-2">
                <div 
                  className="w-3 h-3 rounded-full mt-1" 
                  style={{ backgroundColor: cat.color }} 
                />
                {!cat.isDefault && (
                  <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button 
                      onClick={(e) => openEditModal(cat, e)}
                      className="text-slate-500 hover:text-blue-400"
                    >
                      <Edit2 size={16} />
                    </button>
                    <button 
                      onClick={(e) => handleDeleteCategory(cat, e)}
                      className="text-slate-500 hover:text-red-400"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                )}
              </div>
              <h4 className="font-bold text-slate-200 truncate">{cat.name}</h4>
              {cat.phoneNumber && (
                <div className="flex items-center gap-1 text-[10px] text-slate-500 mt-1">
                  <Phone size={10} />
                  <span dir="ltr">+967 {cat.phoneNumber}</span>
                </div>
              )}
            </div>
            <p className="text-blue-400 font-bold text-sm mt-auto tabular-nums text-right">
              {categoryTotals[cat.id] ? categoryTotals[cat.id].toLocaleString('ar-SA') : '٠'} <span className="text-[10px]">ر.ي</span>
            </p>
          </div>
        ))}
        {filteredCategories.length === 0 && searchQuery && (
          <div className="col-span-2 text-center py-10 text-slate-600">
            لا توجد أقسام تطابق بحثك
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 w-full rounded-2xl p-6 shadow-2xl space-y-4 max-h-[90vh] overflow-y-auto">
            <h3 className="text-xl font-bold">{editingCategory ? 'تعديل قسم' : 'إضافة قسم جديد'}</h3>

            <div className="space-y-4">
              <div>
                <label className="text-xs text-slate-500 block mb-1">اسم القسم</label>
                <input 
                  autoFocus
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                  placeholder="مثال: بقالة، كهرباء..."
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                />
              </div>

              <div>
                <label className="text-xs text-slate-500 block mb-1">رقم الهاتف (اختياري)</label>
                <div className="relative">
                  <span className="absolute left-4 top-3.5 text-slate-500 text-sm font-bold" dir="ltr">+967</span>
                  <input 
                    type="tel"
                    className="w-full bg-slate-800 border border-slate-700 rounded-xl pl-16 pr-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none tabular-nums"
                    placeholder="7xxxxxxxx"
                    value={newCategoryPhone}
                    onChange={(e) => setNewCategoryPhone(e.target.value)}
                  />
                </div>
              </div>

              <div>
                <label className="text-xs text-slate-500 block mb-2">لون القسم</label>
                <div className="grid grid-cols-6 gap-2">
                  {PREDEFINED_COLORS.map(color => (
                    <button
                      key={color}
                      onClick={() => setNewCategoryColor(color)}
                      className={`w-full aspect-square rounded-full flex items-center justify-center transition-all ${newCategoryColor === color ? 'ring-4 ring-white ring-offset-2 ring-offset-slate-900 scale-110' : 'hover:scale-105'}`}
                      style={{ backgroundColor: color }}
                    >
                      {newCategoryColor === color && <Check size={16} className="text-white drop-shadow-md" />}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="flex gap-3 pt-4">
              <button 
                onClick={handleSaveCategory}
                className="flex-grow bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 transition-colors shadow-lg shadow-blue-900/40"
              >
                {editingCategory ? 'تحديث' : 'إضافة'}
              </button>
              <button 
                onClick={() => setIsModalOpen(false)}
                className="flex-grow bg-slate-800 text-slate-300 font-bold py-3 rounded-xl hover:bg-slate-700 transition-colors"
              >
                إلغاء
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

