  categoryId: string;
  amount: number;
  date: string;
  notes?: string;
  image?: string; // base64
  createdAt: number;
  serialNumber?: number; // رقم تسلسلي (SRF-1)
}

export interface DraftExpense {
  id: string;
  categoryName: string;
  amount: number;
  notes: string;
  date: string;
}

export interface RecurringReminder {
  id: string;
  title: string;
  amount: number;
  categoryId: string;
