import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { AppSettings, RecurringReminder, Category, DraftExpense, Expense } from '../types';
import { 
  Eye, 
  Download, 
  Upload, 
  Palette,
  Trash2,
  Bell,
  Plus,
  X,
  Calendar,
  Tag,
  Wand2,
  CheckCircle2,
  AlertCircle,
  FileSearch
} from 'lucide-react';
import ConfirmModal from './ConfirmModal';

interface SettingsViewProps {
  onUpdateSettings: (s: AppSettings) => void;
}

const SettingsView: React.FC<SettingsViewProps> = ({ onUpdateSettings }) => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [reminders, setReminders] = useState<RecurringReminder[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [drafts, setDrafts] = useState<DraftExpense[]>([]);

  const [isAddingReminder, setIsAddingReminder] = useState(false);
  const [isSortingActive, setIsSortingActive] = useState(false);
  const [rawText, setRawText] = useState('');

  // Confirmation state
  const [confirmData, setConfirmData] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void } | null>(null);

  // New reminder form state
  const [newReminderTitle, setNewReminderTitle] = useState('');
  const [newReminderAmount, setNewReminderAmount] = useState('');
  const [newReminderCategory, setNewReminderCategory] = useState('default_general');
  const [newReminderDay, setNewReminderDay] = useState('1');

  useEffect(() => {
    db.settings.get('app_settings').then(s => {
      if (s) setSettings(s);
    });
    loadData();
  }, []);

  const loadData = async () => {
    const r = await db.reminders.toArray();
    setReminders(r);
    const d = await db.drafts.toArray();
    setDrafts(d);
    const c = await db.categories.toArray();
    setCategories(c);
  };

  const handleParseText = async () => {
    if (!rawText.trim()) return;

    const regex = /\*([^*]+)\*\s*\*([\d.]+)\*\s*\*([^*]+)\*/g;
    let match;
    const newDrafts: DraftExpense[] = [];

    while ((match = regex.exec(rawText)) !== null) {
      newDrafts.push({
        id: Math.random().toString(36).substr(2, 9),
        categoryName: match[1].trim(),
        amount: parseFloat(match[2]),
        notes: match[3].trim(),
        date: new Date().toISOString().split('T')[0]
      });
    }

    if (newDrafts.length > 0) {
      await db.drafts.bulkAdd(newDrafts);
      setRawText('');
      setIsSortingActive(false);
      loadData();
    } else {
      alert('لم يتم العثور على بيانات صالحة للفرز. تأكد من الصيغة: *القسم* *المبلغ* *الملاحظة*');
    }
  };

  const confirmDraft = async (draft: DraftExpense) => {
    let cat = categories.find(c => c.name === draft.categoryName);
    if (!cat) {
      cat = categories.find(c => c.isDefault) || categories[0];
    }

    const allExpenses = await db.expenses.toArray();
    const maxSerial = allExpenses.reduce((max, exp) => Math.max(max, exp.serialNumber || 0), 0);

    const newExpense: Expense = {
      id: Date.now().toString() + Math.random().toString(36).substr(2, 5),
      categoryId: cat.id,
      amount: draft.amount,
      notes: draft.notes,
      date: draft.date,
      createdAt: Date.now(),
      serialNumber: maxSerial + 1
    };

    await db.expenses.add(newExpense);
    await db.drafts.delete(draft.id);
    loadData();
  };

  const initiateDeleteReminder = (id: string, title: string) => {
    setConfirmData({
      isOpen: true,
      title: "حذف تذكير",
      message: `هل أنت متأكد من حذف تذكير "${title}"؟`,
      onConfirm: async () => {
        await db.reminders.delete(id);
        setConfirmData(null);
        loadData();
      }
    });
  };

  const initiateClearData = () => {
    setConfirmData({
      isOpen: true,
      title: "مسح جميع البيانات",
      message: "تنبيه هام: سيتم حذف كافة المصروفات المسجلة نهائياً. هل أنت متأكد؟",
      onConfirm: async () => {
        await db.expenses.clear();
        await db.drafts.clear();
        setConfirmData(null);
        window.location.reload();
      }
    });
  };

  const updateSetting = async (key: keyof AppSettings, value: any) => {
    if (!settings) return;
    const newSettings = { ...settings, [key]: value };
    await db.settings.put(newSettings, 'app_settings');
    setSettings(newSettings);
    onUpdateSettings(newSettings);
  };

  const handleAddReminder = async () => {
    if (!newReminderTitle.trim() || !newReminderAmount) return;

    const reminder: RecurringReminder = {
      id: Date.now().toString(),
      title: newReminderTitle,
      amount: parseFloat(newReminderAmount),
      categoryId: newReminderCategory,
      dayOfMonth: parseInt(newReminderDay)
    };

    await db.reminders.add(reminder);
    setNewReminderTitle('');
    setNewReminderAmount('');
    setIsAddingReminder(false);
    loadData();
  };

  const exportData = async () => {
    const cats = await db.categories.toArray();
    const exps = await db.expenses.toArray();
    const sets = await db.settings.get('app_settings');
    const rems = await db.reminders.toArray();

    const data = JSON.stringify({ cats, exps, sets, rems });
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `sarf_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        setConfirmData({
          isOpen: true,
          title: "استيراد بيانات",
          message: "سيتم مسح البيانات الحالية واستبدالها بالنسخة الاحتياطية. هل أنت متأكد؟",
          onConfirm: async () => {
            await db.categories.clear();
            await db.expenses.clear();
            await db.reminders.clear();
            await db.drafts.clear();
            await db.categories.bulkAdd(data.cats);
            await db.expenses.bulkAdd(data.exps);
            if (data.rems) await db.reminders.bulkAdd(data.rems);
            setConfirmData(null);
            window.location.reload();
          }
        });
      } catch (err) {
        alert('خطأ في ملف النسخة الاحتياطية');
      }
    };
    reader.readAsText(file);
  };

  if (!settings) return null;

  return (
