            </div>
            <div className="divide-y divide-amber-500/10">
              {drafts.map(draft => (
                <div key={draft.id} className="p-4 flex justify-between items-center group hover:bg-amber-500/5 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-amber-500/10 flex items-center justify-center text-amber-500 border border-amber-500/20">
                      <span className="text-[10px] font-bold">DRAFT</span>
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                         <span className="font-bold text-sm text-slate-200">{draft.amount.toLocaleString()} ر.ي</span>
