                </select>
                <select 
                  className="bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 text-xs"
                  value={newReminderCategory}
                  onChange={(e) => setNewReminderCategory(e.target.value)}
