                  {categories.map(cat => (
                    <option key={cat.id} value={cat.id}>{cat.name}</option>
                  ))}
                </select>
              </div>
            </div>
            <button 
              onClick={handleAddReminder}
              className="w-full bg-blue-600 text-white font-bold py-4 rounded-2xl shadow-lg shadow-blue-900/40 active:scale-95 transition-all mt-4"
            >
              حفظ المصروف الدوري
