const CACHE_NAME = 'sarf-cache-v2';
const urlsToCache = [
  './',
  './index.html',
  'https://cdn.tailwindcss.com',
  'https://fonts.googleapis.com/css2?family=Tajawal:wght@300;400;500;700&display=swap'
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => cache.addAll(urlsToCache))
  );
});

self.addEventListener('fetch', event => {
  event.respondWith(
    caches.match(event.request)
      .then(response => {
        if (response) return response;
        return fetch(event.request);
      })
  );
});

import React, { useState, useEffect } from 'react';
import { db, initializeDb } from './db';
import { ViewState, Category, Expense, AppSettings } from './types';
import { Plus, Home, PieChart, Settings as SettingsIcon } from 'lucide-react';

import HomeView from './components/HomeView';
import AddExpenseView from './components/AddExpenseView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import CategoryDetailView from './components/CategoryDetailView';
import ExpenseDetailView from './components/ExpenseDetailView';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [editingExpense, setEditingExpense] = useState<Expense | null>(null);
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [initialized, setInitialized] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const init = async () => {
      await initializeDb();
      const s = await db.settings.get('app_settings');
      if (s) setSettings(s);
      setInitialized(true);
    };
    init();

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  if (!initialized || !settings) return <div className="min-h-screen bg-slate-950 flex items-center justify-center text-white font-bold">جاري تحميل صرف...</div>;

  const renderView = () => {
    switch (currentView) {
      case ViewState.HOME:
        return <HomeView onAdd={() => setCurrentView(ViewState.ADD_EXPENSE)} onCategorySelect={(cat) => { setSelectedCategory(cat); setCurrentView(ViewState.CATEGORY_DETAIL); }} />;
      case ViewState.ADD_EXPENSE:
        return <AddExpenseView onClose={() => { setEditingExpense(null); setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.HOME); }} initialData={editingExpense} preselectedCategoryId={selectedCategory?.id} />;
      case ViewState.REPORTS:
        return <ReportsView onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} />;
      case ViewState.SETTINGS:
        return <SettingsView onUpdateSettings={setSettings} installPrompt={deferredPrompt} onInstallSuccess={() => setDeferredPrompt(null)} />;
      case ViewState.CATEGORY_DETAIL:
        return selectedCategory ? <CategoryDetailView category={selectedCategory} onBack={() => { setSelectedCategory(null); setCurrentView(ViewState.HOME); }} onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} onAddExpense={() => { setEditingExpense(null); setCurrentView(ViewState.ADD_EXPENSE); }} /> : null;
      case ViewState.EXPENSE_DETAIL:
        return selectedExpense ? <ExpenseDetailView expense={selectedExpense} onBack={() => setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.REPORTS)} onEdit={(exp) => { setEditingExpense(exp); setCurrentView(ViewState.ADD_EXPENSE); }} /> : null;
      default:
        return <HomeView onAdd={() => setCurrentView(ViewState.ADD_EXPENSE)} onCategorySelect={(cat) => { setSelectedCategory(cat); setCurrentView(ViewState.CATEGORY_DETAIL); }} />;
    }
  };

  return (
    <div className="min-h-screen pb-20 max-w-md mx-auto bg-slate-950 text-slate-100 flex flex-col relative shadow-2xl overflow-x-hidden">
      <header className="p-4 flex justify-between items-center border-b border-slate-800 sticky top-0 bg-slate-950/80 backdrop-blur-md z-40">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-white shadow-lg shadow-blue-900/40">ص</div>
          <h1 className="text-2xl font-bold bg-gradient-to-l from-blue-400 to-blue-600 bg-clip-text text-transparent">صرف</h1>
        </div>
      </header>
      <main className="flex-grow p-4 overflow-y-auto">{renderView()}</main>
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-slate-900 border-t border-slate-800 flex justify-around p-3 z-50 rounded-t-3xl shadow-2xl">
        <button onClick={() => { setSelectedCategory(null); setCurrentView(ViewState.HOME); }} className={`flex flex-col items-center gap-1 transition-colors ${currentView === ViewState.HOME || currentView === ViewState.CATEGORY_DETAIL ? 'text-blue-500' : 'text-slate-500'}`}>
          <Home size={22} /><span className="text-[10px] font-bold">الرئيسية</span>
        </button>
        <button onClick={() => { setEditingExpense(null); setCurrentView(ViewState.ADD_EXPENSE); }} className="bg-blue-600 p-4 rounded-full -mt-10 shadow-xl shadow-blue-900/60 text-white active:scale-90 transition-transform ring-4 ring-slate-950">
          <Plus size={28} />
        </button>
        <button onClick={() => setCurrentView(ViewState.REPORTS)} className={`flex flex-col items-center gap-1 transition-colors ${currentView === ViewState.REPORTS ? 'text-blue-500' : 'text-slate-500'}`}>
          <PieChart size={22} /><span className="text-[10px] font-bold">التقارير</span>
        </button>
        <button onClick={() => setCurrentView(ViewState.SETTINGS)} className={`flex flex-col items-center gap-1 transition-colors ${currentView === ViewState.SETTINGS ? 'text-blue-500' : 'text-slate-500'}`}>
          <SettingsIcon size={22} /><span className="text-[10px] font-bold">الإعدادات</span>
        </button>
      </nav>
    </div>
  );
};
export default App;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { FileDown, TrendingUp, Loader2, Calendar, MessageCircle, ChevronRight, Search, X, ExternalLink, Download, FileText, Sparkles, Layers } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface ReportsViewProps { onExpenseSelect?: (exp: Expense) => void; }

const ReportsView: React.FC<ReportsViewProps> = ({ onExpenseSelect }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showPdfMenu, setShowPdfMenu] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusMessage, setStatusMessage] = useState('');
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);
      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();
      if (selectedCategoryId !== 'all') results = results.filter(e => e.categoryId === selectedCategoryId);
      results.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setExpenses(results);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId]);

  const processPDF = async (action: 'download' | 'view') => {
    if (expenses.length === 0 || isGenerating) return;
    setIsGenerating(true); setShowPdfMenu(false); setProgress(10); setStatusMessage('جاري تحضير البيانات...');
    try {
      const element = reportRef.current;
      if (!element) return;
      await new Promise(r => setTimeout(r, 500)); setProgress(40); setStatusMessage('جاري التقاط لقطات عالية الجودة...');
      element.style.display = 'block'; element.style.visibility = 'visible'; element.style.position = 'fixed'; element.style.left = '-10000px';
      const canvas = await html2canvas(element, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
      element.style.display = 'none'; setProgress(80); setStatusMessage('جاري تحويل السندات إلى ملف PDF...');
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      setProgress(100); setStatusMessage('اكتملت العملية!');
      await new Promise(r => setTimeout(r, 500));
      if (action === 'download') pdf.save(`تقرير_صرف_${fromDate}.pdf`);
      else window.open(pdf.output('bloburl'), '_blank');
    } catch (error) { alert('حدث خطأ أثناء معالجة التقرير.'); }
    finally { setIsGenerating(false); setProgress(0); setStatusMessage(''); }
  };

  const shareViaWhatsApp = () => {
    const totalVal = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
    const cat = categories.find(c => c.id === selectedCategoryId);
    const message = `*كشف مصروفات - تطبيق صرف*\nالقسم: ${selectedCategoryId === 'all' ? 'كافة الأقسام' : cat?.name}\nالفترة: من ${fromDate} إلى ${toDate}\nالإجمالي: ${totalVal.toLocaleString()} ر.ي\nعدد العمليات: ${filteredExpenses.length}`;
    window.open(`https://wa.me/${selectedCategoryId !== 'all' && cat?.phoneNumber ? '967' + cat.phoneNumber : ''}?text=${encodeURIComponent(message)}`, '_blank');
  };

  const filteredExpenses = expenses.filter(exp => exp.notes?.toLowerCase().includes(searchQuery.toLowerCase()) || exp.amount.toString().includes(searchQuery));
  const totalAmount = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);

  return (
    <div className="space-y-6 pb-10">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="text-xs text-slate-500 mb-1 flex items-center gap-1"><Calendar size={12}/> من تاريخ</label>
          <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400" value={fromDate} onChange={e => setFromDate(e.target.value)}/>
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="text-xs text-slate-500 mb-1 flex items-center gap-1"><Calendar size={12}/> إلى تاريخ</label>
          <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400" value={toDate} onChange={e => setToDate(e.target.value)}/>
        </div>
      </div>
      <div className="space-y-2">
        <label className="text-xs text-slate-500 px-1 flex items-center gap-1"><Layers size={12}/> تصفية حسب القسم</label>
        <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
          <button onClick={() => setSelectedCategoryId('all')} className={`flex-shrink-0 px-5 py-2 rounded-full border text-sm font-bold transition-all ${selectedCategoryId === 'all' ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>الكل</button>
          {categories.map(cat => (
            <button key={cat.id} onClick={() => setSelectedCategoryId(cat.id)} className={`flex-shrink-0 px-5 py-2 rounded-full border text-sm font-bold transition-all ${selectedCategoryId === cat.id ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>{cat.name}</button>
          ))}
        </div>
      </div>
      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18}/>
        <input className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-10 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none" placeholder="بحث سريع..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)}/>
      </div>
      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl text-white flex justify-between items-center">
        <div><p className="text-blue-100 text-sm mb-1 font-medium">إجمالي الكشف</p><h3 className="text-2xl font-bold tabular-nums">{totalAmount.toLocaleString()} ر.ي</h3></div>
        <div className="p-3 bg-white/20 rounded-2xl"><TrendingUp size={24}/></div>
      </div>
      <div className="grid grid-cols-2 gap-3">
        <button onClick={() => setShowPdfMenu(true)} disabled={filteredExpenses.length === 0} className="px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 bg-slate-900 border border-slate-800 text-white hover:border-blue-500 transition-all"><FileDown size={24} className="text-blue-500"/><span className="text-xs">كشف PDF</span></button>
        <button onClick={shareViaWhatsApp} disabled={filteredExpenses.length === 0} className="px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 bg-green-600/10 border border-green-600/30 text-green-500 transition-all"><MessageCircle size={24}/><span className="text-xs">مشاركة واتساب</span></button>
      </div>
      <div className="space-y-3">
        {filteredExpenses.map(exp => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div key={exp.id} className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30 cursor-pointer active:bg-slate-800 transition-colors" onClick={() => onExpenseSelect?.(exp)}>
              <div className="flex gap-4 items-center">
                <div className="w-10 h-10 rounded-xl bg-slate-800 flex items-center justify-center text-[10px] text-blue-500 font-bold border border-slate-700">SRF-{exp.serialNumber || '0'}</div>
                <div><p className="font-bold tabular-nums text-slate-200">{exp.amount.toLocaleString()} ر.ي</p><p className="text-[10px] text-slate-500">{exp.date} • {cat?.name}</p></div>
              </div>
              <ChevronRight size={14} className="text-slate-700 rotate-180"/>
            </div>
          );
        })}
      </div>
      {isGenerating && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[200] flex flex-col items-center justify-center p-8">
          <div className="w-full max-w-xs space-y-8 text-center">
            <div className="relative flex items-center justify-center"><div className="w-20 h-20 rounded-full border-4 border-slate-800 border-t-blue-500 animate-spin"/><FileText className="absolute text-blue-500" size={24}/></div>
            <div className="space-y-4">
              <div className="flex justify-between items-end mb-1 px-1"><span className="text-blue-400 text-xs font-bold">{statusMessage}</span><span className="text-slate-500 text-[10px] font-mono">{progress}%</span></div>
              <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden"><div className="h-full bg-blue-500 transition-all duration-500" style={{ width: `${progress}%` }}/></div>
            </div>
          </div>
        </div>
      )}
      {showPdfMenu && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[60] flex items-end justify-center p-4">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-md rounded-t-3xl p-6 animate-in slide-in-from-bottom duration-300">
            <div className="flex justify-between items-center mb-6"><h3 className="text-lg font-bold">تصدير الكشف</h3><button onClick={() => setShowPdfMenu(false)} className="p-2 text-slate-500"><X size={20}/></button></div>
            <div className="grid grid-cols-2 gap-4"><button onClick={() => processPDF('view')} className="bg-slate-800 text-white p-5 rounded-2xl flex flex-col items-center gap-3 border border-slate-700"><ExternalLink size={24}/><span className="font-bold text-sm">عرض</span></button><button onClick={() => processPDF('download')} className="bg-slate-800 text-white p-5 rounded-2xl flex flex-col items-center gap-3 border border-slate-700"><Download size={24}/><span className="font-bold text-sm">تحميل</span></button></div>
          </div>
        </div>
      )}
      <div ref={reportRef} dir="rtl" style={{ display: 'none', width: '210mm', padding: '15mm', backgroundColor: '#ffffff', color: '#000000', fontFamily: 'Tajawal' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '2px solid #000', paddingBottom: '10px', marginBottom: '20px' }}>
          <div><h1 style={{ margin: 0, fontSize: '24px' }}>كشف مصروفات</h1><p style={{ margin: 0, fontSize: '12px' }}>القسم: {selectedCategoryId === 'all' ? 'الكل' : categories.find(c => c.id === selectedCategoryId)?.name}</p></div>
          <div style={{ textAlign: 'left' }}><p style={{ margin: 0, fontSize: '10px' }}>الفترة: {fromDate} إلى {toDate}</p></div>
        </div>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '10px' }}>
          <thead><tr style={{ backgroundColor: '#f0f0f0' }}><th style={{ border: '1px solid #000', padding: '5px' }}>رقم السند</th><th style={{ border: '1px solid #000', padding: '5px' }}>القسم</th><th style={{ border: '1px solid #000', padding: '5px' }}>المبلغ</th><th style={{ border: '1px solid #000', padding: '5px' }}>التاريخ</th><th style={{ border: '1px solid #000', padding: '5px' }}>الملاحظات</th></tr></thead>
          <tbody>{filteredExpenses.map(exp => (<tr key={exp.id}><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center' }}>SRF-{exp.serialNumber}</td><td style={{ border: '1px solid #000', padding: '5px' }}>{categories.find(c => c.id === exp.categoryId)?.name}</td><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center' }}>{exp.amount.toLocaleString()}</td><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center' }}>{exp.date}</td><td style={{ border: '1px solid #000', padding: '5px' }}>{exp.notes}</td></tr>))}</tbody>
        </table>
        <div style={{ marginTop: '20px', textAlign: 'left', fontWeight: 'bold' }}>إجمالي المبلغ: {totalAmount.toLocaleString()} ريال يمني</div>
      </div>
    </div>
  );
};
export default ReportsView;

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { AppSettings, RecurringReminder, Category, DraftExpense, Expense } from '../types';
import { Download, Upload, Trash2, Bell, Plus, X, Wand2, CheckCircle2, AlertCircle, FileSearch, Smartphone } from 'lucide-react';
import ConfirmModal from './ConfirmModal';

interface SettingsViewProps { onUpdateSettings: (s: AppSettings) => void; installPrompt: any; onInstallSuccess: () => void; }

const SettingsView: React.FC<SettingsViewProps> = ({ onUpdateSettings, installPrompt, onInstallSuccess }) => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [reminders, setReminders] = useState<RecurringReminder[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [drafts, setDrafts] = useState<DraftExpense[]>([]);
  const [isSortingActive, setIsSortingActive] = useState(false);
  const [rawText, setRawText] = useState('');
  const [confirmData, setConfirmData] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void } | null>(null);

  useEffect(() => {
    db.settings.get('app_settings').then(s => s && setSettings(s));
    loadData();
  }, []);

  const loadData = async () => {
    setReminders(await db.reminders.toArray());
    setDrafts(await db.drafts.toArray());
    setCategories(await db.categories.toArray());
  };

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') onInstallSuccess();
  };

  const handleParseText = async () => {
    const regex = /\*([^*]+)\*\s*\*([\d.]+)\*\s*\*([^*]+)\*/g;
    let match; const newDrafts: DraftExpense[] = [];
    while ((match = regex.exec(rawText)) !== null) {
      newDrafts.push({ id: Math.random().toString(36).substr(2, 9), categoryName: match[1].trim(), amount: parseFloat(match[2]), notes: match[3].trim(), date: new Date().toISOString().split('T')[0] });
    }
    if (newDrafts.length > 0) { await db.drafts.bulkAdd(newDrafts); setRawText(''); setIsSortingActive(false); loadData(); }
    else alert('تأكد من الصيغة: *القسم* *المبلغ* *الملاحظة*');
  };

  const confirmDraft = async (draft: DraftExpense) => {
    let cat = categories.find(c => c.name === draft.categoryName) || categories[0];
    const all = await db.expenses.toArray();
    const max = all.reduce((m, e) => Math.max(m, e.serialNumber || 0), 0);
    await db.expenses.add({ id: Date.now().toString(), categoryId: cat.id, amount: draft.amount, notes: draft.notes, date: draft.date, createdAt: Date.now(), serialNumber: max + 1 });
    await db.drafts.delete(draft.id); loadData();
  };

  const exportData = async () => {
    const data = JSON.stringify({ cats: await db.categories.toArray(), exps: await db.expenses.toArray(), sets: await db.settings.get('app_settings'), rems: await db.reminders.toArray() });
    const blob = new Blob([data], { type: 'application/json' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `sarf_backup_${Date.now()}.json`; a.click();
  };

  return (
    <div className="space-y-6">
      <h2 className="text-xl font-bold mb-4">الإعدادات</h2>
      {installPrompt && (
        <div className="bg-blue-600/10 border border-blue-500/30 p-5 rounded-3xl flex flex-col items-center gap-3 text-center animate-in fade-in zoom-in">
          <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white"><Smartphone size={24}/></div>
          <div><h4 className="font-bold text-blue-400">ثبت صرف على جوالك</h4><p className="text-[10px] text-slate-500">للوصول السريع كأنه تطبيق APK حقيقي</p></div>
          <button onClick={handleInstallClick} className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl shadow-lg active:scale-95 transition-all">تثبيت الآن</button>
        </div>
      )}
      <div className="flex justify-between items-center px-2">
        <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider">الفرز الذكي</h3>
        <button onClick={() => setIsSortingActive(true)} className="bg-amber-500/10 text-amber-500 flex items-center gap-1 text-[10px] font-bold px-3 py-1 rounded-full border border-amber-500/20"><Wand2 size={12}/> فرز رسائل</button>
      </div>
      {drafts.length > 0 && (
        <div className="bg-amber-500/5 border border-amber-500/20 rounded-2xl divide-y divide-amber-500/10">
          {drafts.map(d => (
            <div key={d.id} className="p-4 flex justify-between items-center">
              <div><p className="font-bold text-sm text-slate-200">{d.amount.toLocaleString()} ر.ي - {d.categoryName}</p><p className="text-[10px] text-slate-500">{d.notes}</p></div>
              <button onClick={() => confirmDraft(d)} className="p-2 bg-green-600/10 text-green-500 rounded-full"><CheckCircle2 size={18}/></button>
            </div>
          ))}
        </div>
      )}
      <div className="bg-slate-900 rounded-2xl border border-slate-800 divide-y divide-slate-800">
        <button onClick={exportData} className="w-full p-4 flex items-center gap-3 text-right"><Download size={20} className="text-blue-400"/><div><p>تصدير نسخة احتياطية</p><p className="text-[10px] text-slate-500">حفظ كافة البيانات محلياً</p></div></button>
        <button onClick={() => setConfirmData({ isOpen: true, title: 'مسح البيانات', message: 'هل أنت متأكد؟', onConfirm: async () => { await db.expenses.clear(); window.location.reload(); } })} className="w-full p-4 flex items-center gap-3 text-red-500 text-right"><Trash2 size={20}/><span>مسح سجل المصروفات</span></button>
      </div>
      {isSortingActive && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm rounded-3xl p-6 space-y-4">
            <div className="flex justify-between items-center"><h3 className="text-lg font-bold">فرز رسائل المصروفات</h3><button onClick={() => setIsSortingActive(false)}><X size={20}/></button></div>
            <textarea className="w-full bg-slate-800 border border-slate-700 rounded-xl p-4 outline-none focus:ring-2 focus:ring-amber-500 min-h-[150px] text-sm" placeholder="*القسم* *المبلغ* *الملاحظة*..." value={rawText} onChange={e => setRawText(e.target.value)}/>
            <button onClick={handleParseText} className="w-full bg-amber-600 text-white font-bold py-4 rounded-2xl">بدء الفرز والتحويل</button>
          </div>
        </div>
      )}
      {confirmData && <ConfirmModal isOpen={confirmData.isOpen} title={confirmData.title} message={confirmData.message} onConfirm={confirmData.onConfirm} onCancel={() => setConfirmData(null)}/>}
    </div>
  );
};
export default SettingsView;

import React, { useState, useEffect } from 'react';
import { db, initializeDb } from './db';
import { ViewState, Category, Expense, AppSettings } from './types';
import { Plus, Home, PieChart, Settings as SettingsIcon } from 'lucide-react';

import HomeView from './components/HomeView';
import AddExpenseView from './components/AddExpenseView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import CategoryDetailView from './components/CategoryDetailView';
import ExpenseDetailView from './components/ExpenseDetailView';
import SplashScreen from './components/SplashScreen';
import IntroScreen from './components/IntroScreen';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [editingExpense, setEditingExpense] = useState<Expense | null>(null);
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [initialized, setInitialized] = useState(false);

  const [showSplash, setShowSplash] = useState(true);
  const [showIntro, setShowIntro] = useState(false);

  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const init = async () => {
      const startTime = Date.now();

      await initializeDb();
      const s = await db.settings.get('app_settings');
      if (s) setSettings(s);
      setInitialized(true);

      const elapsedTime = Date.now() - startTime;
      const minSplashTime = 2500; 
      const remainingTime = Math.max(0, minSplashTime - elapsedTime);

      setTimeout(() => {
        setShowSplash(false);
        setShowIntro(true); 

        setTimeout(() => {
          setShowIntro(false);
        }, 2200);

      }, remainingTime);
    };
    init();

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  if (showSplash) return <SplashScreen />;

  if (!initialized || !settings) return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center text-white font-bold">
      جاري تحميل صرف...
    </div>
  );

  const renderView = () => {
    switch (currentView) {
      case ViewState.HOME:
        return <HomeView onAdd={() => setCurrentView(ViewState.ADD_EXPENSE)} onCategorySelect={(cat) => { setSelectedCategory(cat); setCurrentView(ViewState.CATEGORY_DETAIL); }} />;
      case ViewState.ADD_EXPENSE:
        return <AddExpenseView onClose={() => { setEditingExpense(null); setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.HOME); }} initialData={editingExpense} preselectedCategoryId={selectedCategory?.id} />;
      case ViewState.REPORTS:
        return <ReportsView onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} />;
      case ViewState.SETTINGS:
        return <SettingsView onUpdateSettings={setSettings} installPrompt={deferredPrompt} onInstallSuccess={() => setDeferredPrompt(null)} />;
      case ViewState.CATEGORY_DETAIL:
        return selectedCategory ? <CategoryDetailView category={selectedCategory} onBack={() => { setSelectedCategory(null); setCurrentView(ViewState.HOME); }} onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} onAddExpense={() => { setEditingExpense(null); setCurrentView(ViewState.ADD_EXPENSE); }} /> : null;
      case ViewState.EXPENSE_DETAIL:
        return selectedExpense ? <ExpenseDetailView expense={selectedExpense} onBack={() => setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.REPORTS)} onEdit={(exp) => { setEditingExpense(exp); setCurrentView(ViewState.ADD_EXPENSE); }} /> : null;
      default:
        return <HomeView onAdd={() => setCurrentView(ViewState.ADD_EXPENSE)} onCategorySelect={(cat) => { setSelectedCategory(cat); setCurrentView(ViewState.CATEGORY_DETAIL); }} />;
    }
  };

  return (
    <>
      {showIntro && <IntroScreen />}

      <div className={`min-h-screen pb-20 max-w-md mx-auto bg-slate-950 text-slate-100 flex flex-col relative shadow-2xl overflow-x-hidden transition-all duration-1000 ease-in-out ${showIntro ? 'blur-xl scale-95 opacity-50' : 'blur-0 scale-100 opacity-100'}`}>
        <header className="p-4 flex justify-between items-center border-b border-slate-800 sticky top-0 bg-slate-950/80 backdrop-blur-md z-40">
          {/* زر الإعدادات الزجاجي في اليمين */}
          <button 
            onClick={() => setCurrentView(ViewState.SETTINGS)}
            className={`p-2.5 rounded-2xl transition-all active:scale-90 border flex items-center justify-center group ${currentView === ViewState.SETTINGS ? 'bg-blue-600/20 border-blue-500/40 text-blue-400 shadow-[0_0_15px_rgba(37,99,235,0.2)]' : 'bg-white/5 border-white/10 text-slate-400 hover:bg-white/10'}`}
          >
            <SettingsIcon size={20} className={currentView === ViewState.SETTINGS ? 'animate-[spin_4s_linear_infinite]' : ''} />
          </button>

          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold bg-gradient-to-l from-blue-400 to-blue-600 bg-clip-text text-transparent">صرف</h1>
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-white shadow-lg shadow-blue-900/40">ص</div>
          </div>
        </header>

        <main className="flex-grow p-4 overflow-y-auto">{renderView()}</main>

        <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-slate-900 border-t border-slate-800 flex justify-around p-3 z-50 rounded-t-3xl shadow-2xl">
          <button 
            onClick={() => { setSelectedCategory(null); setCurrentView(ViewState.HOME); }} 
            className={`flex flex-col items-center gap-1 transition-colors px-6 ${currentView === ViewState.HOME || currentView === ViewState.CATEGORY_DETAIL ? 'text-blue-500' : 'text-slate-500'}`}
          >
            <Home size={22} /><span className="text-[10px] font-bold">الرئيسية</span>
          </button>

          <button 
            onClick={() => { setEditingExpense(null); setCurrentView(ViewState.ADD_EXPENSE); }} 
            className="bg-blue-600 p-4 rounded-full -mt-10 shadow-xl shadow-blue-900/60 text-white active:scale-90 transition-transform ring-4 ring-slate-950"
          >
            <Plus size={28} />
          </button>

          <button 
            onClick={() => setCurrentView(ViewState.REPORTS)} 
            className={`flex flex-col items-center gap-1 transition-colors px-6 ${currentView === ViewState.REPORTS ? 'text-blue-500' : 'text-slate-500'}`}
          >
            <PieChart size={22} /><span className="text-[10px] font-bold">التقارير</span>
          </button>
        </nav>
      </div>
    </>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Category } from '../types';
import { 
  FolderPlus, 
  Search,
  Edit2,
  CalendarDays
} from 'lucide-react';

interface HomeViewProps {
  onAdd: () => void;
  onCategorySelect: (cat: Category) => void;
}

const PREDEFINED_COLORS = [
  '#3b82f6', '#6366f1', '#a855f7', '#ec4899', '#ef4444', '#f97316', 
  '#f59e0b', '#22c55e', '#10b981', '#14b8a6', '#06b6d4', '#0ea5e9',
];

const HomeView: React.FC<HomeViewProps> = ({ onAdd, onCategorySelect }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [categoryTotals, setCategoryTotals] = useState<Record<string, number>>({});
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);

  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryPhone, setNewCategoryPhone] = useState('');
  const [newCategoryColor, setNewCategoryColor] = useState(PREDEFINED_COLORS[0]);

  const [todayExpenses, setTodayExpenses] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');

  const loadData = async () => {
    const cats = await db.categories.toArray();
    cats.sort((a, b) => a.order - b.order);
    setCategories(cats);

    const expenses = await db.expenses.toArray();
    const totals: Record<string, number> = {};
    let dailyTotal = 0;
    const todayStr = new Date().toISOString().split('T')[0];

    expenses.forEach(exp => {
      // حساب الإجمالي لكل قسم (كلي)
      totals[exp.categoryId] = (totals[exp.categoryId] || 0) + exp.amount;

      // حساب إجمالي اليوم فقط للخانة الرئيسية
      if (exp.date === todayStr) {
        dailyTotal += exp.amount;
      }
    });

    setCategoryTotals(totals);
    setTodayExpenses(dailyTotal);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleSaveCategory = async () => {
    if (!newCategoryName.trim()) return;
    let phone = newCategoryPhone.trim().replace(/\D/g, '');
    if (phone.startsWith('0')) phone = phone.substring(1);
    if (editingCategory) {
      await db.categories.update(editingCategory.id, {
        name: newCategoryName, phoneNumber: phone || undefined, color: newCategoryColor
      });
    } else {
      await db.categories.add({
        id: Date.now().toString(), name: newCategoryName, 
        phoneNumber: phone || undefined, color: newCategoryColor, order: categories.length
      });
    }
    setIsModalOpen(false);
    loadData();
  };

  const filteredCategories = categories.filter(cat => 
    cat.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      {/* Hero Section: Today's Expenses */}
      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white text-center relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16 blur-2xl"></div>
        <div className="flex items-center justify-center gap-2 mb-1">
          <CalendarDays size={14} className="text-blue-100" />
          <p className="text-blue-100 text-sm font-medium">إجمالي مصاريف اليوم</p>
        </div>
        <h2 className="text-4xl font-bold mb-2 tabular-nums">
          {todayExpenses.toLocaleString('ar-SA')} 
          <span className="text-lg mr-2 opacity-80">ر.ي</span>
        </h2>
        <div className="text-[10px] text-blue-200/60 font-bold uppercase tracking-widest">
          {new Date().toLocaleDateString('ar-YE', { weekday: 'long', day: 'numeric', month: 'long' })}
        </div>
      </div>

      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18} />
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-4 py-3.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
          placeholder="بحث عن قسم..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
      </div>

      <div className="flex justify-between items-center px-1">
        <h3 className="text-lg font-bold text-slate-300">الأقسام</h3>
        <button onClick={() => { setEditingCategory(null); setNewCategoryName(''); setNewCategoryPhone(''); setIsModalOpen(true); }} className="text-blue-500 hover:bg-blue-500/10 p-2 rounded-full transition-colors flex items-center gap-1">
          <FolderPlus size={20} /><span className="text-sm font-medium">قسم جديد</span>
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {filteredCategories.map((cat) => (
          <div 
            key={cat.id}
            className="bg-slate-900 border border-slate-800 rounded-2xl p-4 active:scale-95 transition-transform group relative cursor-pointer flex flex-col justify-between h-40 shadow-lg"
            onClick={() => onCategorySelect(cat)}
            style={{ borderRight: `4px solid ${cat.color}` }}
          >
            <div>
              <div className="flex justify-between items-start mb-2">
                <div className="w-3 h-3 rounded-full mt-1" style={{ backgroundColor: cat.color }} />
                {!cat.isDefault && (
                  <button onClick={(e) => { e.stopPropagation(); setEditingCategory(cat); setNewCategoryName(cat.name); setNewCategoryPhone(cat.phoneNumber || ''); setNewCategoryColor(cat.color); setIsModalOpen(true); }} className="text-slate-600 opacity-0 group-hover:opacity-100"><Edit2 size={14}/></button>
                )}
              </div>
              <h4 className="font-bold text-slate-200 truncate">{cat.name}</h4>
              {cat.phoneNumber && <p className="text-[9px] text-slate-500 mt-1" dir="ltr">+{cat.phoneNumber}</p>}
            </div>
            <div className="mt-auto">
              <p className="text-[9px] text-slate-500 mb-0.5">إجمالي القسم</p>
              <p className="text-blue-400 font-bold text-sm text-left tabular-nums">
                {categoryTotals[cat.id]?.toLocaleString('ar-SA') || '٠'} <span className="text-[10px]">ر.ي</span>
              </p>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 w-full rounded-3xl p-6 shadow-2xl space-y-4 animate-in zoom-in duration-200">
            <h3 className="text-xl font-bold">{editingCategory ? 'تعديل قسم' : 'إضافة قسم جديد'}</h3>
            <div className="space-y-4">
              <input className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 outline-none" placeholder="اسم القسم..." value={newCategoryName} onChange={e => setNewCategoryName(e.target.value)} />
              <input className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 outline-none" placeholder="رقم الهاتف..." value={newCategoryPhone} onChange={e => setNewCategoryPhone(e.target.value)} />
              <div className="grid grid-cols-6 gap-2">
                {PREDEFINED_COLORS.map(c => (
                  <button key={c} onClick={() => setNewCategoryColor(c)} className={`w-8 h-8 rounded-full ${newCategoryColor === c ? 'ring-2 ring-white ring-offset-2 ring-offset-slate-900' : ''}`} style={{ backgroundColor: c }} />
                ))}
              </div>
            </div>
            <div className="flex gap-3 pt-4">
              <button onClick={handleSaveCategory} className="flex-grow bg-blue-600 text-white font-bold py-3 rounded-xl">حفظ</button>
              <button onClick={() => setIsModalOpen(false)} className="flex-grow bg-slate-800 text-slate-400 font-bold py-3 rounded-xl">إلغاء</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HomeView;

export interface Category {
  id: string;
  name: string;
  color: string;
  order: number;
  phoneNumber?: string; // حقل اختياري لرقم الهاتف
  isDefault?: boolean;
}

export interface Expense {
  id: string;
  categoryId: string;
  amount: number;
  date: string;
  notes?: string;
  image?: string; // base64
  createdAt: number;
  serialNumber?: number; // رقم تسلسلي (SRF-1)
}

export interface DraftExpense {
  id: string;
  categoryName: string;
  amount: number;
  notes: string;
  date: string;
}

export interface RecurringReminder {
  id: string;
  title: string;
  amount: number;
  categoryId: string;
  dayOfMonth: number;
}

export interface AppSettings {
  showImages: boolean;
  showNotes: boolean;
}

export enum ViewState {
  HOME = 'HOME',
  CATEGORIES = 'CATEGORIES',
  ADD_EXPENSE = 'ADD_EXPENSE',
  EDIT_EXPENSE = 'EDIT_EXPENSE',
  REPORTS = 'REPORTS',
  SETTINGS = 'SETTINGS',
  CATEGORY_DETAIL = 'CATEGORY_DETAIL',
  EXPENSE_DETAIL = 'EXPENSE_DETAIL'
}

import React, { useState, useEffect } from 'react';
import { db, initializeDb } from './db';
import { ViewState, Category, Expense, AppSettings } from './types';
import { Plus, Home, PieChart, Settings as SettingsIcon, LayoutGrid } from 'lucide-react';

import HomeView from './components/HomeView';
import CategoriesView from './components/CategoriesView';
import AddExpenseView from './components/AddExpenseView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import CategoryDetailView from './components/CategoryDetailView';
import ExpenseDetailView from './components/ExpenseDetailView';
import SplashScreen from './components/SplashScreen';
import IntroScreen from './components/IntroScreen';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [editingExpense, setEditingExpense] = useState<Expense | null>(null);
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [initialized, setInitialized] = useState(false);

  const [showSplash, setShowSplash] = useState(true);
  const [showIntro, setShowIntro] = useState(false);

  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const init = async () => {
      const startTime = Date.now();

      await initializeDb();
      const s = await db.settings.get('app_settings');
      if (s) setSettings(s);
      setInitialized(true);

      const elapsedTime = Date.now() - startTime;
      const minSplashTime = 2500; 
      const remainingTime = Math.max(0, minSplashTime - elapsedTime);

      setTimeout(() => {
        setShowSplash(false);
        setShowIntro(true); 

        setTimeout(() => {
          setShowIntro(false);
        }, 2200);

      }, remainingTime);
    };
    init();

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  if (showSplash) return <SplashScreen />;

  if (!initialized || !settings) return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center text-white font-bold">
      جاري تحميل صرف...
    </div>
  );

  const renderView = () => {
    switch (currentView) {
      case ViewState.HOME:
        return <HomeView onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} />;
      case ViewState.CATEGORIES:
        return <CategoriesView onCategorySelect={(cat) => { setSelectedCategory(cat); setCurrentView(ViewState.CATEGORY_DETAIL); }} />;
      case ViewState.ADD_EXPENSE:
        return <AddExpenseView onClose={() => { setEditingExpense(null); setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.HOME); }} initialData={editingExpense} preselectedCategoryId={selectedCategory?.id} />;
      case ViewState.REPORTS:
        return <ReportsView onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} />;
      case ViewState.SETTINGS:
        return <SettingsView onUpdateSettings={setSettings} installPrompt={deferredPrompt} onInstallSuccess={() => setDeferredPrompt(null)} />;
      case ViewState.CATEGORY_DETAIL:
        return selectedCategory ? <CategoryDetailView category={selectedCategory} onBack={() => { setSelectedCategory(null); setCurrentView(ViewState.CATEGORIES); }} onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} onAddExpense={() => { setEditingExpense(null); setCurrentView(ViewState.ADD_EXPENSE); }} /> : null;
      case ViewState.EXPENSE_DETAIL:
        return selectedExpense ? <ExpenseDetailView expense={selectedExpense} onBack={() => setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.HOME)} onEdit={(exp) => { setEditingExpense(exp); setCurrentView(ViewState.ADD_EXPENSE); }} /> : null;
      default:
        return <HomeView onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} />;
    }
  };

  return (
    <>
      {showIntro && <IntroScreen />}

      <div className={`min-h-screen pb-24 max-w-md mx-auto bg-slate-950 text-slate-100 flex flex-col relative shadow-2xl overflow-x-hidden transition-all duration-1000 ease-in-out ${showIntro ? 'blur-xl scale-95 opacity-50' : 'blur-0 scale-100 opacity-100'}`}>
        <header className="p-4 flex justify-between items-center border-b border-slate-800 sticky top-0 bg-slate-950/80 backdrop-blur-md z-40">
          <button 
            onClick={() => setCurrentView(ViewState.SETTINGS)}
            className={`p-2.5 rounded-2xl transition-all active:scale-90 border flex items-center justify-center group ${currentView === ViewState.SETTINGS ? 'bg-blue-600/20 border-blue-500/40 text-blue-400 shadow-[0_0_15px_rgba(37,99,235,0.2)]' : 'bg-white/5 border-white/10 text-slate-400 hover:bg-white/10'}`}
          >
            <SettingsIcon size={20} className={currentView === ViewState.SETTINGS ? 'animate-[spin_4s_linear_infinite]' : ''} />
          </button>

          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold bg-gradient-to-l from-blue-400 to-blue-600 bg-clip-text text-transparent">صرف</h1>
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-white shadow-lg shadow-blue-900/40">ص</div>
          </div>
        </header>

        <main className="flex-grow p-4 overflow-y-auto">{renderView()}</main>

        <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-slate-900/90 backdrop-blur-lg border-t border-slate-800 flex justify-around items-center p-3 pb-6 z-50 rounded-t-[2.5rem] shadow-2xl">
          <button 
            onClick={() => { setSelectedCategory(null); setCurrentView(ViewState.HOME); }} 
            className={`flex flex-col items-center gap-1 transition-all duration-300 ${currentView === ViewState.HOME ? 'text-blue-500 scale-110' : 'text-slate-500 hover:text-slate-300'}`}
          >
            <Home size={22} /><span className="text-[10px] font-bold">الرئيسية</span>
          </button>

          <button 
            onClick={() => { setSelectedCategory(null); setCurrentView(ViewState.CATEGORIES); }} 
            className={`flex flex-col items-center gap-1 transition-all duration-300 ${currentView === ViewState.CATEGORIES || currentView === ViewState.CATEGORY_DETAIL ? 'text-blue-500 scale-110' : 'text-slate-500 hover:text-slate-300'}`}
          >
            <LayoutGrid size={22} /><span className="text-[10px] font-bold">الأقسام</span>
          </button>

          <button 
            onClick={() => { setEditingExpense(null); setCurrentView(ViewState.ADD_EXPENSE); }} 
            className="bg-blue-600 p-4 rounded-full -mt-12 shadow-xl shadow-blue-900/60 text-white active:scale-90 transition-transform ring-8 ring-slate-950 flex items-center justify-center"
          >
            <Plus size={28} />
          </button>

          <button 
            onClick={() => setCurrentView(ViewState.REPORTS)} 
            className={`flex flex-col items-center gap-1 transition-all duration-300 ${currentView === ViewState.REPORTS ? 'text-blue-500 scale-110' : 'text-slate-500 hover:text-slate-300'}`}
          >
            <PieChart size={22} /><span className="text-[10px] font-bold">التقارير</span>
          </button>
        </nav>
      </div>
    </>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { 
  CalendarDays,
  TrendingUp,
  History,
  ChevronLeft
} from 'lucide-react';

interface HomeViewProps {
  onExpenseSelect: (exp: Expense) => void;
}

const HomeView: React.FC<HomeViewProps> = ({ onExpenseSelect }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [todayExpenses, setTodayExpenses] = useState(0);
  const [recentExpenses, setRecentExpenses] = useState<Expense[]>([]);

  const loadData = async () => {
    const cats = await db.categories.toArray();
    setCategories(cats);

    const expenses = await db.expenses.toArray();
    let dailyTotal = 0;
    const todayStr = new Date().toISOString().split('T')[0];

    expenses.forEach(exp => {
      if (exp.date === todayStr) {
        dailyTotal += exp.amount;
      }
    });

    setTodayExpenses(dailyTotal);

    // Sort and get last 10 expenses
    const sorted = [...expenses].sort((a, b) => b.createdAt - a.createdAt).slice(0, 10);
    setRecentExpenses(sorted);
  };

  useEffect(() => {
    loadData();
  }, []);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  return (
    <div className="space-y-6">
      {/* Hero Section: Today's Expenses */}
      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-8 rounded-[2.5rem] shadow-2xl shadow-blue-900/30 text-white text-center relative overflow-hidden">
        <div className="absolute top-0 right-0 w-40 h-40 bg-white/10 rounded-full -mr-20 -mt-20 blur-3xl opacity-50"></div>
        <div className="absolute bottom-0 left-0 w-32 h-32 bg-indigo-400/10 rounded-full -ml-16 -mb-16 blur-2xl opacity-40"></div>

        <div className="relative z-10">
          <div className="flex items-center justify-center gap-2 mb-2">
            <CalendarDays size={16} className="text-blue-100" />
            <p className="text-blue-100 text-sm font-bold uppercase tracking-widest">إجمالي مصاريف اليوم</p>
          </div>
          <h2 className="text-5xl font-black mb-3 tabular-nums">
            {todayExpenses.toLocaleString('ar-SA')} 
            <span className="text-xl mr-2 font-normal opacity-70">ر.ي</span>
          </h2>
          <div className="inline-flex items-center px-4 py-1.5 bg-white/15 rounded-full text-[11px] font-bold backdrop-blur-sm border border-white/10">
            {new Date().toLocaleDateString('ar-YE', { weekday: 'long', day: 'numeric', month: 'long' })}
          </div>
        </div>
      </div>

      {/* Quick Stats Grid */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-slate-900 border border-slate-800 p-5 rounded-3xl shadow-lg relative overflow-hidden group">
          <div className="flex flex-col gap-1 relative z-10">
            <span className="text-[10px] text-slate-500 font-black uppercase tracking-widest">أعلى عملية</span>
            <span className="text-lg font-bold text-slate-100 tabular-nums">
              {recentExpenses.length > 0 ? Math.max(...recentExpenses.map(e => e.amount)).toLocaleString() : '٠'}
            </span>
          </div>
          <TrendingUp className="absolute bottom-[-10px] right-[-10px] text-blue-500/10 group-hover:text-blue-500/20 transition-colors" size={60} />
        </div>
        <div className="bg-slate-900 border border-slate-800 p-5 rounded-3xl shadow-lg relative overflow-hidden group">
          <div className="flex flex-col gap-1 relative z-10">
            <span className="text-[10px] text-slate-500 font-black uppercase tracking-widest">عدد العمليات</span>
            <span className="text-lg font-bold text-slate-100 tabular-nums">
              {recentExpenses.length}
            </span>
          </div>
          <History className="absolute bottom-[-10px] right-[-10px] text-indigo-500/10 group-hover:text-indigo-500/20 transition-colors" size={60} />
        </div>
      </div>

      {/* Recent Activity */}
      <div className="space-y-4">
        <div className="flex justify-between items-center px-2">
          <h3 className="text-lg font-black text-slate-300 flex items-center gap-2">
            <History size={18} className="text-blue-500" />
            أحدث العمليات
          </h3>
          <span className="text-[10px] font-bold text-slate-600 bg-slate-900 px-2 py-0.5 rounded-full border border-slate-800">آخر ١٠ قيود</span>
        </div>

        <div className="space-y-3">
          {recentExpenses.map((exp) => {
            const cat = categories.find(c => c.id === exp.categoryId);
            return (
              <div 
                key={exp.id}
                onClick={() => onExpenseSelect(exp)}
                className="bg-slate-900/60 border border-slate-800/50 p-4 rounded-2xl flex justify-between items-center active:scale-[0.98] transition-all cursor-pointer hover:bg-slate-900 group"
              >
                <div className="flex gap-3 items-center">
                  <div 
                    className="w-10 h-10 rounded-xl flex items-center justify-center text-[10px] font-black shadow-lg" 
                    style={{ backgroundColor: `${cat?.color}15`, color: cat?.color, border: `1px solid ${cat?.color}30` }}
                  >
                    {cat?.name?.charAt(0) || 'ص'}
                  </div>
                  <div>
                    <h4 className="font-bold text-slate-200 text-sm">{cat?.name || 'بدون قسم'}</h4>
                    <p className="text-[10px] text-slate-500 mt-0.5">{exp.date} • {getDayName(exp.date)}</p>
                  </div>
                </div>
                <div className="text-left flex items-center gap-2">
                  <div className="flex flex-col items-end">
                    <span className="font-bold text-blue-400 tabular-nums">{exp.amount.toLocaleString()}</span>
                    <span className="text-[8px] text-slate-600 font-bold">ريال يمني</span>
                  </div>
                  <ChevronLeft size={14} className="text-slate-700 group-hover:text-blue-500 transition-colors" />
                </div>
              </div>
            );
          })}

          {recentExpenses.length === 0 && (
            <div className="text-center py-10 bg-slate-900/30 rounded-3xl border border-dashed border-slate-800">
              <p className="text-slate-600 text-xs font-bold">لا توجد عمليات مسجلة بعد</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default HomeView;

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Category } from '../types';
import { 
  FolderPlus, 
  Search,
  Edit2,
  LayoutGrid
} from 'lucide-react';

interface CategoriesViewProps {
  onCategorySelect: (cat: Category) => void;
}

const PREDEFINED_COLORS = [
  '#3b82f6', '#6366f1', '#a855f7', '#ec4899', '#ef4444', '#f97316', 
  '#f59e0b', '#22c55e', '#10b981', '#14b8a6', '#06b6d4', '#0ea5e9',
];

const CategoriesView: React.FC<CategoriesViewProps> = ({ onCategorySelect }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [categoryTotals, setCategoryTotals] = useState<Record<string, number>>({});
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);

  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryPhone, setNewCategoryPhone] = useState('');
  const [newCategoryColor, setNewCategoryColor] = useState(PREDEFINED_COLORS[0]);

  const [searchQuery, setSearchQuery] = useState('');

  const loadData = async () => {
    const cats = await db.categories.toArray();
    cats.sort((a, b) => a.order - b.order);
    setCategories(cats);

    const expenses = await db.expenses.toArray();
    const totals: Record<string, number> = {};

    expenses.forEach(exp => {
      totals[exp.categoryId] = (totals[exp.categoryId] || 0) + exp.amount;
    });

    setCategoryTotals(totals);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleSaveCategory = async () => {
    if (!newCategoryName.trim()) return;
    let phone = newCategoryPhone.trim().replace(/\D/g, '');
    if (phone.startsWith('0')) phone = phone.substring(1);

    if (editingCategory) {
      await db.categories.update(editingCategory.id, {
        name: newCategoryName, phoneNumber: phone || undefined, color: newCategoryColor
      });
    } else {
      await db.categories.add({
        id: Date.now().toString(), name: newCategoryName, 
        phoneNumber: phone || undefined, color: newCategoryColor, order: categories.length
      });
    }
    setIsModalOpen(false);
    loadData();
  };

  const filteredCategories = categories.filter(cat => 
    cat.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center px-1">
        <h2 className="text-xl font-black text-slate-100 flex items-center gap-2">
          <LayoutGrid size={22} className="text-blue-500" />
          أقسام المصروفات
        </h2>
        <button 
          onClick={() => { setEditingCategory(null); setNewCategoryName(''); setNewCategoryPhone(''); setIsModalOpen(true); }} 
          className="bg-blue-600/10 text-blue-500 hover:bg-blue-600 hover:text-white p-2.5 rounded-2xl transition-all flex items-center gap-2 border border-blue-500/20"
        >
          <FolderPlus size={18} />
          <span className="text-xs font-black">إضافة قسم</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18} />
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-4 py-3.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all shadow-lg"
          placeholder="بحث سريع في الأقسام..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-2 gap-4">
        {filteredCategories.map((cat) => (
          <div 
            key={cat.id}
            className="bg-slate-900 border border-slate-800 rounded-3xl p-5 active:scale-95 transition-all group relative cursor-pointer flex flex-col justify-between h-44 shadow-xl hover:border-slate-700"
            onClick={() => onCategorySelect(cat)}
          >
            <div className="absolute top-0 right-0 p-3 opacity-0 group-hover:opacity-100 transition-opacity">
              {!cat.isDefault && (
                <button 
                  onClick={(e) => { 
                    e.stopPropagation(); 
                    setEditingCategory(cat); 
                    setNewCategoryName(cat.name); 
                    setNewCategoryPhone(cat.phoneNumber || ''); 
                    setNewCategoryColor(cat.color); 
                    setIsModalOpen(true); 
                  }} 
                  className="p-1.5 bg-slate-800 text-slate-400 rounded-lg hover:text-white"
                >
                  <Edit2 size={12}/>
                </button>
              )}
            </div>

            <div>
              <div className="w-10 h-10 rounded-xl mb-3 flex items-center justify-center font-black text-white shadow-lg" style={{ backgroundColor: cat.color }}>
                {cat.name.charAt(0)}
              </div>
              <h4 className="font-black text-slate-100 truncate text-base">{cat.name}</h4>
              {cat.phoneNumber && <p className="text-[10px] text-slate-500 mt-1 font-mono" dir="ltr">+{cat.phoneNumber}</p>}
            </div>

            <div className="mt-auto pt-2 border-t border-slate-800/50">
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mb-0.5">إجمالي المنصرف</p>
              <p className="text-blue-400 font-black text-sm tabular-nums">
                {categoryTotals[cat.id]?.toLocaleString('ar-SA') || '٠'} 
                <span className="text-[10px] mr-1 text-slate-500">ر.ي</span>
              </p>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm rounded-3xl p-6 shadow-2xl space-y-4 animate-in zoom-in duration-200">
            <h3 className="text-xl font-black">{editingCategory ? 'تعديل بيانات القسم' : 'إنشاء قسم مالي جديد'}</h3>
            <div className="space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] text-slate-500 font-black uppercase tracking-widest px-1">اسم القسم</label>
                <input className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3.5 outline-none focus:ring-2 focus:ring-blue-500 text-sm font-bold" placeholder="مثال: بقالة، وقود، إيجار..." value={newCategoryName} onChange={e => setNewCategoryName(e.target.value)} />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] text-slate-500 font-black uppercase tracking-widest px-1">رقم التواصل (اختياري)</label>
                <input className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3.5 outline-none focus:ring-2 focus:ring-blue-500 text-sm font-mono" placeholder="رقم الهاتف بدون مفتاح الدولة..." value={newCategoryPhone} onChange={e => setNewCategoryPhone(e.target.value)} />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] text-slate-500 font-black uppercase tracking-widest px-1">لون القسم المميز</label>
                <div className="grid grid-cols-6 gap-3 pt-1">
                  {PREDEFINED_COLORS.map(c => (
                    <button key={c} onClick={() => setNewCategoryColor(c)} className={`w-8 h-8 rounded-full transition-all ${newCategoryColor === c ? 'ring-4 ring-white/20 scale-125 shadow-lg shadow-white/5' : 'hover:scale-110'}`} style={{ backgroundColor: c }} />
                  ))}
                </div>
              </div>
            </div>
            <div className="flex gap-3 pt-6">
              <button onClick={handleSaveCategory} className="flex-grow bg-blue-600 hover:bg-blue-500 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-900/40 active:scale-95 transition-all">حفظ البيانات</button>
              <button onClick={() => setIsModalOpen(false)} className="px-6 bg-slate-800 text-slate-400 font-bold py-4 rounded-2xl active:scale-95 transition-all">إلغاء</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CategoriesView;

