import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Category, Expense } from '../types';
import { X, Camera, Calendar, Image as ImageIcon, Trash2, Check } from 'lucide-react';
import ConfirmModal from './ConfirmModal';

interface AddExpenseViewProps {
  onClose: () => void;
  initialData?: Expense | null;
  preselectedCategoryId?: string;
}

const AddExpenseView: React.FC<AddExpenseViewProps> = ({ onClose, initialData, preselectedCategoryId }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [amount, setAmount] = useState(initialData?.amount.toString() || '');
  const [categoryId, setCategoryId] = useState(initialData?.categoryId || preselectedCategoryId || 'default_general');
  const [notes, setNotes] = useState(initialData?.notes || '');
  const [date, setDate] = useState(initialData?.date || new Date().toISOString().split('T')[0]);
  const [image, setImage] = useState<string | null>(initialData?.image || null);
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    db.categories.toArray().then(setCategories);
    if (!initialData && preselectedCategoryId) {
      setCategoryId(preselectedCategoryId);
    }
  }, [preselectedCategoryId, initialData]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleSave = async () => {
    const numAmount = parseFloat(amount);
    if (!numAmount || numAmount <= 0) {
      alert('الرجاء إدخال مبلغ صحيح أكبر من صفر');
      return;
    }

    let serialNumber = initialData?.serialNumber;

    if (!initialData) {
      const allExpenses = await db.expenses.toArray();
      const maxSerial = allExpenses.reduce((max, exp) => Math.max(max, exp.serialNumber || 0), 0);
      serialNumber = maxSerial + 1;
    }

    const expenseData: Expense = {
      id: initialData?.id || Date.now().toString(),
      amount: numAmount,
      categoryId,
      notes,
      date,
      image: image || undefined,
      createdAt: initialData?.createdAt || Date.now(),
      serialNumber
    };

    if (initialData) {
      await db.expenses.put(expenseData);
    } else {
      await db.expenses.add(expenseData);
    }
    onClose();
  };

  const handleDelete = async () => {
    if (initialData) {
      await db.expenses.delete(initialData.id);
      setIsConfirmOpen(false);
      onClose();
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6 pb-20">
      {/* Header with Save Button moved here */}
      <div className="flex items-center justify-between mb-4 sticky top-0 bg-slate-950/80 backdrop-blur-md z-10 py-2 -mx-4 px-4 border-b border-slate-800/50">
        <button onClick={onClose} className="p-2 text-slate-400 hover:text-white transition-colors">
          <X size={24} />
        </button>

        <h2 className="text-lg font-bold text-slate-100">
          {initialData ? 'تعديل مصروف' : 'إضافة مصروف'}
        </h2>

        <button 
          onClick={handleSave}
          className="bg-blue-600 hover:bg-blue-500 text-white font-bold px-5 py-2 rounded-xl shadow-lg shadow-blue-900/40 active:scale-95 transition-all flex items-center gap-2"
        >
          <Check size={18} />
          <span>حفظ</span>
        </button>
      </div>

      <div className="space-y-6">
        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">المبلغ (ريال يمني)</label>
          <input 
            type="number" 
            pattern="[0-9]*"
            inputMode="decimal"
            autoFocus
            className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-4 py-6 text-4xl font-black text-center text-blue-500 outline-none focus:ring-2 focus:ring-blue-500 tabular-nums shadow-inner"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            placeholder="0.00"
          />
        </div>

        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">القسم الضريبي / المالي</label>
          <div className="flex gap-2 overflow-x-auto pb-3 no-scrollbar">
            {categories.map(cat => (
              <button
                key={cat.id}
                onClick={() => setCategoryId(cat.id)}
                className={`flex-shrink-0 px-6 py-2.5 rounded-2xl border transition-all text-sm font-bold ${
                  categoryId === cat.id 
                    ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-900/40' 
                    : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-700'
                }`}
              >
                {cat.name}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 gap-4">
          <div>
            <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">تاريخ العملية</label>
            <div className="relative group">
              <input 
                type="date"
                className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-4 py-4 outline-none focus:ring-2 focus:ring-blue-500 text-white font-bold"
                value={date}
                onChange={(e) => setDate(e.target.value)}
              />
              <Calendar className="absolute left-4 top-4 text-slate-500 pointer-events-none" size={20} />
              <div className="absolute right-4 top-4 bg-blue-600/10 text-blue-500 px-3 py-1 rounded-lg text-[10px] font-black pointer-events-none border border-blue-500/20">
                {getDayName(date)}
              </div>
            </div>
          </div>
        </div>

        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">البيان / ملاحظات إضافية</label>
          <textarea 
            className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-4 py-4 outline-none focus:ring-2 focus:ring-blue-500 resize-none h-28 text-sm font-medium"
            placeholder="اكتب تفاصيل المصروف هنا (اختياري)..."
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
          />
        </div>

        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">المرفقات والصور</label>
          {image ? (
            <div className="relative group rounded-2xl overflow-hidden border border-slate-800 aspect-video bg-slate-900 shadow-xl">
              <img src={image} className="w-full h-full object-contain" alt="Expense attachment" />
              <button 
                onClick={() => setImage(null)}
                className="absolute top-3 right-3 bg-red-600 text-white p-2.5 rounded-xl shadow-lg active:scale-90 transition-all"
              >
                <Trash2 size={18} />
              </button>
            </div>
          ) : (
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full border-2 border-dashed border-slate-800 rounded-2xl p-10 flex flex-col items-center justify-center gap-3 text-slate-500 hover:border-blue-500 hover:text-blue-500 transition-all active:scale-[0.98] bg-slate-900/50"
            >
              <div className="p-4 bg-slate-800 rounded-2xl">
                <Camera size={32} />
              </div>
              <div className="text-center">
                <span className="font-bold text-sm block">تصوير فاتورة</span>
                <span className="text-[10px] opacity-60">أو اختيار ملف من الاستوديو</span>
              </div>
            </button>
          )}
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept="image/*" 
            onChange={handleImageUpload} 
          />
        </div>

        {initialData && (
          <div className="pt-4">
            <button 
              onClick={() => setIsConfirmOpen(true)}
              className="w-full p-4 bg-red-600/10 text-red-500 rounded-2xl hover:bg-red-600 hover:text-white transition-all font-bold flex items-center justify-center gap-2 border border-red-500/20 shadow-lg shadow-red-900/5"
            >
              <Trash2 size={20} />
              <span>حذف هذا المصروف نهائياً</span>
            </button>
          </div>
        )}
      </div>

      <ConfirmModal 
        isOpen={isConfirmOpen}
        title="حذف مصروف"
        message="هل أنت متأكد من حذف هذا المصروف؟ لا يمكن استعادة البيانات بعد الحذف."
        onConfirm={handleDelete}
        onCancel={() => setIsConfirmOpen(false)}
      />
    </div>
  );
};

export default AddExpenseView;

import React, { useState, useEffect } from 'react';
import { db, initializeDb } from './db';
import { ViewState, Category, Expense, AppSettings } from './types';
import { Plus, Home, PieChart, Settings as SettingsIcon, LayoutGrid } from 'lucide-react';

import HomeView from './components/HomeView';
import CategoriesView from './components/CategoriesView';
import AddExpenseView from './components/AddExpenseView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import CategoryDetailView from './components/CategoryDetailView';
import ExpenseDetailView from './components/ExpenseDetailView';
import SplashScreen from './components/SplashScreen';
import IntroScreen from './components/IntroScreen';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [editingExpense, setEditingExpense] = useState<Expense | null>(null);
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [initialized, setInitialized] = useState(false);

  const [showSplash, setShowSplash] = useState(true);
  const [showIntro, setShowIntro] = useState(false);

  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const init = async () => {
      const startTime = Date.now();

      await initializeDb();
      const s = await db.settings.get('app_settings');
      if (s) setSettings(s);
      setInitialized(true);

      const elapsedTime = Date.now() - startTime;
      const minSplashTime = 2500; 
      const remainingTime = Math.max(0, minSplashTime - elapsedTime);

      setTimeout(() => {
        setShowSplash(false);
        setShowIntro(true); 

        setTimeout(() => {
          setShowIntro(false);
        }, 2200);

      }, remainingTime);
    };
    init();

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  if (showSplash) return <SplashScreen />;

  if (!initialized || !settings) return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center text-white font-bold">
      جاري تحميل صرف...
    </div>
  );

  const renderView = () => {
    switch (currentView) {
      case ViewState.HOME:
        return <HomeView onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} />;
      case ViewState.CATEGORIES:
        return <CategoriesView onCategorySelect={(cat) => { setSelectedCategory(cat); setCurrentView(ViewState.CATEGORY_DETAIL); }} />;
      case ViewState.ADD_EXPENSE:
        return <AddExpenseView onClose={() => { setEditingExpense(null); setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.HOME); }} initialData={editingExpense} preselectedCategoryId={selectedCategory?.id} />;
      case ViewState.REPORTS:
        return <ReportsView onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} />;
      case ViewState.SETTINGS:
        return <SettingsView onUpdateSettings={setSettings} installPrompt={deferredPrompt} onInstallSuccess={() => setDeferredPrompt(null)} />;
      case ViewState.CATEGORY_DETAIL:
        return selectedCategory ? <CategoryDetailView category={selectedCategory} onBack={() => { setSelectedCategory(null); setCurrentView(ViewState.CATEGORIES); }} onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} onAddExpense={() => { setEditingExpense(null); setCurrentView(ViewState.ADD_EXPENSE); }} /> : null;
      case ViewState.EXPENSE_DETAIL:
        return selectedExpense ? <ExpenseDetailView expense={selectedExpense} onBack={() => setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.HOME)} onEdit={(exp) => { setEditingExpense(exp); setCurrentView(ViewState.ADD_EXPENSE); }} /> : null;
      default:
        return <HomeView onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} />;
    }
  };

  return (
    <>
      {showIntro && <IntroScreen />}

      <div className={`min-h-screen pb-32 max-w-md mx-auto bg-slate-950 text-slate-100 flex flex-col relative shadow-2xl overflow-x-hidden transition-all duration-1000 ease-in-out ${showIntro ? 'blur-xl scale-95 opacity-50' : 'blur-0 scale-100 opacity-100'}`}>
        <header className="p-4 flex justify-between items-center border-b border-slate-800 sticky top-0 bg-slate-950/80 backdrop-blur-md z-40">
          <button 
            onClick={() => setCurrentView(ViewState.SETTINGS)}
            className={`p-2.5 rounded-2xl transition-all active:scale-90 border flex items-center justify-center group ${currentView === ViewState.SETTINGS ? 'bg-blue-600/20 border-blue-500/40 text-blue-400 shadow-[0_0_15px_rgba(37,99,235,0.2)]' : 'bg-white/5 border-white/10 text-slate-400 hover:bg-white/10'}`}
          >
            <SettingsIcon size={20} className={currentView === ViewState.SETTINGS ? 'animate-[spin_4s_linear_infinite]' : ''} />
          </button>

          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold bg-gradient-to-l from-blue-400 to-blue-600 bg-clip-text text-transparent">صرف</h1>
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-white shadow-lg shadow-blue-900/40">ص</div>
          </div>
        </header>

        <main className="flex-grow p-4 overflow-y-auto">{renderView()}</main>

        {/* Floating Glassmorphism Navigation Bar */}
        <div className="fixed bottom-6 left-0 right-0 z-50 px-4 flex justify-center pointer-events-none">
          <nav className="w-full max-w-[calc(100%-1rem)] md:max-w-[400px] pointer-events-auto bg-slate-900/60 backdrop-blur-2xl border border-white/10 flex justify-around items-center p-2 rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.5)] relative">

            <button 
              onClick={() => { setSelectedCategory(null); setCurrentView(ViewState.HOME); }} 
              className={`flex flex-col items-center gap-1 transition-all duration-300 py-1 flex-1 ${currentView === ViewState.HOME ? 'text-blue-500 scale-110' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <Home size={20} /><span className="text-[9px] font-black">الرئيسية</span>
            </button>

            <button 
              onClick={() => { setSelectedCategory(null); setCurrentView(ViewState.CATEGORIES); }} 
              className={`flex flex-col items-center gap-1 transition-all duration-300 py-1 flex-1 ${currentView === ViewState.CATEGORIES || currentView === ViewState.CATEGORY_DETAIL ? 'text-blue-500 scale-110' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <LayoutGrid size={20} /><span className="text-[9px] font-black">الأقسام</span>
            </button>

            <div className="relative -mt-10 px-2">
              <button 
                onClick={() => { setEditingExpense(null); setCurrentView(ViewState.ADD_EXPENSE); }} 
                className="bg-blue-600 p-4 rounded-full shadow-[0_10px_25px_rgba(37,99,235,0.4)] text-white active:scale-90 transition-all ring-4 ring-slate-950 flex items-center justify-center group"
              >
                <Plus size={28} className="group-hover:rotate-90 transition-transform duration-300" />
              </button>
            </div>

            <button 
              onClick={() => setCurrentView(ViewState.REPORTS)} 
              className={`flex flex-col items-center gap-1 transition-all duration-300 py-1 flex-1 ${currentView === ViewState.REPORTS ? 'text-blue-500 scale-110' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <PieChart size={20} /><span className="text-[9px] font-black">التقارير</span>
            </button>

            <button 
              onClick={() => setCurrentView(ViewState.SETTINGS)}
              className={`flex flex-col items-center gap-1 transition-all duration-300 py-1 flex-1 ${currentView === ViewState.SETTINGS ? 'text-blue-500 scale-110' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <SettingsIcon size={20} /><span className="text-[9px] font-black">الضبط</span>
            </button>
          </nav>
        </div>
      </div>
    </>
  );
};

export default App;

