import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { FileDown, TrendingUp, Calendar, MessageCircle, ChevronRight, Search, X, ExternalLink, Download, FileText, Layers, ChevronDown } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface ReportsViewProps { onExpenseSelect?: (exp: Expense) => void; }

const ReportsView: React.FC<ReportsViewProps> = ({ onExpenseSelect }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showPdfMenu, setShowPdfMenu] = useState(false);
  const [showAll, setShowAll] = useState(false); // حالة إظهار الكل
  const [progress, setProgress] = useState(0);
  const [statusMessage, setStatusMessage] = useState('');
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);
      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();
      if (selectedCategoryId !== 'all') results = results.filter(e => e.categoryId === selectedCategoryId);

      // فرز الأحدث حسب تاريخ الإنشاء الفعلي لضمان أن آخر سند أضيف يظهر أولاً
      results.sort((a, b) => b.createdAt - a.createdAt);

      setExpenses(results);
      setShowAll(false); // إعادة التعيين عند تغيير الفلاتر
    };
    load();
  }, [fromDate, toDate, selectedCategoryId]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const processPDF = async (action: 'download' | 'view') => {
    if (expenses.length === 0 || isGenerating) return;
    setIsGenerating(true); 
    setShowPdfMenu(false); 
    setProgress(10); 
    setStatusMessage('جاري تحضير البيانات...');
    try {
      const element = reportRef.current;
      if (!element) return;

      await new Promise(r => setTimeout(r, 500)); 
      setProgress(40); 
      setStatusMessage('جاري التقاط لقطات عالية الجودة...');

      element.style.display = 'block'; 
      element.style.visibility = 'visible'; 
      element.style.position = 'fixed'; 
      element.style.left = '-10000px';

      const canvas = await html2canvas(element, { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: '#ffffff' 
      });

      element.style.display = 'none'; 
      setProgress(80); 
      setStatusMessage('جاري تحويل البيانات إلى ملف PDF...');

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      setProgress(100); 
      setStatusMessage('اكتملت العملية!');

      await new Promise(r => setTimeout(r, 500));
      if (action === 'download') pdf.save(`تقرير_صرف_${fromDate}.pdf`);
      else window.open(pdf.output('bloburl'), '_blank');
    } catch (error) { 
      alert('حدث خطأ أثناء معالجة التقرير.'); 
    } finally { 
      setIsGenerating(false); 
      setProgress(0); 
      setStatusMessage(''); 
    }
  };

  const currentCategory = categories.find(c => c.id === selectedCategoryId);
  const isWhatsAppEnabled = selectedCategoryId !== 'all' && !!currentCategory?.phoneNumber;

  const shareViaWhatsApp = () => {
    if (!isWhatsAppEnabled || !currentCategory) return;
    const totalVal = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
    const message = `*كشف مصروفات - تطبيق صرف*\n\n` +
                    `*القسم:* ${currentCategory.name}\n` +
                    `*الفترة:* من ${fromDate} إلى ${toDate}\n` +
                    `*الإجمالي:* ${totalVal.toLocaleString()} ر.ي\n` +
                    `*عدد العمليات:* ${filteredExpenses.length}\n\n` +
                    `_تم التصدير بواسطة تطبيق صرف المالي_`;
    const url = `https://wa.me/967${currentCategory.phoneNumber}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const filteredExpenses = expenses.filter(exp => exp.notes?.toLowerCase().includes(searchQuery.toLowerCase()) || exp.amount.toString().includes(searchQuery));
  const totalAmount = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);

  // التحكم في السندات المعروضة (15 أو الكل)
  const displayedExpenses = showAll ? filteredExpenses : filteredExpenses.slice(0, 15);

  const sortedExpensesForPdf = [...filteredExpenses].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  return (
    <div className="space-y-6 pb-10">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="text-xs text-slate-500 mb-1 flex items-center gap-1"><Calendar size={12}/> من تاريخ</label>
          <div className="relative">
            <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400" value={fromDate} onChange={e => setFromDate(e.target.value)}/>
            <span className="text-[9px] text-slate-600 block mt-1">{getDayName(fromDate)}</span>
          </div>
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="text-xs text-slate-500 mb-1 flex items-center gap-1"><Calendar size={12}/> إلى تاريخ</label>
          <div className="relative">
            <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400" value={toDate} onChange={e => setToDate(e.target.value)}/>
            <span className="text-[9px] text-slate-600 block mt-1">{getDayName(toDate)}</span>
          </div>
        </div>
      </div>

      <div className="space-y-2">
        <label className="text-xs text-slate-500 px-1 flex items-center gap-1"><Layers size={12}/> تصفية حسب القسم</label>
        <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
          <button onClick={() => setSelectedCategoryId('all')} className={`flex-shrink-0 px-5 py-2 rounded-full border text-sm font-bold transition-all ${selectedCategoryId === 'all' ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>الكل</button>
          {categories.map(cat => (
            <button key={cat.id} onClick={() => setSelectedCategoryId(cat.id)} className={`flex-shrink-0 px-5 py-2 rounded-full border text-sm font-bold transition-all ${selectedCategoryId === cat.id ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>{cat.name}</button>
          ))}
        </div>
      </div>

      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18}/>
        <input className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-10 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none" placeholder="بحث سريع..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)}/>
      </div>

      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl text-white flex justify-between items-center">
        <div><p className="text-blue-100 text-sm mb-1 font-medium">إجمالي الكشف</p><h3 className="text-2xl font-bold tabular-nums">{totalAmount.toLocaleString()} ر.ي</h3></div>
        <div className="p-3 bg-white/20 rounded-2xl"><TrendingUp size={24}/></div>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <button onClick={() => setShowPdfMenu(true)} disabled={filteredExpenses.length === 0} className="px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 bg-slate-900 border border-slate-800 text-white hover:border-blue-500 transition-all active:scale-95 disabled:opacity-50">
          <FileDown size={24} className="text-blue-500"/>
          <span className="text-xs">كشف PDF</span>
        </button>

        <button onClick={shareViaWhatsApp} disabled={filteredExpenses.length === 0 || !isWhatsAppEnabled} className={`px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 transition-all active:scale-95 border ${isWhatsAppEnabled ? 'bg-green-600/10 border-green-600/30 text-green-500' : 'bg-slate-900/50 border-slate-800 text-slate-600 opacity-40 grayscale cursor-not-allowed'}`}>
          <MessageCircle size={24}/>
          <span className="text-xs">مشاركة واتساب</span>
        </button>
      </div>

      <div className="space-y-3">
        <div className="flex justify-between items-center px-1">
          <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">السندات المفلترة ({filteredExpenses.length})</h4>
        </div>

        {displayedExpenses.map(exp => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div key={exp.id} className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30 cursor-pointer active:bg-slate-800 transition-colors" onClick={() => onExpenseSelect?.(exp)}>
              <div className="flex gap-4 items-center">
                <div className="w-10 h-10 rounded-xl bg-slate-800 flex items-center justify-center text-[10px] text-blue-500 font-bold border border-slate-700">SRF-{exp.serialNumber || '0'}</div>
                <div><p className="font-bold tabular-nums text-slate-200">{exp.amount.toLocaleString()} ر.ي</p><p className="text-[10px] text-slate-500">{exp.date} ({getDayName(exp.date)}) • {cat?.name}</p></div>
              </div>
              <ChevronRight size={14} className="text-slate-700 rotate-180"/>
            </div>
          );
        })}

        {/* زر إظهار المزيد - يظهر فقط إذا كان هناك أكثر من 15 ولم يتم الضغط عليه بعد */}
        {!showAll && filteredExpenses.length > 15 && (
          <button 
            onClick={() => setShowAll(true)}
            className="w-full py-3 mt-2 flex items-center justify-center gap-2 text-[10px] font-bold text-blue-500 bg-blue-600/5 border border-blue-600/20 rounded-xl active:scale-95 transition-all"
          >
            <span>إظهار المزيد ({filteredExpenses.length - 15})</span>
            <ChevronDown size={12}/>
          </button>
        )}

        {filteredExpenses.length === 0 && (
          <div className="text-center py-12 bg-slate-900/30 rounded-3xl border border-dashed border-slate-800">
            <p className="text-slate-600 text-xs">لا توجد عمليات في هذه الفترة</p>
          </div>
        )}
      </div>

      {isGenerating && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[200] flex flex-col items-center justify-center p-8">
          <div className="w-full max-w-xs space-y-8 text-center">
            <div className="relative flex items-center justify-center"><div className="w-20 h-20 rounded-full border-4 border-slate-800 border-t-blue-500 animate-spin"/><FileText className="absolute text-blue-500" size={24}/></div>
            <div className="space-y-4">
              <div className="flex justify-between items-end mb-1 px-1"><span className="text-blue-400 text-xs font-bold">{statusMessage}</span><span className="text-slate-500 text-[10px] font-mono">{progress}%</span></div>
              <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden"><div className="h-full bg-blue-500 transition-all duration-500" style={{ width: `${progress}%` }}/></div>
            </div>
          </div>
        </div>
      )}

      {/* Floating Glass PDF Menu */}
      {showPdfMenu && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-md z-[200] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-slate-900/80 backdrop-blur-2xl border border-white/10 w-full max-w-sm rounded-[2.5rem] p-8 shadow-[0_20px_50px_rgba(0,0,0,0.5)] animate-in zoom-in duration-300">
            <div className="flex justify-between items-center mb-8">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-600/20 text-blue-500 rounded-xl">
                  <FileDown size={20} />
                </div>
                <h3 className="text-lg font-bold text-white">تصدير الكشف</h3>
              </div>
              <button onClick={() => setShowPdfMenu(false)} className="p-2 text-slate-500 hover:text-white transition-colors">
                <X size={20}/>
              </button>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <button 
                onClick={() => processPDF('view')} 
                className="group bg-white/5 hover:bg-white/10 text-white p-6 rounded-3xl flex flex-col items-center gap-3 border border-white/5 transition-all active:scale-95"
              >
                <div className="p-3 bg-blue-600/10 text-blue-500 rounded-2xl group-hover:scale-110 transition-transform">
                  <ExternalLink size={24}/>
                </div>
                <span className="font-bold text-sm">فتح الملف</span>
              </button>

              <button 
                onClick={() => processPDF('download')} 
                className="group bg-blue-600 hover:bg-blue-500 text-white p-6 rounded-3xl flex flex-col items-center gap-3 shadow-lg shadow-blue-900/20 transition-all active:scale-95"
              >
                <div className="p-3 bg-white/20 text-white rounded-2xl group-hover:scale-110 transition-transform">
                  <Download size={24}/>
                </div>
                <span className="font-bold text-sm">تحميل PDF</span>
              </button>
            </div>

            <p className="mt-6 text-center text-[10px] text-slate-500 font-medium">سيتم إنشاء تقرير مفصل للفترة المختارة</p>
          </div>
        </div>
      )}

      {/* التقرير المستخدم للتصوير (html2canvas) */}
      <div ref={reportRef} dir="rtl" style={{ display: 'none', width: '210mm', padding: '15mm', backgroundColor: '#ffffff', color: '#000000', fontFamily: 'Tajawal' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '2px solid #000', paddingBottom: '10px', marginBottom: '20px' }}>
          <div><h1 style={{ margin: 0, fontSize: '24px', color: '#000000' }}>كشف مصروفات</h1><p style={{ margin: 0, fontSize: '12px', color: '#000000' }}>القسم: {selectedCategoryId === 'all' ? 'الكل' : categories.find(c => c.id === selectedCategoryId)?.name}</p></div>
          <div style={{ textAlign: 'left' }}><p style={{ margin: 0, fontSize: '10px', color: '#000000' }}>الفترة: {fromDate} إلى {toDate}</p></div>
        </div>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '10px', color: '#000000' }}>
          <thead><tr style={{ backgroundColor: '#f0f0f0' }}><th style={{ border: '1px solid #000', padding: '5px', color: '#000000' }}>رقم السند</th><th style={{ border: '1px solid #000', padding: '5px', color: '#000000' }}>القسم</th><th style={{ border: '1px solid #000', padding: '5px', color: '#000000' }}>المبلغ</th><th style={{ border: '1px solid #000', padding: '5px', color: '#000000' }}>التاريخ واليوم</th><th style={{ border: '1px solid #000', padding: '5px', color: '#000000' }}>الملاحظات</th></tr></thead>
          <tbody>{sortedExpensesForPdf.map(exp => (<tr key={exp.id}><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center', color: '#000000' }}>SRF-{exp.serialNumber}</td><td style={{ border: '1px solid #000', padding: '5px', color: '#000000' }}>{categories.find(c => c.id === exp.categoryId)?.name}</td><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center', color: '#000000' }}>{exp.amount.toLocaleString()}</td><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center', color: '#000000' }}>{exp.date} ({getDayName(exp.date)})</td><td style={{ border: '1px solid #000', padding: '5px', color: '#000000' }}>{exp.notes}</td></tr>))}</tbody>
        </table>
        <div style={{ marginTop: '20px', textAlign: 'left', fontWeight: 'bold', color: '#000000' }}>إجمالي المبلغ: {totalAmount.toLocaleString()} ريال يمني</div>
      </div>
    </div>
  );
};
export default ReportsView;

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Category, Expense } from '../types';
import { ChevronRight, Search, Calendar, FileText, Image as ImageIcon, Phone, PlusCircle, ChevronDown, ListFilter } from 'lucide-react';

interface CategoryDetailViewProps {
  category: Category;
  onBack: () => void;
  onExpenseSelect: (exp: Expense) => void;
  onAddExpense: () => void;
}

const CategoryDetailView: React.FC<CategoryDetailViewProps> = ({ category, onBack, onExpenseSelect, onAddExpense }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [search, setSearch] = useState('');
  const [total, setTotal] = useState(0);
  const [showAll, setShowAll] = useState(false); // حالة التحكم في عدد العناصر المعروضة

  useEffect(() => {
    const load = async () => {
      let exps = await db.expenses.where('categoryId').equals(category.id).toArray();

      // فرز السندات حسب تاريخ الإنشاء الفعلي (الأحدث أولاً)
      exps.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));

      setExpenses(exps);
      setTotal(exps.reduce((acc, curr) => acc + curr.amount, 0));
      setShowAll(false); // إعادة التعيين عند تغيير القسم
    };
    load();
  }, [category.id]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const filteredExpenses = expenses.filter(exp => 
    exp.notes?.toLowerCase().includes(search.toLowerCase()) || 
    exp.amount.toString().includes(search) ||
    (exp.serialNumber && `SRF-${exp.serialNumber}`.toLowerCase().includes(search.toLowerCase()))
  );

  // منطق عرض أول 15 أو الكل
  const displayedExpenses = showAll ? filteredExpenses : filteredExpenses.slice(0, 15);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4 mb-2">
        <button onClick={onBack} className="p-2 bg-slate-800/50 rounded-full hover:bg-slate-700 transition-colors">
          <ChevronRight size={20} />
        </button>
        <div>
          <h2 className="text-xl font-bold text-slate-100">{category.name}</h2>
          {category.phoneNumber && (
            <div className="flex items-center gap-1 text-[10px] text-slate-500 font-mono" dir="ltr">
              <Phone size={10} className="text-blue-500" />
              <span>+967 {category.phoneNumber}</span>
            </div>
          )}
        </div>
      </div>

      {/* Stats Card */}
      <div className="bg-slate-900 border border-slate-800 p-6 rounded-[2.5rem] text-center relative overflow-hidden group shadow-xl">
        <div className="relative z-10">
          <p className="text-slate-500 text-xs mb-1 font-bold uppercase tracking-widest">إجمالي مصروفات القسم</p>
          <h3 className="text-4xl font-black text-white tabular-nums">
            {total.toLocaleString('ar-SA')} 
            <span className="text-sm text-slate-500 mr-2 font-normal">ريال يمني</span>
          </h3>
        </div>
        <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/5 rounded-full -mr-16 -mt-16 blur-3xl group-hover:bg-blue-600/10 transition-all duration-700" />
      </div>

      {/* Action Button */}
      <button 
        onClick={onAddExpense}
        className="w-full bg-blue-600 hover:bg-blue-500 text-white font-black py-4 rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-blue-900/30 active:scale-95 transition-all"
      >
        <PlusCircle size={22} />
        <span>إضافة سند لـ {category.name}</span>
      </button>

      {/* Search Bar */}
      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18} />
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-4 py-3.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all shadow-inner"
          placeholder="بحث في سندات هذا القسم..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      {/* Expenses List */}
      <div className="space-y-3 pb-4">
