  const [draggedItem, setDraggedItem] = useState<number | null>(null);

  const handleDragStart = (id: number) => {
    setDraggedItem(id);
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
  };

  const handleDrop = (targetId: number) => {
    if (draggedItem === null || draggedItem === targetId) return;

    const reorderedCategories = [...categories];
    const draggedIndex = reorderedCategories.findIndex((c) => c.id === draggedItem);
    const targetIndex = reorderedCategories.findIndex((c) => c.id === targetId);

    const [item] = reorderedCategories.splice(draggedIndex, 1);
    reorderedCategories.splice(targetIndex, 0, item);

    onReorder(reorderedCategories);
    setDraggedItem(null);
  };

  return (
    <div>
      {categories.map((category) => (
        <div
          key={category.id}
          draggable
          onDragStart={() => handleDragStart(category.id)}
          onDragOver={handleDragOver}
          onDrop={() => handleDrop(category.id)}
          style={{
            border: '1px solid #ccc',
            padding: '10px',
            margin: '5px',
            cursor: 'move',
          }}
        >
          {category.name}
        </div>
      ))}
    </div>
  );
};

export default CategoriesView;
