import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Category, Expense } from '../types';
import { ChevronRight, Search, Calendar, FileText, Image as ImageIcon, Phone, PlusCircle, ChevronDown, ListFilter } from 'lucide-react';

interface CategoryDetailViewProps {
  category: Category;
  onBack: () => void;
  onExpenseSelect: (exp: Expense) => void;
  onAddExpense: () => void;
}

export default function CategoryDetailView({ category, onBack, onExpenseSelect, onAddExpense }: CategoryDetailViewProps) {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [search, setSearch] = useState('');
  const [total, setTotal] = useState(0);
  const [showAll, setShowAll] = useState(false);

  useEffect(() => {
    const load = async () => {
      let exps = await db.expenses.where('categoryId').equals(category.id).toArray();
      // فرز السندات حسب تاريخ الإنشاء الفعلي (الأحدث أولاً)
      exps.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
      setExpenses(exps);
      setTotal(exps.reduce((acc, curr) => acc + curr.amount, 0));
      setShowAll(false);
    };
    load();
  }, [category.id]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const filteredExpenses = expenses.filter(exp => 
    exp.notes?.toLowerCase().includes(search.toLowerCase()) || 
    exp.amount.toString().includes(search) ||
    (exp.serialNumber && `SRF-${exp.serialNumber}`.toLowerCase().includes(search.toLowerCase()))
  );

  const displayedExpenses = showAll ? filteredExpenses : filteredExpenses.slice(0, 15);

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex items-center gap-4 mb-2">
        <button onClick={onBack} className="p-2 bg-slate-800/50 rounded-full hover:bg-slate-700 transition-colors">
          <ChevronRight size={20} />
        </button>
        <div>
          <h2 className="text-xl font-bold text-slate-100">{category.name}</h2>
          {category.phoneNumber && (
            <div className="flex items-center gap-1 text-[10px] text-slate-500 font-mono" dir="ltr">
              <Phone size={10} className="text-blue-500" />
              <span>+967 {category.phoneNumber}</span>
            </div>
          )}
        </div>
      </div>

      <div className="bg-slate-900 border border-slate-800 p-6 rounded-[2.5rem] text-center relative overflow-hidden group shadow-xl">
        <div className="relative z-10">
          <p className="text-slate-500 text-xs mb-1 font-bold uppercase tracking-widest">إجمالي مصروفات القسم</p>
          <h3 className="text-4xl font-black text-white tabular-nums">
            {total.toLocaleString('ar-SA')} 
            <span className="text-sm text-slate-500 mr-2 font-normal">ريال يمني</span>
          </h3>
        </div>
        <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/5 rounded-full -mr-16 -mt-16 blur-3xl group-hover:bg-blue-600/10 transition-all duration-700" />
      </div>

      <button 
        onClick={onAddExpense}
        className="w-full bg-blue-600 hover:bg-blue-500 text-white font-black py-4 rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-blue-900/30 active:scale-95 transition-all"
      >
        <PlusCircle size={22} />
        <span>إضافة سند لـ {category.name}</span>
      </button>

      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18} />
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-4 py-3.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all shadow-inner"
          placeholder="بحث في سندات هذا القسم..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      <div className="space-y-3 pb-4">
        <div className="flex justify-between items-center px-1">
          <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] flex items-center gap-2">
            <ListFilter size={12} className="text-blue-500"/>
            العمليات الأخيرة ({filteredExpenses.length})
          </h4>
          {!showAll && filteredExpenses.length > 15 && (
            <span className="text-[9px] text-blue-500 font-bold bg-blue-500/10 px-2 py-0.5 rounded-full">يعرض 15 من {filteredExpenses.length}</span>
          )}
        </div>

        {displayedExpenses.map((exp) => (
          <div 
            key={exp.id} 
            className="bg-slate-900/60 border border-slate-800/40 rounded-2xl p-4 flex justify-between items-center active:bg-slate-800 transition-all cursor-pointer group"
            onClick={() => onExpenseSelect(exp)}
          >
            <div className="flex gap-4 items-center">
              <div className="w-10 h-10 rounded-xl bg-slate-800 border border-slate-700 flex items-center justify-center text-blue-500 font-black text-[10px] shadow-lg group-hover:border-blue-500/50 transition-colors">
                {exp.serialNumber ? `SRF-${exp.serialNumber}` : '---'}
              </div>
              <div>
                <h4 className="font-bold text-slate-200 tabular-nums">{exp.amount.toLocaleString('ar-SA')} ر.ي</h4>
                <div className="flex gap-2 items-center text-[9px] text-slate-500 mt-1 font-medium">
                  <Calendar size={10} className="text-slate-600" />
                  <span>{exp.date} ({getDayName(exp.date)})</span>
                  {exp.notes && <FileText size={10} className="text-slate-600" />}
                  {exp.image && <ImageIcon size={10} className="text-slate-600" />}
                </div>
              </div>
            </div>
            <ChevronRight size={16} className="text-slate-700 rotate-180 group-hover:text-blue-500 transition-colors" />
          </div>
        ))}

        {!showAll && filteredExpenses.length > 15 && (
          <button 
            onClick={() => setShowAll(true)}
            className="w-full py-4 mt-2 flex flex-col items-center justify-center gap-1 text-[11px] font-bold text-blue-500 bg-blue-600/5 border border-dashed border-blue-600/20 rounded-2xl active:scale-[0.98] transition-all hover:bg-blue-600/10"
          >
            <span>إظهار جميع السندات المتبقية ({filteredExpenses.length - 15})</span>
            <ChevronDown size={14} className="animate-bounce" />
          </button>
        )}

        {filteredExpenses.length === 0 && (
          <div className="text-center py-16 bg-slate-900/30 rounded-[2rem] border border-dashed border-slate-800/50">
            <div className="w-12 h-12 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-3">
              <Search size={20} className="text-slate-700" />
            </div>
            <p className="text-slate-600 text-xs font-bold">لا توجد نتائج مطابقة للبحث</p>
          </div>
        )}
      </div>
    </div>
  );
}

export interface Category {
  id: string;
  name: string;
  color: string;
  order: number;
  phoneNumber?: string; // حقل اختياري لرقم الهاتف
  isDefault?: boolean;
}

export interface Expense {
  id: string;
  categoryId: string;
  amount: number;
  date: string;
  notes?: string;
  image?: string; // base64
  createdAt: number;
  serialNumber?: number; // رقم تسلسلي (SRF-1)
  isFavorite?: boolean; // حقل السندات المميزة
}

export interface DraftExpense {
  id: string;
  categoryName: string;
  amount: number;
  notes: string;
  date: string;
}

export interface RecurringReminder {
  id: string;
  title: string;
  amount: number;
  categoryId: string;
  dayOfMonth: number;
}

export interface AppSettings {
  showImages: boolean;
  showNotes: boolean;
}

export enum ViewState {
  HOME = 'HOME',
  CATEGORIES = 'CATEGORIES',
  ADD_EXPENSE = 'ADD_EXPENSE',
  EDIT_EXPENSE = 'EDIT_EXPENSE',
  REPORTS = 'REPORTS',
  SETTINGS = 'SETTINGS',
  CATEGORY_DETAIL = 'CATEGORY_DETAIL',
  EXPENSE_DETAIL = 'EXPENSE_DETAIL'
}

import Dexie, { type Table } from 'dexie';
import { Category, Expense, AppSettings, RecurringReminder, DraftExpense } from './types';

// Define the database class extending Dexie
export class SarfDB extends Dexie {
  categories!: Table<Category>;
  expenses!: Table<Expense>;
  settings!: Table<AppSettings>;
  reminders!: Table<RecurringReminder>;
  drafts!: Table<DraftExpense>;

  constructor() {
    super('SarfDB');
    // Version 5 includes isFavorite in expenses
    (this as Dexie).version(5).stores({
      categories: 'id, name, order',
      expenses: 'id, categoryId, date, createdAt, isFavorite',
      settings: '',
      reminders: 'id, categoryId, dayOfMonth',
      drafts: 'id, categoryName'
    });
  }
}

export const db = new SarfDB();

export async function initializeDb() {
  const count = await db.categories.count();
  if (count === 0) {
    await db.categories.add({
      id: 'default_general',
      name: 'عام',
      color: '#3b82f6',
      order: 0,
      isDefault: true
    });
  }

  const settingsCount = await db.settings.count();
  if (settingsCount === 0) {
    await db.settings.put({
      showImages: true,
      showNotes: true
    }, 'app_settings');
  }
}

import React, { useState, useEffect } from 'react';
import { db, initializeDb } from './db';
import { ViewState, Category, Expense, AppSettings } from './types';
import { Plus, Home, PieChart, Settings as SettingsIcon, LayoutGrid } from 'lucide-react';

import HomeView from './components/HomeView';
import CategoriesView from './components/CategoriesView';
import AddExpenseView from './components/AddExpenseView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import CategoryDetailView from './components/CategoryDetailView';
import ExpenseDetailView from './components/ExpenseDetailView';
import SplashScreen from './components/SplashScreen';
import IntroScreen from './components/IntroScreen';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [editingExpense, setEditingExpense] = useState<Expense | null>(null);
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [initialized, setInitialized] = useState(false);

  const [showSplash, setShowSplash] = useState(true);
  const [showIntro, setShowIntro] = useState(false);

  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const init = async () => {
      const startTime = Date.now();

      await initializeDb();
      const s = await db.settings.get('app_settings');
      if (s) setSettings(s);
      setInitialized(true);

      const elapsedTime = Date.now() - startTime;
      const minSplashTime = 2500; 
      const remainingTime = Math.max(0, minSplashTime - elapsedTime);

      setTimeout(() => {
        setShowSplash(false);
        setShowIntro(true); 

        setTimeout(() => {
          setShowIntro(false);
        }, 2200);

      }, remainingTime);
    };
    init();

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  if (showSplash) return <SplashScreen />;

  if (!initialized || !settings) return (
    <div className="h-screen bg-slate-950 flex items-center justify-center text-white font-bold">
      جاري تحميل صرف...
    </div>
  );

  const handleExpenseSelect = (exp: Expense) => {
    setSelectedExpense(exp);
    setCurrentView(ViewState.EXPENSE_DETAIL);
  };

  const renderView = () => {
    switch (currentView) {
      case ViewState.HOME:
        return <HomeView onExpenseSelect={handleExpenseSelect} />;
      case ViewState.CATEGORIES:
        return <CategoriesView onCategorySelect={(cat) => { setSelectedCategory(cat); setCurrentView(ViewState.CATEGORY_DETAIL); }} />;
      case ViewState.ADD_EXPENSE:
        return <AddExpenseView onClose={() => { setEditingExpense(null); setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.HOME); }} initialData={editingExpense} preselectedCategoryId={selectedCategory?.id} />;
      case ViewState.REPORTS:
        return <ReportsView onExpenseSelect={handleExpenseSelect} />;
      case ViewState.SETTINGS:
        return <SettingsView onUpdateSettings={setSettings} installPrompt={deferredPrompt} onInstallSuccess={() => setDeferredPrompt(null)} onExpenseSelect={handleExpenseSelect} />;
      case ViewState.CATEGORY_DETAIL:
        return selectedCategory ? <CategoryDetailView category={selectedCategory} onBack={() => { setSelectedCategory(null); setCurrentView(ViewState.CATEGORIES); }} onExpenseSelect={handleExpenseSelect} onAddExpense={() => { setEditingExpense(null); setCurrentView(ViewState.ADD_EXPENSE); }} /> : null;
      case ViewState.EXPENSE_DETAIL:
        return selectedExpense ? <ExpenseDetailView expense={selectedExpense} onBack={() => setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.HOME)} onEdit={(exp) => { setEditingExpense(exp); setCurrentView(ViewState.ADD_EXPENSE); }} /> : null;
      default:
        return <HomeView onExpenseSelect={handleExpenseSelect} />;
    }
  };

  return (
    <>
      {showIntro && <IntroScreen />}

      <div className={`h-screen max-w-md mx-auto bg-slate-950 text-slate-100 flex flex-col relative shadow-2xl overflow-hidden transition-all duration-1000 ease-in-out ${showIntro ? 'blur-xl scale-95 opacity-50' : 'blur-0 scale-100 opacity-100'}`}>
        <header className="flex-none p-4 flex justify-center items-center border-b border-slate-800 bg-slate-950/80 backdrop-blur-md z-40">
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold bg-gradient-to-l from-blue-400 to-blue-600 bg-clip-text text-transparent">صرف</h1>
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-white shadow-lg shadow-blue-900/40">ص</div>
          </div>
        </header>

        <main className="flex-grow p-4 overflow-y-auto overflow-x-hidden pb-32 no-scrollbar">
          {renderView()}
        </main>

        <div className="fixed bottom-6 left-0 right-0 z-50 px-4 flex justify-center pointer-events-none">
          <nav className="w-full max-w-[calc(100%-1rem)] md:max-w-[400px] pointer-events-auto bg-slate-900/60 backdrop-blur-2xl border border-white/10 flex justify-around items-center p-2 rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.5)] relative">

            <button 
              onClick={() => { setSelectedCategory(null); setCurrentView(ViewState.HOME); }} 
              className={`flex flex-col items-center gap-1 transition-all duration-300 py-1 flex-1 ${currentView === ViewState.HOME ? 'text-blue-500 scale-110' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <Home size={20} /><span className="text-[9px] font-black">الرئيسية</span>
            </button>

            <button 
              onClick={() => { setSelectedCategory(null); setCurrentView(ViewState.CATEGORIES); }} 
              className={`flex flex-col items-center gap-1 transition-all duration-300 py-1 flex-1 ${currentView === ViewState.CATEGORIES || currentView === ViewState.CATEGORY_DETAIL ? 'text-blue-500 scale-110' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <LayoutGrid size={20} /><span className="text-[9px] font-black">الأقسام</span>
            </button>

            <div className="relative -mt-10 px-2">
              <button 
                onClick={() => { setEditingExpense(null); setCurrentView(ViewState.ADD_EXPENSE); }} 
                className="bg-blue-600 p-4 rounded-full shadow-[0_10px_25px_rgba(37,99,235,0.4)] text-white active:scale-90 transition-all ring-4 ring-slate-950 flex items-center justify-center group"
              >
                <Plus size={28} className="group-hover:rotate-90 transition-transform duration-300" />
              </button>
            </div>

            <button 
              onClick={() => setCurrentView(ViewState.REPORTS)} 
              className={`flex flex-col items-center gap-1 transition-all duration-300 py-1 flex-1 ${currentView === ViewState.REPORTS ? 'text-blue-500 scale-110' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <PieChart size={20} /><span className="text-[9px] font-black">التقارير</span>
            </button>

            <button 
              onClick={() => setCurrentView(ViewState.SETTINGS)}
              className={`flex flex-col items-center gap-1 transition-all duration-300 py-1 flex-1 ${currentView === ViewState.SETTINGS ? 'text-blue-500 scale-110' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <SettingsIcon size={20} /><span className="text-[9px] font-black">الضبط</span>
            </button>
          </nav>
        </div>
      </div>
    </>
  );
};

export default App;

