  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    db.categories.toArray().then(setCategories);
    if (!initialData && preselectedCategoryId) {
      setCategoryId(preselectedCategoryId);
    }
  }, [preselectedCategoryId, initialData]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleSave = async () => {
    const numAmount = parseFloat(amount);
    if (!numAmount || numAmount <= 0) {
      alert('الرجاء إدخال مبلغ صحيح أكبر من صفر');
      return;
    }

    let serialNumber = initialData?.serialNumber;

    if (!initialData) {
      const allExpenses = await db.expenses.toArray();
      const maxSerial = allExpenses.reduce((max, exp) => Math.max(max, exp.serialNumber || 0), 0);
      serialNumber = maxSerial + 1;
    }

    const expenseData: Expense = {
      id: initialData?.id || Date.now().toString(),
      amount: numAmount,
      categoryId,
      notes,
      date,
      image: image || undefined,
      createdAt: initialData?.createdAt || Date.now(),
      serialNumber,
      isFavorite
    };

    if (initialData) {
      await db.expenses.put(expenseData);
    } else {
      await db.expenses.add(expenseData);
    }
    onClose();
  };

  const handleDelete = async () => {
    if (initialData) {
      await db.expenses.delete(initialData.id);
      setIsConfirmOpen(false);
      onClose();
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6 pb-20">
      {/* Header with Save Button and Favorite Star */}
      <div className="flex items-center justify-between mb-4 sticky top-0 bg-slate-950/80 backdrop-blur-md z-10 py-2 -mx-4 px-4 border-b border-slate-800/50">
        <button onClick={onClose} className="p-2 text-slate-400 hover:text-white transition-colors">
          <X size={24} />
        </button>

        <div className="flex items-center gap-3">
          <button 
            onClick={() => setIsFavorite(!isFavorite)}
            className={`p-2 transition-all active:scale-125 ${isFavorite ? 'text-yellow-400 drop-shadow-[0_0_8px_rgba(250,204,21,0.5)]' : 'text-slate-600'}`}
          >
            <Star size={24} fill={isFavorite ? "currentColor" : "none"} />
          </button>

          <h2 className="text-lg font-bold text-slate-100">
            {initialData ? 'تعديل مصروف' : 'إضافة مصروف'}
          </h2>
        </div>

        <button 
          onClick={handleSave}
          className="bg-blue-600 hover:bg-blue-500 text-white font-bold px-5 py-2 rounded-xl shadow-lg shadow-blue-900/40 active:scale-95 transition-all flex items-center gap-2"
        >
          <Check size={18} />
          <span>حفظ</span>
        </button>
      </div>

      <div className="space-y-6">
        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">المبلغ (ريال يمني)</label>
          <input 
            type="number" 
            pattern="[0-9]*"
            inputMode="decimal"
            autoFocus
            className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-4 py-6 text-4xl font-black text-center text-blue-500 outline-none focus:ring-2 focus:ring-blue-500 tabular-nums shadow-inner"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            placeholder="0.00"
          />
        </div>

        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">القسم الضريبي / المالي</label>
          <div className="flex gap-2 overflow-x-auto pb-3 no-scrollbar">
            {categories.map(cat => (
              <button
                key={cat.id}
                onClick={() => setCategoryId(cat.id)}
                className={`flex-shrink-0 px-6 py-2.5 rounded-2xl border transition-all text-sm font-bold ${
                  categoryId === cat.id 
                    ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-900/40' 
                    : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-700'
                }`}
              >
                {cat.name}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 gap-4">
          <div>
            <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">تاريخ العملية</label>
            <div className="relative group">
              <input 
                type="date"
                className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-4 py-4 outline-none focus:ring-2 focus:ring-blue-500 text-white font-bold"
                value={date}
                onChange={(e) => setDate(e.target.value)}
              />
              <Calendar className="absolute left-4 top-4 text-slate-500 pointer-events-none" size={20} />
              <div className="absolute right-4 top-4 bg-blue-600/10 text-blue-500 px-3 py-1 rounded-lg text-[10px] font-black pointer-events-none border border-blue-500/20">
                {getDayName(date)}
              </div>
            </div>
          </div>
        </div>

        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">البيان / ملاحظات إضافية</label>
          <textarea 
            className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-4 py-4 outline-none focus:ring-2 focus:ring-blue-500 resize-none h-28 text-sm font-medium"
            placeholder="اكتب تفاصيل المصروف هنا (اختياري)..."
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
          />
        </div>

        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">المرفقات والصور</label>
          {image ? (
            <div className="relative group rounded-2xl overflow-hidden border border-slate-800 aspect-video bg-slate-900 shadow-xl">
              <img src={image} className="w-full h-full object-contain" alt="Expense attachment" />
              <button 
                onClick={() => setImage(null)}
                className="absolute top-3 right-3 bg-red-600 text-white p-2.5 rounded-xl shadow-lg active:scale-90 transition-all"
              >
                <Trash2 size={18} />
              </button>
            </div>
          ) : (
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full border-2 border-dashed border-slate-800 rounded-2xl p-10 flex flex-col items-center justify-center gap-3 text-slate-500 hover:border-blue-500 hover:text-blue-500 transition-all active:scale-[0.98] bg-slate-900/50"
            >
              <div className="p-4 bg-slate-800 rounded-2xl">
                <Camera size={32} />
              </div>
              <div className="text-center">
                <span className="font-bold text-sm block">تصوير فاتورة</span>
                <span className="text-[10px] opacity-60">أو اختيار ملف من الاستوديو</span>
              </div>
            </button>
          )}
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept="image/*" 
            onChange={handleImageUpload} 
          />
        </div>

        {initialData && (
          <div className="pt-4">
            <button 
              onClick={() => setIsConfirmOpen(true)}
              className="w-full p-4 bg-red-600/10 text-red-500 rounded-2xl hover:bg-red-600 hover:text-white transition-all font-bold flex items-center justify-center gap-2 border border-red-500/20 shadow-lg shadow-red-900/5"
            >
              <Trash2 size={20} />
              <span>حذف هذا المصروف نهائياً</span>
            </button>
          </div>
        )}
      </div>

      <ConfirmModal 
        isOpen={isConfirmOpen}
        title="حذف مصروف"
        message="هل أنت متأكد من حذف هذا المصروف؟ لا يمكن استعادة البيانات بعد الحذف."
        onConfirm={handleDelete}
        onCancel={() => setIsConfirmOpen(false)}
      />
    </div>
  );
};

export default AddExpenseView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { AppSettings, RecurringReminder, Category, DraftExpense, Expense } from '../types';
import { 
  Download, 
  Upload, 
  Trash2, 
  Bell, 
  Plus, 
  X, 
  Wand2, 
  CheckCircle2, 
  AlertCircle, 
  FileSearch, 
  Smartphone,
  AlertTriangle,
  Info,
  Calendar,
  Layers,
  Zap,
  Check,
  Camera,
  Loader2,
  Sparkles,
  Star,
  ChevronRight
} from 'lucide-react';
import ConfirmModal from './ConfirmModal';
import { GoogleGenAI, Type } from "@google/genai";

interface SettingsViewProps { 
  onUpdateSettings: (s: AppSettings) => void; 
  installPrompt: any; 
  onInstallSuccess: () => void;
  onExpenseSelect?: (exp: Expense) => void;
}

const SettingsView: React.FC<SettingsViewProps> = ({ onUpdateSettings, installPrompt, onInstallSuccess, onExpenseSelect }) => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [reminders, setReminders] = useState<RecurringReminder[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [drafts, setDrafts] = useState<DraftExpense[]>([]);

  // المميز
  const [isFavoritesOpen, setIsFavoritesOpen] = useState(false);
  const [favoriteExpenses, setFavoriteExpenses] = useState<Expense[]>([]);

  // حالات الفرز الذكي
  const [isSortingActive, setIsSortingActive] = useState(false);
  const [rawText, setRawText] = useState('');
  const [sortingDate, setSortingDate] = useState(new Date().toISOString().split('T')[0]);

  // حالات المسح الضوئي AI
  const [isScanning, setIsScanning] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // حالات "ضرب عصفورين بحجر"
  const [isMultiAddActive, setIsMultiAddActive] = useState(false);
  const [multiAmount, setMultiAmount] = useState('');
  const [multiNote, setMultiNote] = useState('');
  const [multiDate, setMultiDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCatIds, setSelectedCatIds] = useState<string[]>([]);

  const [confirmData, setConfirmData] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void } | null>(null);

  useEffect(() => {
    db.settings.get('app_settings').then(s => s && setSettings(s));
    loadData();
  }, []);

  const loadData = async () => {
    const [rems, drfs, cats] = await Promise.all([
      db.reminders.toArray(),
      db.drafts.toArray(),
      db.categories.toArray()
    ]);
    setReminders(rems);
    setDrafts(drfs);
    setCategories(cats);

    // تحميل المميز
    const favs = await db.expenses.where('isFavorite').equals(1).toArray();
    favs.sort((a, b) => b.createdAt - a.createdAt);
    setFavoriteExpenses(favs);
  };

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') onInstallSuccess();
  };

  const handleAIScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64Data = (reader.result as string).split(',')[1];

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: [
            {
              parts: [
                { inlineData: { data: base64Data, mimeType: file.type } },
                { text: "حلل هذه الفاتورة بدقة. استخرج: 1- المبلغ الإجمالي كرقم. 2- التاريخ بصيغة YYYY-MM-DD. 3- اسم المتجر بالعربي. 4- وصف موجز للمشتريات بالعربي. 5- رقم الفاتورة (إن وجد). أرجع النتيجة كـ JSON حصراً." }
              ]
            }
          ],
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.OBJECT,
              properties: {
                amount: { type: Type.NUMBER, description: "Total amount as a number" },
                date: { type: Type.STRING, description: "Receipt date YYYY-MM-DD" },
                storeName: { type: Type.STRING, description: "Store name in Arabic" },
                descriptionArabic: { type: Type.STRING, description: "Brief description in Arabic" },
                invoiceNumber: { type: Type.STRING, description: "Invoice number if found" }
              },
              required: ["amount", "date", "storeName", "descriptionArabic"]
            }
          }
        });

        const result = JSON.parse(response.text || '{}');

        if (result.amount) {
          let formattedNoteParts = [
            result.descriptionArabic || 'مشتريات',
            result.storeName || 'محل غير معروف'
          ];

          if (result.invoiceNumber) {
            formattedNoteParts.push(`رقم الفاتورة: ${result.invoiceNumber}`);
          }

          formattedNoteParts.push(`تاريخ الفاتورة: ${result.date}`);

          const finalNote = formattedNoteParts.join(' - ');

          await db.drafts.add({
            id: Math.random().toString(36).substr(2, 9),
            categoryName: 'عام',
            amount: result.amount,
            notes: `[AI مسح] ${finalNote}`,
            date: result.date || new Date().toISOString().split('T')[0]
          });
          loadData();
        }
      };
      reader.readAsDataURL(file);
    } catch (error) {
      console.error("AI Scan Error:", error);
      alert("عذراً، فشل تحليل الفاتورة. تأكد من جودة الصورة.");
    } finally {
      setIsScanning(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleProcessMultiAdd = async () => {
    const amountNum = parseFloat(multiAmount);
    if (!amountNum || selectedCatIds.length === 0) {
      alert('الرجاء إدخال المبلغ واختيار قسم واحد على الأقل');
      return;
    }

    const newDrafts: DraftExpense[] = selectedCatIds.map(id => {
      const cat = categories.find(c => c.id === id);
      return {
        id: Math.random().toString(36).substr(2, 9),
        categoryName: cat?.name || 'عام',
        amount: amountNum,
        notes: multiNote,
        date: multiDate 
      };
    });

    await db.drafts.bulkAdd(newDrafts);
    setMultiAmount('');
    setMultiNote('');
    setMultiDate(new Date().toISOString().split('T')[0]);
    setSelectedCatIds([]);
    setIsMultiAddActive(false);
    loadData();
  };

  const toggleCategorySelection = (id: string) => {
    setSelectedCatIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleParseText = async () => {
    const regex = /\*([^*]+)\*\s*\*([\d.]+)\*\s*\*([^*]+)\*/g;
    let match; 
    const newDrafts: DraftExpense[] = [];

    while ((match = regex.exec(rawText)) !== null) {
      newDrafts.push({ 
        id: Math.random().toString(36).substr(2, 9), 
        categoryName: match[1].trim(), 
        amount: parseFloat(match[2]), 
        notes: match[3].trim(), 
        date: sortingDate 
      });
    }

    if (newDrafts.length > 0) { 
      await db.drafts.bulkAdd(newDrafts); 
      setRawText(''); 
      setIsSortingActive(false); 
      loadData(); 
    } else { 
      alert('تأكد من الصيغة الصحيحة: *القسم* *المبلغ* *الملاحظة*'); 
    }
  };

  const confirmDraft = async (draft: DraftExpense) => {
    const cat = categories.find(c => c.name === draft.categoryName);
    if (!cat) return;

    const all = await db.expenses.toArray();
    const max = all.reduce((m, e) => Math.max(m, e.serialNumber || 0), 0);

    await db.expenses.add({ 
      id: Date.now().toString(), 
      categoryId: cat.id, 
      amount: draft.amount, 
      notes: draft.notes, 
      date: draft.date, 
      createdAt: Date.now(), 
      serialNumber: max + 1 
    });

    await db.drafts.delete(draft.id); 
    loadData();
  };

  const deleteDraft = async (id: string) => {
    await db.drafts.delete(id);
    loadData();
  };

  const exportData = async () => {
    const data = JSON.stringify({ 
      cats: await db.categories.toArray(), 
      exps: await db.expenses.toArray(), 
      sets: await db.settings.get('app_settings'), 
      rems: await db.reminders.toArray() 
    });
    const blob = new Blob([data], { type: 'application/json' });
    const a = document.createElement('a'); 
    a.href = URL.createObjectURL(blob); 
    a.download = `sarf_backup_${Date.now()}.json`; 
    a.click();
  };

  return (
    <div className="space-y-6 pb-12">
      <h2 className="text-xl font-bold mb-4">الإعدادات</h2>

      {installPrompt && (
        <div className="bg-blue-600/10 border border-blue-500/30 p-5 rounded-3xl flex flex-col items-center gap-3 text-center animate-in fade-in zoom-in mb-4">
          <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white"><Smartphone size={24}/></div>
          <div><h4 className="font-bold text-blue-400">ثبت صرف على جوالك</h4><p className="text-[10px] text-slate-500">للوصول السريع كأنه تطبيق APK حقيقي</p></div>
          <button onClick={handleInstallClick} className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl shadow-lg active:scale-95 transition-all">تثبيت الآن</button>
        </div>
      )}

      {/* ميزة السندات المميزة */}
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-5 space-y-4 shadow-xl">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-yellow-400/10 text-yellow-400 rounded-2xl border border-yellow-400/20">
              <Star size={24} fill="currentColor"/>
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-100">سندات مميزة</h3>
              <p className="text-[9px] text-slate-500 mt-0.5">الوصول السريع للسندات التي وضعت عليها نجمة</p>
            </div>
          </div>
          <button 
            onClick={() => setIsFavoritesOpen(true)}
            className="bg-yellow-400 hover:bg-yellow-500 text-slate-900 text-[10px] font-black px-4 py-2.5 rounded-xl shadow-lg shadow-yellow-900/20 transition-all active:scale-95"
          >
            عرض الكل ({favoriteExpenses.length})
          </button>
        </div>
      </div>

      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-5 space-y-4 shadow-xl relative overflow-hidden">
        <div className="absolute top-0 left-0 w-32 h-32 bg-blue-500/5 blur-3xl rounded-full -ml-16 -mt-16"></div>
        <div className="flex justify-between items-center relative z-10">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-blue-600/20 text-blue-400 rounded-2xl border border-blue-500/20">
              {isScanning ? <Loader2 size={24} className="animate-spin" /> : <Camera size={24}/>}
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-100 flex items-center gap-2">
                مسح الفواتير بالذكاء الاصطناعي
                <span className="bg-blue-600 text-[8px] px-1.5 py-0.5 rounded-full text-white uppercase font-black">AI</span>
              </h3>
              <p className="text-[9px] text-slate-500 mt-0.5">صور الفاتورة وسنقوم باستخراج كافة البيانات</p>
            </div>
          </div>
          <button 
            disabled={isScanning}
            onClick={() => fileInputRef.current?.click()}
            className="bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white text-[10px] font-bold px-4 py-2.5 rounded-xl shadow-lg shadow-blue-900/40 transition-all active:scale-95 flex items-center gap-1.5"
          >
            {isScanning ? 'جاري التحليل...' : 'مسح فاتورة'}
          </button>
        </div>
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleAIScan} capture="environment" />
      </div>

      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-5 space-y-4 shadow-xl">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="p-2 bg-indigo-500/20 text-indigo-400 rounded-xl">
              <Zap size={20}/>
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-200">ضرب عصفورين بحجر</h3>
              <p className="text-[9px] text-slate-500 mt-0.5">مبلغ واحد لعدة أقسام بضغطة واحدة</p>
            </div>
          </div>
          <button 
            onClick={() => setIsMultiAddActive(true)}
            className="bg-indigo-600 hover:bg-indigo-500 text-white text-[10px] font-bold px-4 py-2.5 rounded-xl shadow-lg shadow-indigo-900/20 transition-all active:scale-95 flex items-center gap-1.5"
          >
            <Plus size={14}/> ابدأ الآن
          </button>
        </div>
      </div>

      <div className="flex justify-between items-center px-2 pt-2">
        <div className="flex flex-col">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider">الفرز الذكي</h3>
          <p className="text-[9px] text-slate-600 mt-0.5">حوّل رسائل واتساب إلى سندات صرف فوراً</p>
        </div>
        <button onClick={() => setIsSortingActive(true)} className="bg-indigo-500/10 text-indigo-400 flex items-center gap-1 text-[10px] font-bold px-4 py-2 rounded-full border border-indigo-500/20 hover:bg-indigo-500/20 transition-colors">
          <Wand2 size={12}/> فرز رسائل
        </button>
      </div>

      {drafts.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center gap-2 px-2 text-blue-500">
            <Layers size={14} />
            <span className="text-[10px] font-bold uppercase tracking-widest">المسودات المعلقة ({drafts.length})</span>
          </div>
          {drafts.map(d => {
            const categoryExists = categories.some(c => c.name === d.categoryName);
            const isAIScan = d.notes.includes('[AI مسح]');

            return (
              <div 
                key={d.id} 
                className={`group relative overflow-hidden p-4 rounded-2xl border transition-all duration-300 ${
                  categoryExists 
                    ? 'bg-slate-900/40 border-slate-800 hover:border-blue-500/50' 
                    : 'bg-red-500/5 border-red-500/20'
                }`}
              >
                {isAIScan && (
                  <div className="absolute top-0 left-0 bg-blue-600 text-[8px] text-white px-2 py-0.5 rounded-br-lg font-bold">AI SCAN</div>
                )}
                {!categoryExists && (
