        <div>
          <h2 className="text-xl font-bold text-slate-100">{category.name}</h2>
          {category.phoneNumber && (
            <div className="flex items-center gap-1 text-[10px] text-slate-500 font-mono" dir="ltr">
              <Phone size={10} className="text-blue-500" />
              <span>+967 {category.phoneNumber}</span>
            </div>
          )}
        </div>
      </div>

      <div className="bg-slate-900 border border-slate-800 p-6 rounded-[2.5rem] text-center relative overflow-hidden group shadow-xl">
        <div className="relative z-10">
          <p className="text-slate-500 text-xs mb-1 font-bold uppercase tracking-widest">إجمالي مصروفات القسم</p>
          <h3 className="text-4xl font-black text-white tabular-nums">
            {total.toLocaleString('ar-SA')} 
            <span className="text-sm text-slate-500 mr-2 font-normal">ريال يمني</span>
          </h3>
        </div>
        <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/5 rounded-full -mr-16 -mt-16 blur-3xl group-hover:bg-blue-600/10 transition-all duration-700" />
      </div>

      <button 
        onClick={onAddExpense}
        className="w-full bg-blue-600 hover:bg-blue-500 text-white font-black py-4 rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-blue-900/30 active:scale-95 transition-all"
      >
        <PlusCircle size={22} />
        <span>إضافة سند لـ {category.name}</span>
      </button>

      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18} />
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-4 py-3.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all shadow-inner"
          placeholder="بحث في سندات هذا القسم..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      <div className="space-y-3 pb-4">
        <div className="flex justify-between items-center px-1">
          <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] flex items-center gap-2">
            <ListFilter size={12} className="text-blue-500"/>
            العمليات الأخيرة ({filteredExpenses.length})
