          {!showAll && filteredExpenses.length > 15 && (
            <span className="text-[9px] text-blue-500 font-bold bg-blue-500/10 px-2 py-0.5 rounded-full">يعرض 15 من {filteredExpenses.length}</span>
          )}
        </div>

        {displayedExpenses.map((exp) => (
          <div 
            key={exp.id} 
            className="bg-slate-900/60 border border-slate-800/40 rounded-2xl p-4 flex justify-between items-center active:bg-slate-800 transition-all cursor-pointer group relative overflow-hidden"
            onClick={() => onExpenseSelect(exp)}
          >
            {exp.isFavorite && (
              <div className="absolute top-0 right-0 p-1.5 bg-yellow-400/10 rounded-bl-xl">
                <Star size={10} className="text-yellow-400 fill-yellow-400" />
