            )}
            <div className="flex gap-4 items-center">
              <div className="w-10 h-10 rounded-xl bg-slate-800 border border-slate-700 flex items-center justify-center text-blue-500 font-black text-[10px] shadow-lg group-hover:border-blue-500/50 transition-colors">
                {exp.serialNumber ? `SRF-${exp.serialNumber}` : '---'}
              </div>
              <div>
                <h4 className="font-bold text-slate-200 tabular-nums">{exp.amount.toLocaleString('ar-SA')} ر.ي</h4>
                <div className="flex gap-2 items-center text-[9px] text-slate-500 mt-1 font-medium">
                  <Calendar size={10} className="text-slate-600" />
