  const voucherRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    db.categories.get(expense.categoryId).then(cat => setCategory(cat || null));
  }, [expense.categoryId]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleDeleteToTrash = async () => {
    // نقل للسلة قبل الحذف من جدول المصروفات
    await db.trash.add(expense);
    await db.expenses.delete(expense.id);
    onBack();
  };

  const generateVoucherPDF = async () => {
    setIsGeneratingVoucher(true);
    try {
      const element = voucherRef.current;
      if (!element) return;
      element.style.display = 'block';
      element.style.position = 'fixed';
      element.style.left = '-10000px';
      await new Promise(r => setTimeout(r, 800));
      const canvas = await html2canvas(element, { scale: 3, useCORS: true, backgroundColor: '#ffffff' });
      element.style.display = 'none';
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a5' });
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      window.open(pdf.output('bloburl'), '_blank');
    } catch (error) {
      alert('خطأ في استخراج السند');
    } finally {
      setIsGeneratingVoucher(false);
    }
  };

  const hasAttachments = !!(expense.notes || expense.image);

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
      {/* Header */}
      <div className="flex items-center justify-between mb-2">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-full hover:bg-slate-700 transition-colors">
          <ChevronRight size={20} />
        </button>
        <div className="text-center">
          <h2 className="text-xl font-bold">تفاصيل المصروف</h2>
          <p className="text-[10px] text-blue-500 font-mono font-bold tracking-widest uppercase">SRF-{expense.serialNumber}</p>
        </div>
        <button onClick={() => setIsConfirmOpen(true)} className="p-2 bg-red-600/10 text-red-500 rounded-full hover:bg-red-600 hover:text-white transition-all">
          <Trash2 size={20} />
        </button>
      </div>

      {/* Amount Hero Section */}
      <div className="bg-slate-900 rounded-[2.5rem] p-8 border border-slate-800 text-center shadow-xl relative overflow-hidden">
        {expense.isFavorite && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 opacity-20">
            <Star size={100} className="text-yellow-400 fill-yellow-400 blur-sm" />
          </div>
        )}
        <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/10 rounded-full -mr-16 -mt-16 blur-3xl opacity-50" />

        <div className="relative z-10">
          <p className="text-slate-500 text-sm mb-2 font-medium">المبلغ المصروف</p>
          <div className="flex items-center justify-center gap-2">
            {expense.isFavorite && <Star size={24} className="text-yellow-400 fill-yellow-400 animate-pulse" />}
            <h3 className="text-5xl font-black text-blue-500 tabular-nums">
              {expense.amount.toLocaleString('ar-SA')} 
            </h3>
          </div>
          <p className="text-lg text-slate-500 font-bold">ريال يمني</p>
        </div>
      </div>

      {/* Data Grid */}
      <div className="bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden divide-y divide-slate-800 shadow-lg">
        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800 rounded-xl flex items-center justify-center text-slate-500">
            <Hash size={18} />
          </div>
          <div className="flex-grow">
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider mb-0.5">الرقم التسلسلي</p>
            <p className="font-bold text-slate-200">SRF - {expense.serialNumber}</p>
          </div>
        </div>
        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800 rounded-xl flex items-center justify-center text-slate-500">
            <Tag size={18} />
          </div>
          <div className="flex-grow">
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider mb-0.5">الجهة / القسم</p>
            <p className="font-bold text-slate-200">{category?.name || 'عام'}</p>
          </div>
        </div>
        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800 rounded-xl flex items-center justify-center text-slate-500">
            <Calendar size={18} />
          </div>
          <div>
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider mb-0.5">تاريخ الصرف</p>
            <p className="font-bold text-slate-200">{expense.date} <span className="text-xs opacity-60 mr-1">({getDayName(expense.date)})</span></p>
          </div>
        </div>
      </div>

      {/* Notes & Image */}
      {hasAttachments && (
        <div className="space-y-4">
          {expense.notes && (
            <div className="bg-slate-900/40 rounded-3xl border border-slate-800/50 p-6 shadow-inner relative">
              <div className="flex items-center gap-2 mb-3">
                <FileText size={16} className="text-blue-500" />
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">البيان / الملاحظات</p>
              </div>
              <p className="text-slate-300 text-sm leading-relaxed whitespace-pre-wrap">{expense.notes}</p>
            </div>
          )}
          {expense.image && (
            <div className="bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden shadow-xl">
              <img src={expense.image} className="w-full h-auto max-h-[500px] object-contain" alt="Expense" />
            </div>
          )}
        </div>
      )}

      {/* Action Buttons */}
      <div className="grid grid-cols-2 gap-3 pt-4">
        <button 
          onClick={() => onEdit(expense)} 
          className="bg-slate-800 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 active:scale-95 transition-all hover:bg-slate-700"
        >
          <Edit3 size={20} />
          <span>تعديل</span>
        </button>
        <button 
          disabled={isGeneratingVoucher} 
          onClick={generateVoucherPDF} 
          className="bg-blue-600 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 shadow-xl shadow-blue-900/20 active:scale-95 transition-all hover:bg-blue-500 disabled:opacity-50"
        >
          {isGeneratingVoucher ? <Loader2 size={20} className="animate-spin" /> : <ExternalLink size={20} />}
          <span>عرض السند</span>
        </button>
      </div>

      <ConfirmModal 
        isOpen={isConfirmOpen} 
        title="أرشفة السند" 
        message="هل أنت متأكد من حذف هذا السند؟ سيتم نقله إلى سلة المهملات." 
        onConfirm={handleDeleteToTrash} 
        onCancel={() => setIsConfirmOpen(false)} 
      />

      {/* قالب السند الرسمي للطباعة */}
      <div ref={voucherRef} dir="rtl" style={{ display: 'none', width: '148mm', padding: '12mm', backgroundColor: '#ffffff', color: '#1e293b', fontFamily: "'Tajawal', Arial" }}>
        <div style={{ border: '1.5mm double #3b82f6', padding: '10mm', height: '100%', borderRadius: '4px', position: 'relative', display: 'flex', flexDirection: 'column' }}>

          <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #e2e8f0', paddingBottom: '6mm', marginBottom: '8mm' }}>
            <div>
              <h1 style={{ fontSize: '24px', fontWeight: '900', color: '#1e3a8a', margin: '0 0 2mm 0' }}>سند صــرف مالي</h1>
              <p style={{ fontSize: '10px', color: '#64748b', margin: 0 }}>نظام صرف لإدارة المصروفات الشخصية</p>
            </div>
            <div style={{ textAlign: 'left', fontSize: '11px', color: '#1e293b' }}>
              <p style={{ margin: '0 0 1mm 0' }}>الرقم: <span style={{ fontWeight: 'bold' }}>SRF-{expense.serialNumber}</span></p>
              <p style={{ margin: 0 }}>التاريخ: <span style={{ fontWeight: 'bold' }}>{expense.date}</span></p>
            </div>
          </div>

          <div style={{ flexGrow: 1 }}>
            <div style={{ marginBottom: '6mm', display: 'flex', gap: '4px' }}>
              <span style={{ fontSize: '13px', color: '#64748b' }}>يصرف لـ:</span>
              <span style={{ fontSize: '15px', fontWeight: 'bold', borderBottom: '1px dashed #cbd5e1', flexGrow: 1 }}>{category?.name || 'عام'}</span>
            </div>

            <div style={{ backgroundColor: '#f8fafc', border: '1px solid #e2e8f0', padding: '6mm', borderRadius: '4px', marginBottom: '8mm', textAlign: 'center' }}>
              <p style={{ fontSize: '10px', color: '#64748b', marginBottom: '2mm' }}>مبلغ وقدره</p>
              <h2 style={{ fontSize: '28px', fontWeight: '900', color: '#1d4ed8', margin: 0, tabularNums: true }}>
                {expense.amount.toLocaleString()} <span style={{ fontSize: '14px' }}>ريال يمني</span>
              </h2>
            </div>

            <div style={{ display: 'flex', gap: '4px', alignItems: 'start' }}>
              <span style={{ fontSize: '13px', color: '#64748b', whiteSpace: 'nowrap' }}>وذلك مقابل:</span>
              <span style={{ fontSize: '13px', lineHeight: '1.6', flexGrow: 1 }}>{expense.notes || 'مصروفات متنوعة.'}</span>
            </div>
          </div>

          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '15mm', borderTop: '1px solid #f1f5f9', paddingTop: '10mm' }}>
            <div style={{ textAlign: 'center', width: '40%' }}>
              <p style={{ margin: '0 0 12mm 0', fontSize: '11px', fontWeight: 'bold', color: '#475569' }}>توقيع المستلم</p>
              <div style={{ height: '0.3mm', width: '100%', backgroundColor: '#cbd5e1' }}></div>
            </div>
            <div style={{ textAlign: 'center', width: '40%' }}>
              <p style={{ margin: '0 0 12mm 0', fontSize: '11px', fontWeight: 'bold', color: '#475569' }}>المحاسب / المدير</p>
              <div style={{ height: '0.3mm', width: '100%', backgroundColor: '#1e3a8a' }}></div>
            </div>
          </div>

          <p style={{ position: 'absolute', bottom: '4mm', left: '0', right: '0', textAlign: 'center', fontSize: '8px', color: '#94a3b8' }}>
            صدر هذا السند إلكترونياً عبر تطبيق صرف - {new Date().toLocaleTimeString('ar-YE')}
          </p>
        </div>
      </div>
    </div>
  );
};

export default ExpenseDetailView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { AppSettings, RecurringReminder, Category, DraftExpense, Expense } from '../types';
import { 
  Download, 
  Upload, 
  Trash2, 
  Bell, 
  Plus, 
  X, 
  Wand2, 
  CheckCircle2, 
  AlertCircle, 
  FileSearch, 
  Smartphone,
  AlertTriangle,
  Info,
  Calendar,
  Layers,
  Zap,
  Check,
  Camera,
  Loader2,
  Sparkles,
  Star,
  ChevronRight,
  RotateCcw
} from 'lucide-react';
import ConfirmModal from './ConfirmModal';
import { GoogleGenAI, Type } from "@google/genai";

interface SettingsViewProps { 
  onUpdateSettings: (s: AppSettings) => void; 
  installPrompt: any; 
  onInstallSuccess: () => void;
  onExpenseSelect?: (exp: Expense) => void;
}

const SettingsView: React.FC<SettingsViewProps> = ({ onUpdateSettings, installPrompt, onInstallSuccess, onExpenseSelect }) => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [reminders, setReminders] = useState<RecurringReminder[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [drafts, setDrafts] = useState<DraftExpense[]>([]);

  // المميز والسلة
  const [isFavoritesOpen, setIsFavoritesOpen] = useState(false);
  const [favoriteExpenses, setFavoriteExpenses] = useState<Expense[]>([]);
  const [isTrashOpen, setIsTrashOpen] = useState(false);
  const [trashExpenses, setTrashExpenses] = useState<Expense[]>([]);

  // حالات الفرز الذكي
  const [isSortingActive, setIsSortingActive] = useState(false);
  const [rawText, setRawText] = useState('');
  const [sortingDate, setSortingDate] = useState(new Date().toISOString().split('T')[0]);

  // حالات المسح الضوئي AI
  const [isScanning, setIsScanning] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // حالات "ضرب عصفورين بحجر"
  const [isMultiAddActive, setIsMultiAddActive] = useState(false);
  const [multiAmount, setMultiAmount] = useState('');
  const [multiNote, setMultiNote] = useState('');
  const [multiDate, setMultiDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCatIds, setSelectedCatIds] = useState<string[]>([]);

  const [confirmData, setConfirmData] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void } | null>(null);

  useEffect(() => {
    db.settings.get('app_settings').then(s => s && setSettings(s));
    loadData();
  }, []);

  const loadData = async () => {
    const [rems, drfs, cats, trashItems] = await Promise.all([
      db.reminders.toArray(),
      db.drafts.toArray(),
      db.categories.toArray(),
      db.trash.toArray()
    ]);
    setReminders(rems);
    setDrafts(drfs);
    setCategories(cats);
    setTrashExpenses(trashItems.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0)));

    // تحميل السندات التي تم تفعيل النجمة عليها
    const favs = await db.expenses.where('isFavorite').equals(1).toArray();
    favs.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
    setFavoriteExpenses(favs);
  };

  const restoreFromTrash = async (exp: Expense) => {
    await db.expenses.add(exp);
    await db.trash.delete(exp.id);
    loadData();
  };

  const deleteFromTrashForever = async (id: string) => {
    await db.trash.delete(id);
    loadData();
  };

  const emptyTrash = async () => {
    if (confirm('هل أنت متأكد من تفريغ السلة نهائياً؟')) {
      await db.trash.clear();
      loadData();
    }
  };

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') onInstallSuccess();
  };

  const handleAIScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64Data = (reader.result as string).split(',')[1];

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: [
            {
              parts: [
                { inlineData: { data: base64Data, mimeType: file.type } },
                { text: "حلل هذه الفاتورة بدقة. استخرج: 1- المبلغ الإجمالي كرقم. 2- التاريخ بصيغة YYYY-MM-DD. 3- اسم المتجر بالعربي. 4- وصف موجز للمشتريات بالعربي. 5- رقم الفاتورة (إن وجد). أرجع النتيجة كـ JSON حصراً." }
              ]
            }
          ],
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.OBJECT,
              properties: {
                amount: { type: Type.NUMBER, description: "Total amount as a number" },
                date: { type: Type.STRING, description: "Receipt date YYYY-MM-DD" },
                storeName: { type: Type.STRING, description: "Store name in Arabic" },
                descriptionArabic: { type: Type.STRING, description: "Brief description in Arabic" },
                invoiceNumber: { type: Type.STRING, description: "Invoice number if found" }
              },
              required: ["amount", "date", "storeName", "descriptionArabic"]
            }
          }
        });

        const result = JSON.parse(response.text || '{}');

        if (result.amount) {
          let formattedNoteParts = [
            result.descriptionArabic || 'مشتريات',
            result.storeName || 'محل غير معروف'
          ];

          if (result.invoiceNumber) {
            formattedNoteParts.push(`رقم الفاتورة: ${result.invoiceNumber}`);
          }

          formattedNoteParts.push(`تاريخ الفاتورة: ${result.date}`);

          const finalNote = formattedNoteParts.join(' - ');

          await db.drafts.add({
            id: Math.random().toString(36).substr(2, 9),
            categoryName: 'عام',
            amount: result.amount,
            notes: `[AI مسح] ${finalNote}`,
            date: result.date || new Date().toISOString().split('T')[0]
          });
          loadData();
        }
      };
      reader.readAsDataURL(file);
    } catch (error) {
      console.error("AI Scan Error:", error);
      alert("عذراً، فشل تحليل الفاتورة. تأكد من جودة الصورة.");
    } finally {
      setIsScanning(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleProcessMultiAdd = async () => {
    const amountNum = parseFloat(multiAmount);
    if (!amountNum || selectedCatIds.length === 0) {
      alert('الرجاء إدخال المبلغ واختيار قسم واحد على الأقل');
      return;
    }

    const newDrafts: DraftExpense[] = selectedCatIds.map(id => {
      const cat = categories.find(c => c.id === id);
      return {
        id: Math.random().toString(36).substr(2, 9),
        categoryName: cat?.name || 'عام',
        amount: amountNum,
        notes: multiNote,
        date: multiDate 
      };
    });

    await db.drafts.bulkAdd(newDrafts);
    setMultiAmount('');
    setMultiNote('');
    setMultiDate(new Date().toISOString().split('T')[0]);
    setSelectedCatIds([]);
    setIsMultiAddActive(false);
    loadData();
  };

  const toggleCategorySelection = (id: string) => {
    setSelectedCatIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleParseText = async () => {
    const regex = /\*([^*]+)\*\s*\*([\d.]+)\*\s*\*([^*]+)\*/g;
    let match; 
    const newDrafts: DraftExpense[] = [];

    while ((match = regex.exec(rawText)) !== null) {
      newDrafts.push({ 
        id: Math.random().toString(36).substr(2, 9), 
        categoryName: match[1].trim(), 
        amount: parseFloat(match[2]), 
        notes: match[3].trim(), 
        date: sortingDate 
      });
    }

    if (newDrafts.length > 0) { 
      await db.drafts.bulkAdd(newDrafts); 
      setRawText(''); 
      setIsSortingActive(false); 
      loadData(); 
    } else { 
      alert('تأكد من الصيغة الصحيحة: *القسم* *المبلغ* *الملاحظة*'); 
    }
  };

  const confirmDraft = async (draft: DraftExpense) => {
    const cat = categories.find(c => c.name === draft.categoryName);
    if (!cat) return;

    const all = await db.expenses.toArray();
    const max = all.reduce((m, e) => Math.max(m, e.serialNumber || 0), 0);

    await db.expenses.add({ 
      id: Date.now().toString(), 
      categoryId: cat.id, 
      amount: draft.amount, 
      notes: draft.notes, 
      date: draft.date, 
      createdAt: Date.now(), 
      serialNumber: max + 1 
    });

    await db.drafts.delete(draft.id); 
    loadData();
  };

  const deleteDraft = async (id: string) => {
    await db.drafts.delete(id);
    loadData();
  };

  const exportData = async () => {
    const data = JSON.stringify({ 
      cats: await db.categories.toArray(), 
      exps: await db.expenses.toArray(), 
      sets: await db.settings.get('app_settings'), 
      rems: await db.reminders.toArray() 
    });
    const blob = new Blob([data], { type: 'application/json' });
    const a = document.createElement('a'); 
    a.href = URL.createObjectURL(blob); 
    a.download = `sarf_backup_${Date.now()}.json`; 
    a.click();
  };

  return (
    <div className="space-y-6 pb-12">
      <h2 className="text-xl font-bold mb-4">الإعدادات</h2>

      {installPrompt && (
        <div className="bg-blue-600/10 border border-blue-500/30 p-5 rounded-3xl flex flex-col items-center gap-3 text-center animate-in fade-in zoom-in mb-4">
          <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white"><Smartphone size={24}/></div>
          <div><h4 className="font-bold text-blue-400">ثبت صرف على جوالك</h4><p className="text-[10px] text-slate-500">للوصول السريع كأنه تطبيق APK حقيقي</p></div>
          <button onClick={handleInstallClick} className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl shadow-lg active:scale-95 transition-all">تثبيت الآن</button>
        </div>
      )}

      {/* خانات الأرشفة والتمييز */}
      <div className="grid grid-cols-2 gap-4">
        {/* خانة مميز */}
        <div className="bg-slate-900 border border-slate-800 rounded-3xl p-5 space-y-3 shadow-xl flex flex-col items-center text-center">
          <div className="p-3 bg-yellow-400/10 text-yellow-400 rounded-2xl border border-yellow-400/20">
            <Star size={24} fill="currentColor"/>
          </div>
          <div>
            <h3 className="text-sm font-bold text-slate-100">مميز</h3>
            <p className="text-[9px] text-slate-500 mt-0.5">سنداتك الهامة</p>
          </div>
          <button 
            onClick={() => setIsFavoritesOpen(true)}
            className="w-full bg-slate-800 hover:bg-slate-700 text-yellow-400 text-[10px] font-black px-3 py-2.5 rounded-xl transition-all active:scale-95"
          >
            فتح ({favoriteExpenses.length})
          </button>
        </div>

        {/* خانة سلة */}
        <div className="bg-slate-900 border border-slate-800 rounded-3xl p-5 space-y-3 shadow-xl flex flex-col items-center text-center">
          <div className="p-3 bg-red-500/10 text-red-500 rounded-2xl border border-red-500/20">
            <Trash2 size={24} />
          </div>
          <div>
            <h3 className="text-sm font-bold text-slate-100">سلة</h3>
            <p className="text-[9px] text-slate-500 mt-0.5">الأرشيف المحذوف</p>
          </div>
          <button 
            onClick={() => setIsTrashOpen(true)}
