            </div>

            <div className="flex-grow overflow-y-auto p-4 space-y-3 no-scrollbar pb-10">
              {trashExpenses.length > 0 ? (
                trashExpenses.map(exp => {
                  const cat = categories.find(c => c.id === exp.categoryId);
                  return (
                    <div 
                      key={exp.id} 
                      className="bg-slate-800/30 border border-slate-800 rounded-2xl p-4 flex justify-between items-center group"
