                        </div>
                      </div>

                      <div className="flex gap-2">
                        <button 
                          onClick={() => handleRestoreRequest(exp)}
                          title="استعادة السند"
                          className="p-2 bg-green-600/10 text-green-500 rounded-xl hover:bg-green-600 hover:text-white transition-all active:scale-90"
