export default ExpenseDetailView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { FileDown, TrendingUp, Calendar, MessageCircle, ChevronRight, Search, X, ExternalLink, Download, FileText, Layers, ChevronDown, Star, Tag, Hash } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface ReportsViewProps { onExpenseSelect?: (exp: Expense) => void; }

const ReportsView: React.FC<ReportsViewProps> = ({ onExpenseSelect }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [availableTags, setAvailableTags] = useState<string[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [selectedTag, setSelectedTag] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showPdfMenu, setShowPdfMenu] = useState(false);
  const [showAll, setShowAll] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusMessage, setStatusMessage] = useState('');
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);

      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();

      // استخراج كافة الوسوم المتاحة في هذه الفترة
      const tags = Array.from(new Set(results.flatMap(e => e.tags || []))).sort();
      setAvailableTags(tags);

      if (selectedCategoryId !== 'all') results = results.filter(e => e.categoryId === selectedCategoryId);
      if (selectedTag) results = results.filter(e => e.tags?.includes(selectedTag));

      results.sort((a, b) => b.createdAt - a.createdAt);
      setExpenses(results);
      setShowAll(false);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId, selectedTag]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const processPDF = async (action: 'download' | 'view') => {
    if (expenses.length === 0 || isGenerating) return;
    setIsGenerating(true); 
    setShowPdfMenu(false); 
    setProgress(10); 
    setStatusMessage('جاري تحضير البيانات...');
    try {
      const element = reportRef.current;
      if (!element) return;
      await new Promise(r => setTimeout(r, 500)); 
      setProgress(40); 
      setStatusMessage('جاري التقاط لقطات عالية الجودة...');
      element.style.display = 'block'; 
      element.style.visibility = 'visible'; 
      element.style.position = 'fixed'; 
      element.style.left = '-10000px';
      const canvas = await html2canvas(element, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
      element.style.display = 'none'; 
      setProgress(80); 
      setStatusMessage('جاري تحويل البيانات إلى ملف PDF...');
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      setProgress(100); 
      setStatusMessage('اكتملت العملية!');
      await new Promise(r => setTimeout(r, 500));
      if (action === 'download') pdf.save(`تقرير_صرف_${fromDate}.pdf`);
      else window.open(pdf.output('bloburl'), '_blank');
    } catch (error) { alert('حدث خطأ أثناء معالجة التقرير.'); } 
    finally { setIsGenerating(false); setProgress(0); setStatusMessage(''); }
  };

  const shareViaWhatsApp = () => {
    const totalVal = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
    const message = `*كشف مصروفات - تطبيق صرف*\n\n` +
                    `*الفترة:* من ${fromDate} إلى ${toDate}\n` +
                    (selectedTag ? `*الوسم:* ${selectedTag}\n` : '') +
                    `*الإجمالي:* ${totalVal.toLocaleString()} ر.ي\n` +
                    `*عدد العمليات:* ${filteredExpenses.length}\n\n` +
                    `_تم التصدير بواسطة تطبيق صرف المالي_`;
    const url = `https://wa.me/?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const filteredExpenses = expenses.filter(exp => 
    exp.notes?.toLowerCase().includes(searchQuery.toLowerCase()) || 
    exp.amount.toString().includes(searchQuery) ||
    exp.tags?.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  const totalAmount = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
  const displayedExpenses = showAll ? filteredExpenses : filteredExpenses.slice(0, 15);
  const sortedExpensesForPdf = [...filteredExpenses].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  return (
    <div className="space-y-6 pb-10 animate-in fade-in duration-500">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="text-xs text-slate-500 mb-1 flex items-center gap-1"><Calendar size={12}/> من تاريخ</label>
          <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400" value={fromDate} onChange={e => setFromDate(e.target.value)}/>
          <span className="text-[9px] text-slate-600 block mt-1">{getDayName(fromDate)}</span>
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="text-xs text-slate-500 mb-1 flex items-center gap-1"><Calendar size={12}/> إلى تاريخ</label>
          <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400" value={toDate} onChange={e => setToDate(e.target.value)}/>
          <span className="text-[9px] text-slate-600 block mt-1">{getDayName(toDate)}</span>
        </div>
      </div>

      <div className="space-y-2">
        <label className="text-xs text-slate-500 px-1 flex items-center gap-1"><Layers size={12}/> تصفية حسب القسم</label>
        <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
          <button onClick={() => setSelectedCategoryId('all')} className={`flex-shrink-0 px-5 py-2 rounded-full border text-sm font-bold transition-all ${selectedCategoryId === 'all' ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>الكل</button>
          {categories.map(cat => (
            <button key={cat.id} onClick={() => setSelectedCategoryId(cat.id)} className={`flex-shrink-0 px-5 py-2 rounded-full border text-sm font-bold transition-all ${selectedCategoryId === cat.id ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>{cat.name}</button>
          ))}
        </div>
      </div>

      {availableTags.length > 0 && (
        <div className="space-y-2">
          <label className="text-xs text-slate-500 px-1 flex items-center gap-1"><Tag size={12}/> فلترة حسب الوسم والمناسبة</label>
          <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
            <button onClick={() => setSelectedTag(null)} className={`flex-shrink-0 px-5 py-2 rounded-full border text-[10px] font-black transition-all ${!selectedTag ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>بدون وسم</button>
            {availableTags.map(tag => (
              <button key={tag} onClick={() => setSelectedTag(tag === selectedTag ? null : tag)} className={`flex-shrink-0 px-5 py-2 rounded-full border text-[10px] font-black transition-all ${selectedTag === tag ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>{tag}</button>
            ))}
          </div>
        </div>
      )}

      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18}/>
        <input className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-10 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none shadow-inner" placeholder="بحث بالوصف، المبلغ، أو الوسوم (#)..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)}/>
      </div>

      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-6 rounded-[2rem] shadow-xl text-white flex justify-between items-center relative overflow-hidden">
        <div className="absolute top-0 right-0 w-24 h-24 bg-white/5 rounded-full -mr-12 -mt-12 blur-2xl"></div>
        <div className="relative z-10">
          <p className="text-blue-100 text-[10px] mb-1 font-bold uppercase tracking-widest">إجمالي المبلغ للفترة</p>
          <h3 className="text-3xl font-black tabular-nums">{totalAmount.toLocaleString()} <span className="text-sm font-normal opacity-70">ر.ي</span></h3>
        </div>
        <div className="p-3 bg-white/15 rounded-2xl relative z-10 backdrop-blur-sm border border-white/10"><TrendingUp size={24}/></div>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <button onClick={() => setShowPdfMenu(true)} disabled={filteredExpenses.length === 0} className="px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 bg-slate-900 border border-slate-800 text-white hover:border-blue-500 transition-all active:scale-95 disabled:opacity-50 shadow-lg"><FileDown size={24} className="text-blue-500"/><span className="text-xs">تصدير PDF</span></button>
        <button onClick={shareViaWhatsApp} disabled={filteredExpenses.length === 0} className="px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 bg-slate-900 border border-slate-800 text-white hover:border-green-500 transition-all active:scale-95 disabled:opacity-50 shadow-lg"><MessageCircle size={24} className="text-green-500"/><span className="text-xs">مشاركة واتساب</span></button>
      </div>

      <div className="space-y-3">
        <div className="flex justify-between items-center px-1">
          <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">السندات المفلترة ({filteredExpenses.length})</h4>
        </div>
        {displayedExpenses.map(exp => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div key={exp.id} className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30 cursor-pointer active:bg-slate-800 transition-colors relative overflow-hidden group" onClick={() => onExpenseSelect?.(exp)}>
