          <button onClick={() => onEdit(expense)} className="bg-slate-800 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 active:scale-95 transition-all hover:bg-slate-700">
            <Edit3 size={20} />
            <span>تعديل</span>
          </button>
          <button disabled={isGeneratingVoucher} onClick={generateVoucherPDF} className="bg-blue-600 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 shadow-xl shadow-blue-900/20 active:scale-95 transition-all hover:bg-blue-500 disabled:opacity-50">
            {isGeneratingVoucher ? <Loader2 size={20} className="animate-spin" /> : <ExternalLink size={20} />}
            <span>عرض السند</span>
          </button>
        </div>
      </div>

      <ConfirmModal isOpen={isConfirmOpen} title="أرشفة السند" message="هل أنت متأكد من حذف هذا السند؟ سيتم نقله إلى سلة المهملات." onConfirm={handleDeleteToTrash} onCancel={() => setIsConfirmOpen(false)} />

      <div ref={voucherRef} dir="rtl" style={{ display: 'none', width: '148mm', padding: '12mm', backgroundColor: '#ffffff', color: '#1e293b', fontFamily: "'Tajawal', Arial" }}>
        <div style={{ border: '1.5mm double #3b82f6', padding: '10mm', height: '100%', borderRadius: '4px', position: 'relative', display: 'flex', flexDirection: 'column' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #e2e8f0', paddingBottom: '6mm', marginBottom: '8mm' }}>
            <div><h1 style={{ fontSize: '24px', fontWeight: '900', color: '#1e3a8a', margin: '0 0 2mm 0' }}>سند صــرف مالي</h1><p style={{ fontSize: '10px', color: '#64748b', margin: 0 }}>نظام صرف لإدارة المصروفات الشخصية</p></div>
            <div style={{ textAlign: 'left', fontSize: '11px', color: '#1e293b' }}><p style={{ margin: '0 0 1mm 0' }}>الرقم: <span style={{ fontWeight: 'bold' }}>SRF-{expense.serialNumber}</span></p><p style={{ margin: 0 }}>التاريخ: <span style={{ fontWeight: 'bold' }}>{expense.date}</span></p></div>
          </div>
          <div style={{ flexGrow: 1 }}>
            <div style={{ marginBottom: '6mm', display: 'flex', gap: '4px' }}><span style={{ fontSize: '13px', color: '#64748b' }}>يصرف لـ:</span><span style={{ fontSize: '15px', fontWeight: 'bold', borderBottom: '1px dashed #cbd5e1', flexGrow: 1 }}>{category?.name || 'عام'}</span></div>
            <div style={{ backgroundColor: '#f8fafc', border: '1px solid #e2e8f0', padding: '6mm', borderRadius: '4px', marginBottom: '8mm', textAlign: 'center' }}><p style={{ fontSize: '10px', color: '#64748b', marginBottom: '2mm' }}>مبلغ وقدره</p><h2 style={{ fontSize: '28px', fontWeight: '900', color: '#1d4ed8', margin: 0, tabularNums: true }}>{expense.amount.toLocaleString()} <span style={{ fontSize: '14px' }}>ريال يمني</span></h2></div>
            <div style={{ display: 'flex', gap: '4px', alignItems: 'start' }}><span style={{ fontSize: '13px', color: '#64748b', whiteSpace: 'nowrap' }}>وذلك مقابل:</span><span style={{ fontSize: '13px', lineHeight: '1.6', flexGrow: 1 }}>{expense.notes || 'مصروفات متنوعة.'}{expense.tags && expense.tags.length > 0 && ` [${expense.tags.join(' ')}]`}</span></div>
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '15mm', borderTop: '1px solid #f1f5f9', paddingTop: '10mm' }}><div style={{ textAlign: 'center', width: '40%' }}><p style={{ margin: '0 0 12mm 0', fontSize: '11px', fontWeight: 'bold', color: '#475569' }}>توقيع المستلم</p><div style={{ height: '0.3mm', width: '100%', backgroundColor: '#cbd5e1' }}></div></div><div style={{ textAlign: 'center', width: '40%' }}><p style={{ margin: '0 0 12mm 0', fontSize: '11px', fontWeight: 'bold', color: '#475569' }}>المحاسب / المدير</p><div style={{ height: '0.3mm', width: '100%', backgroundColor: '#1e3a8a' }}></div></div></div>
          <p style={{ position: 'absolute', bottom: '4mm', left: '0', right: '0', textAlign: 'center', fontSize: '8px', color: '#94a3b8' }}>صدر هذا السند إلكترونياً عبر تطبيق صرف - {new Date().toLocaleTimeString('ar-YE')}</p>
        </div>
      </div>
    </div>
  );
};

export default ExpenseDetailView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { FileDown, TrendingUp, Calendar, MessageCircle, ChevronRight, Search, X, ExternalLink, Download, FileText, Layers, ChevronDown, Star, Tag, Hash, Clock } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface ReportsViewProps { onExpenseSelect?: (exp: Expense) => void; }

const ReportsView: React.FC<ReportsViewProps> = ({ onExpenseSelect }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showPdfMenu, setShowPdfMenu] = useState(false);
  const [showAll, setShowAll] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusMessage, setStatusMessage] = useState('');
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const reportRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);

      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();

      if (selectedCategoryId !== 'all') results = results.filter(e => e.categoryId === selectedCategoryId);

      results.sort((a, b) => b.createdAt - a.createdAt);
      setExpenses(results);
      setShowAll(false);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId]);

  useEffect(() => {
    if (searchQuery.length > 0) {
      const loadSuggestions = async () => {
        const allExpenses = await db.expenses.toArray();
        const tags = allExpenses.flatMap(e => e.tags || []);
        const notes = allExpenses.map(e => e.notes || '').filter(n => n.length > 0);

        const combined = Array.from(new Set([...tags, ...notes]));
        const filtered = combined.filter(item => 
          item.toLowerCase().includes(searchQuery.toLowerCase())
        ).slice(0, 5);

        setSuggestions(filtered);
        setShowSuggestions(true);
      };
      loadSuggestions();
    } else {
      setSuggestions([]);
      setShowSuggestions(false);
    }
  }, [searchQuery]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const processPDF = async (action: 'download' | 'view') => {
    if (expenses.length === 0 || isGenerating) return;
    setIsGenerating(true); 
    setShowPdfMenu(false); 
    setProgress(10); 
    setStatusMessage('جاري تحضير البيانات...');
    try {
      const element = reportRef.current;
      if (!element) return;
      await new Promise(r => setTimeout(r, 500)); 
      setProgress(40); 
      setStatusMessage('جاري التقاط لقطات عالية الجودة...');
      element.style.display = 'block'; 
      element.style.visibility = 'visible'; 
      element.style.position = 'fixed'; 
      element.style.left = '-10000px';
      const canvas = await html2canvas(element, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
      element.style.display = 'none'; 
      setProgress(80); 
      setStatusMessage('جاري تحويل البيانات إلى ملف PDF...');
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      setProgress(100); 
      setStatusMessage('اكتملت العملية!');
      await new Promise(r => setTimeout(r, 500));
      if (action === 'download') pdf.save(`تقرير_صرف_${fromDate}.pdf`);
      else window.open(pdf.output('bloburl'), '_blank');
    } catch (error) { alert('حدث خطأ أثناء معالجة التقرير.'); } 
    finally { setIsGenerating(false); setProgress(0); setStatusMessage(''); }
  };

  const shareViaWhatsApp = () => {
    const totalVal = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
    const cat = selectedCategoryId !== 'all' ? categories.find(c => c.id === selectedCategoryId) : null;

    const message = `*كشف مصروفات - تطبيق صرف*\n\n` +
                    `*الفترة:* من ${fromDate} إلى ${toDate}\n` +
                    (cat ? `*القسم:* ${cat.name}\n` : '') +
                    (searchQuery ? `*بحث:* ${searchQuery}\n` : '') +
                    `*الإجمالي:* ${totalVal.toLocaleString()} ر.ي\n` +
                    `*عدد العمليات:* ${filteredExpenses.length}\n\n` +
                    `_تم التصدير بواسطة تطبيق صرف المالي_`;

    let targetPhone = '';
    if (cat?.phoneNumber) {
      targetPhone = cat.phoneNumber.startsWith('967') ? cat.phoneNumber : `967${cat.phoneNumber}`;
    }

    const url = `https://wa.me/${targetPhone}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const filteredExpenses = expenses.filter(exp => 
    exp.notes?.toLowerCase().includes(searchQuery.toLowerCase()) || 
    exp.amount.toString().includes(searchQuery) ||
    exp.tags?.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  const totalAmount = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
  const displayedExpenses = showAll ? filteredExpenses : filteredExpenses.slice(0, 15);
  const sortedExpensesForPdf = [...filteredExpenses].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  return (
    <div className="space-y-6 pb-10 animate-in fade-in duration-500">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl shadow-lg">
          <label className="text-[10px] text-slate-500 font-black uppercase tracking-widest mb-1 flex items-center gap-1"><Calendar size={12}/> من تاريخ</label>
          <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400 font-bold" value={fromDate} onChange={e => setFromDate(e.target.value)}/>
          <span className="text-[9px] text-slate-600 block mt-1 font-medium">{getDayName(fromDate)}</span>
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl shadow-lg">
          <label className="text-[10px] text-slate-500 font-black uppercase tracking-widest mb-1 flex items-center gap-1"><Calendar size={12}/> إلى تاريخ</label>
          <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400 font-bold" value={toDate} onChange={e => setToDate(e.target.value)}/>
          <span className="text-[9px] text-slate-600 block mt-1 font-medium">{getDayName(toDate)}</span>
        </div>
      </div>

      <div className="space-y-2">
        <label className="text-[10px] text-slate-500 font-black uppercase tracking-widest px-1 flex items-center gap-1"><Layers size={12}/> تصفية حسب القسم</label>
        <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
          <button onClick={() => setSelectedCategoryId('all')} className={`flex-shrink-0 px-6 py-2 rounded-full border text-xs font-black transition-all ${selectedCategoryId === 'all' ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>الكل</button>
          {categories.map(cat => (
            <button key={cat.id} onClick={() => setSelectedCategoryId(cat.id)} className={`flex-shrink-0 px-6 py-2 rounded-full border text-xs font-black transition-all ${selectedCategoryId === cat.id ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>{cat.name}</button>
          ))}
        </div>
      </div>

      <div className="relative" ref={searchRef}>
        <div className="absolute right-4 top-4 text-slate-500">
          <Search size={18}/>
        </div>
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-11 pl-11 py-4 text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none shadow-xl placeholder:text-slate-600 transition-all" 
          placeholder="ابحث بالوصف، المبلغ، أو الوسوم (#)..." 
          value={searchQuery} 
          onChange={e => setSearchQuery(e.target.value)}
          onFocus={() => searchQuery.length > 0 && setShowSuggestions(true)}
        />
        {searchQuery && (
          <button 
            onClick={() => { setSearchQuery(''); setShowSuggestions(false); }}
            className="absolute left-4 top-4 text-slate-500 hover:text-white transition-colors"
          >
            <X size={18}/>
          </button>
        )}

        {showSuggestions && suggestions.length > 0 && (
          <div className="absolute top-full left-0 right-0 mt-2 bg-slate-900 border border-slate-800 rounded-2xl shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2">
            <div className="p-2 border-b border-slate-800 flex items-center gap-2 px-4 py-3 bg-slate-900/50">
              <Clock size={14} className="text-slate-500" />
              <span className="text-[10px] text-slate-500 font-black uppercase tracking-widest">نتائج مقترحة</span>
            </div>
            {suggestions.map((suggestion, idx) => (
              <button
                key={idx}
                onClick={() => {
                  setSearchQuery(suggestion);
                  setShowSuggestions(false);
                }}
                className="w-full text-right px-4 py-3.5 hover:bg-slate-800 text-sm font-bold border-b border-slate-800/50 last:border-0 flex items-center justify-between transition-colors group"
              >
                <span className={suggestion.startsWith('#') ? 'text-blue-400' : 'text-slate-200'}>
                  {suggestion}
                </span>
                <ChevronRight size={14} className="text-slate-700 rotate-180 group-hover:text-blue-500 transition-colors" />
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-7 rounded-[2.5rem] shadow-2xl text-white flex justify-between items-center relative overflow-hidden group">
        <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -mr-16 -mt-16 blur-2xl group-hover:scale-150 transition-transform duration-1000"></div>
        <div className="relative z-10">
          <p className="text-blue-100 text-[10px] mb-1 font-black uppercase tracking-[0.2em]">إجمالي المبلغ للفترة</p>
          <h3 className="text-4xl font-black tabular-nums">{totalAmount.toLocaleString()} <span className="text-sm font-normal opacity-70">ر.ي</span></h3>
        </div>
        <div className="p-4 bg-white/15 rounded-3xl relative z-10 backdrop-blur-xl border border-white/10 shadow-lg group-hover:rotate-12 transition-transform"><TrendingUp size={28}/></div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <button onClick={() => setShowPdfMenu(true)} disabled={filteredExpenses.length === 0} className="px-4 py-5 rounded-3xl font-black flex flex-col items-center justify-center gap-2 bg-slate-900 border border-slate-800 text-white hover:border-blue-500 hover:shadow-lg hover:shadow-blue-900/10 transition-all active:scale-95 disabled:opacity-30 shadow-md">
          <div className="p-3 bg-blue-600/10 rounded-2xl"><FileDown size={24} className="text-blue-500"/></div>
          <span className="text-[11px] uppercase tracking-wider">تصدير PDF</span>
        </button>
        <button onClick={shareViaWhatsApp} disabled={filteredExpenses.length === 0} className="px-4 py-5 rounded-3xl font-black flex flex-col items-center justify-center gap-2 bg-slate-900 border border-slate-800 text-white hover:border-green-500 hover:shadow-lg hover:shadow-green-900/10 transition-all active:scale-95 disabled:opacity-30 shadow-md">
          <div className="p-3 bg-green-600/10 rounded-2xl"><MessageCircle size={24} className="text-green-500"/></div>
          <span className="text-[11px] uppercase tracking-wider">مشاركة واتساب</span>
        </button>
      </div>

      <div className="space-y-4">
        <div className="flex justify-between items-center px-1">
          <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.25em] flex items-center gap-2">
            <Layers size={12} className="text-blue-500" />
            السندات المفلترة ({filteredExpenses.length})
          </h4>
        </div>

        {displayedExpenses.length > 0 ? (
          <div className="space-y-3">
            {displayedExpenses.map(exp => {
              const cat = categories.find(c => c.id === exp.categoryId);
              return (
                <div 
                  key={exp.id} 
                  className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30 cursor-pointer active:bg-slate-800 transition-all relative overflow-hidden group hover:border-slate-700" 
                  onClick={() => onExpenseSelect?.(exp)}
                >
                  {exp.isFavorite && <div className="absolute top-0 right-0 p-2 bg-yellow-400/10 rounded-bl-2xl"><Star size={12} className="text-yellow-400 fill-yellow-400" /></div>}
                  <div className="flex gap-4 items-center">
                    <div className="w-11 h-11 rounded-2xl bg-slate-800 flex items-center justify-center text-[10px] text-blue-500 font-black border border-slate-700 group-hover:border-blue-500/50 transition-colors shadow-inner">
                      {exp.serialNumber || '0'}
                    </div>
                    <div>
                      <p className="font-black tabular-nums text-slate-200 text-base">{exp.amount.toLocaleString()} ر.ي</p>
                      <p className="text-[10px] text-slate-500 font-bold mt-0.5">{exp.date} • {cat?.name}</p>
                      {exp.tags && exp.tags.length > 0 && (
                        <div className="flex gap-1.5 mt-2 overflow-x-auto no-scrollbar">
                          {exp.tags.map(t => <span key={t} className="text-[8px] font-black bg-blue-600/10 text-blue-400 border border-blue-600/20 px-2 py-0.5 rounded-full">{t}</span>)}
                        </div>
                      )}
                    </div>
                  </div>
                  <ChevronRight size={16} className="text-slate-700 rotate-180 group-hover:text-blue-500 transition-all"/>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="text-center py-20 bg-slate-900/20 border border-dashed border-slate-800 rounded-[2.5rem]">
            <Search size={40} className="text-slate-800 mx-auto mb-4" />
            <p className="text-slate-500 text-sm font-bold">لا توجد نتائج تطابق بحثك</p>
            <p className="text-[10px] text-slate-700 mt-2">جرب البحث بكلمات مختلفة أو تغيير الفترة</p>
          </div>
        )}

        {!showAll && filteredExpenses.length > 15 && (
          <button 
            onClick={() => setShowAll(true)} 
            className="w-full py-5 mt-2 flex flex-col items-center justify-center gap-1 text-[11px] font-black text-blue-500 bg-blue-600/5 border border-dashed border-blue-600/20 rounded-3xl active:scale-95 transition-all"
          >
            <span>عرض كافة النتائج المتبقية ({filteredExpenses.length - 15})</span>
            <ChevronDown size={14} className="animate-bounce mt-1" />
          </button>
        )}
      </div>

      {isGenerating && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[200] flex flex-col items-center justify-center p-8">
          <div className="w-full max-w-xs space-y-8 text-center">
            <div className="relative flex items-center justify-center">
              <div className="w-24 h-24 rounded-full border-4 border-slate-800 border-t-blue-500 animate-spin shadow-2xl shadow-blue-500/20"/>
              <FileText className="absolute text-blue-500" size={32}/>
            </div>
            <div className="space-y-4">
              <div className="flex justify-between items-end mb-2 px-1">
                <span className="text-blue-400 text-xs font-black uppercase tracking-widest">{statusMessage}</span>
                <span className="text-slate-500 text-[10px] font-mono font-bold">{progress}%</span>
              </div>
              <div className="w-full h-2 bg-slate-800 rounded-full overflow-hidden shadow-inner">
                <div className="h-full bg-blue-500 transition-all duration-500 shadow-lg shadow-blue-500/50" style={{ width: `${progress}%` }}/>
              </div>
            </div>
          </div>
        </div>
      )}

      {showPdfMenu && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[200] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm rounded-[3rem] p-8 shadow-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center mb-8">
              <div className="flex items-center gap-3">
                <div className="p-3 bg-blue-600/20 text-blue-500 rounded-2xl shadow-lg">
                  <FileDown size={24} />
                </div>
                <div>
                  <h3 className="text-xl font-black text-white">تصدير الكشف</h3>
                  <p className="text-[10px] text-slate-500 mt-0.5">اختر كيفية معالجة التقرير</p>
                </div>
              </div>
              <button onClick={() => setShowPdfMenu(false)} className="p-2 text-slate-500 hover:text-white transition-colors">
                <X size={24}/>
              </button>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <button onClick={() => processPDF('view')} className="group bg-slate-800/50 hover:bg-slate-800 text-white p-7 rounded-[2.5rem] flex flex-col items-center gap-3 border border-slate-800 transition-all active:scale-95">
                <div className="p-4 bg-blue-600/10 text-blue-500 rounded-2xl group-hover:scale-110 transition-transform">
                  <ExternalLink size={28}/>
                </div>
                <span className="font-black text-xs uppercase tracking-wider">فتح فوري</span>
              </button>
              <button onClick={() => processPDF('download')} className="group bg-blue-600 hover:bg-blue-500 text-white p-7 rounded-[2.5rem] flex flex-col items-center gap-3 shadow-2xl shadow-blue-900/20 transition-all active:scale-95 border border-blue-500/20">
                <div className="p-4 bg-white/20 text-white rounded-2xl group-hover:scale-110 transition-transform">
                  <Download size={28}/>
                </div>
                <span className="font-black text-xs uppercase tracking-wider">تحميل PDF</span>
              </button>
            </div>
          </div>
        </div>
      )}

      <div ref={reportRef} dir="rtl" style={{ display: 'none', width: '210mm', padding: '15mm', backgroundColor: '#ffffff', color: '#000000', fontFamily: 'Tajawal' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '2px solid #000', paddingBottom: '10px', marginBottom: '20px' }}>
          <div><h1 style={{ margin: 0, fontSize: '24px', color: '#000000' }}>كشف مصروفات</h1><p style={{ margin: 0, fontSize: '12px', color: '#000000' }}>القسم: {selectedCategoryId === 'all' ? 'الكل' : categories.find(c => c.id === selectedCategoryId)?.name}{searchQuery ? ` | بحث: ${searchQuery}` : ''}</p></div>
          <div style={{ textAlign: 'left' }}><p style={{ margin: 0, fontSize: '10px', color: '#000000' }}>الفترة: {fromDate} إلى {toDate}</p></div>
        </div>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '10px', color: '#000000' }}>
          <thead><tr style={{ backgroundColor: '#f0f0f0' }}><th style={{ border: '1px solid #000', padding: '5px' }}>رقم السند</th><th style={{ border: '1px solid #000', padding: '5px' }}>القسم</th><th style={{ border: '1px solid #000', padding: '5px' }}>المبلغ</th><th style={{ border: '1px solid #000', padding: '5px' }}>التاريخ</th><th style={{ border: '1px solid #000', padding: '5px' }}>البيان والوسوم</th></tr></thead>
          <tbody>{sortedExpensesForPdf.map(exp => (<tr key={exp.id}><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center' }}>SRF-{exp.serialNumber}</td><td style={{ border: '1px solid #000', padding: '5px' }}>{categories.find(c => c.id === exp.categoryId)?.name}</td><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center' }}>{exp.amount.toLocaleString()}</td><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center' }}>{exp.date}</td><td style={{ border: '1px solid #000', padding: '5px' }}>{exp.notes}{exp.tags && exp.tags.length > 0 && ` [${exp.tags.join(' ')}]`}</td></tr>))}</tbody>
        </table>
        <div style={{ marginTop: '20px', textAlign: 'left', fontWeight: 'bold' }}>إجمالي المبلغ: {totalAmount.toLocaleString()} ريال يمني</div>
      </div>
    </div>
  );
};
export default ReportsView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { FileDown, TrendingUp, Calendar, MessageCircle, ChevronRight, Search, X, ExternalLink, Download, FileText, Layers, ChevronDown, Star, Tag, Hash, Clock } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface ReportsViewProps { onExpenseSelect?: (exp: Expense) => void; }

const ReportsView: React.FC<ReportsViewProps> = ({ onExpenseSelect }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showPdfMenu, setShowPdfMenu] = useState(false);
  const [showAll, setShowAll] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusMessage, setStatusMessage] = useState('');
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const reportRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);

      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();

      if (selectedCategoryId !== 'all') results = results.filter(e => e.categoryId === selectedCategoryId);

      results.sort((a, b) => b.createdAt - a.createdAt);
      setExpenses(results);
      setShowAll(false);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId]);

  useEffect(() => {
    if (searchQuery.length > 0) {
      const loadSuggestions = async () => {
        const allExpenses = await db.expenses.toArray();
        const tags = allExpenses.flatMap(e => e.tags || []);
        const notes = allExpenses.map(e => e.notes || '').filter(n => n.length > 0);

        const combined = Array.from(new Set([...tags, ...notes]));
        const filtered = combined.filter(item => 
          item.toLowerCase().includes(searchQuery.toLowerCase())
        ).slice(0, 5);

        setSuggestions(filtered);
        setShowSuggestions(true);
      };
      loadSuggestions();
    } else {
      setSuggestions([]);
      setShowSuggestions(false);
    }
  }, [searchQuery]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const processPDF = async (action: 'download' | 'view') => {
    if (expenses.length === 0 || isGenerating) return;
    setIsGenerating(true); 
    setShowPdfMenu(false); 
    setProgress(10); 
    setStatusMessage('جاري تحضير البيانات...');
    try {
      const element = reportRef.current;
      if (!element) return;
      await new Promise(r => setTimeout(r, 500)); 
      setProgress(40); 
      setStatusMessage('جاري التقاط لقطات عالية الجودة...');
      element.style.display = 'block'; 
      element.style.visibility = 'visible'; 
      element.style.position = 'fixed'; 
      element.style.left = '-10000px';
      const canvas = await html2canvas(element, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
      element.style.display = 'none'; 
      setProgress(80); 
      setStatusMessage('جاري تحويل البيانات إلى ملف PDF...');
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      setProgress(100); 
      setStatusMessage('اكتملت العملية!');
      await new Promise(r => setTimeout(r, 500));
      if (action === 'download') pdf.save(`تقرير_صرف_${fromDate}.pdf`);
      else window.open(pdf.output('bloburl'), '_blank');
    } catch (error) { alert('حدث خطأ أثناء معالجة التقرير.'); } 
    finally { setIsGenerating(false); setProgress(0); setStatusMessage(''); }
  };

  const selectedCategory = selectedCategoryId !== 'all' ? categories.find(c => c.id === selectedCategoryId) : null;
  const canShareWhatsApp = selectedCategoryId !== 'all' && !!selectedCategory?.phoneNumber;

  const shareViaWhatsApp = () => {
    if (!canShareWhatsApp) return;

    const totalVal = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
    const catName = selectedCategory?.name || '';

    const message = `*كشف مصروفات - تطبيق صرف*\n\n` +
                    `*الفترة:* من ${fromDate} إلى ${toDate}\n` +
                    `*القسم:* ${catName}\n` +
                    (searchQuery ? `*بحث:* ${searchQuery}\n` : '') +
                    `*الإجمالي:* ${totalVal.toLocaleString()} ر.ي\n` +
                    `*عدد العمليات:* ${filteredExpenses.length}\n\n` +
                    `_تم التصدير بواسطة تطبيق صرف المالي_`;

    const phone = selectedCategory!.phoneNumber!.startsWith('967') ? selectedCategory!.phoneNumber : `967${selectedCategory!.phoneNumber}`;
    const url = `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const filteredExpenses = expenses.filter(exp => 
    exp.notes?.toLowerCase().includes(searchQuery.toLowerCase()) || 
    exp.amount.toString().includes(searchQuery) ||
    exp.tags?.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  const totalAmount = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
  const displayedExpenses = showAll ? filteredExpenses : filteredExpenses.slice(0, 15);
  const sortedExpensesForPdf = [...filteredExpenses].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  return (
    <div className="space-y-6 pb-10 animate-in fade-in duration-500">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl shadow-lg">
          <label className="text-[10px] text-slate-500 font-black uppercase tracking-widest mb-1 flex items-center gap-1"><Calendar size={12}/> من تاريخ</label>
          <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400 font-bold" value={fromDate} onChange={e => setFromDate(e.target.value)}/>
          <span className="text-[9px] text-slate-600 block mt-1 font-medium">{getDayName(fromDate)}</span>
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl shadow-lg">
          <label className="text-[10px] text-slate-500 font-black uppercase tracking-widest mb-1 flex items-center gap-1"><Calendar size={12}/> إلى تاريخ</label>
          <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400 font-bold" value={toDate} onChange={e => setToDate(e.target.value)}/>
          <span className="text-[9px] text-slate-600 block mt-1 font-medium">{getDayName(toDate)}</span>
        </div>
      </div>

      <div className="space-y-2">
        <label className="text-[10px] text-slate-500 font-black uppercase tracking-widest px-1 flex items-center gap-1"><Layers size={12}/> تصفية حسب القسم</label>
        <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
          <button onClick={() => setSelectedCategoryId('all')} className={`flex-shrink-0 px-6 py-2 rounded-full border text-xs font-black transition-all ${selectedCategoryId === 'all' ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>الكل</button>
          {categories.map(cat => (
            <button key={cat.id} onClick={() => setSelectedCategoryId(cat.id)} className={`flex-shrink-0 px-6 py-2 rounded-full border text-xs font-black transition-all ${selectedCategoryId === cat.id ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>{cat.name}</button>
          ))}
        </div>
      </div>

      <div className="relative" ref={searchRef}>
        <div className="absolute right-4 top-4 text-slate-500">
          <Search size={18}/>
        </div>
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-11 pl-11 py-4 text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none shadow-xl placeholder:text-slate-600 transition-all" 
          placeholder="ابحث بالوصف، المبلغ، أو الوسوم (#)..." 
          value={searchQuery} 
          onChange={e => setSearchQuery(e.target.value)}
          onFocus={() => searchQuery.length > 0 && setShowSuggestions(true)}
        />
        {searchQuery && (
          <button 
            onClick={() => { setSearchQuery(''); setShowSuggestions(false); }}
            className="absolute left-4 top-4 text-slate-500 hover:text-white transition-colors"
          >
            <X size={18}/>
          </button>
        )}

        {showSuggestions && suggestions.length > 0 && (
          <div className="absolute top-full left-0 right-0 mt-2 bg-slate-900 border border-slate-800 rounded-2xl shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2">
            <div className="p-2 border-b border-slate-800 flex items-center gap-2 px-4 py-3 bg-slate-900/50">
              <Clock size={14} className="text-slate-500" />
              <span className="text-[10px] text-slate-500 font-black uppercase tracking-widest">نتائج مقترحة</span>
            </div>
            {suggestions.map((suggestion, idx) => (
              <button
                key={idx}
                onClick={() => {
                  setSearchQuery(suggestion);
                  setShowSuggestions(false);
                }}
                className="w-full text-right px-4 py-3.5 hover:bg-slate-800 text-sm font-bold border-b border-slate-800/50 last:border-0 flex items-center justify-between transition-colors group"
              >
                <span className={suggestion.startsWith('#') ? 'text-blue-400' : 'text-slate-200'}>
                  {suggestion}
                </span>
                <ChevronRight size={14} className="text-slate-700 rotate-180 group-hover:text-blue-500 transition-colors" />
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-7 rounded-[2.5rem] shadow-2xl text-white flex justify-between items-center relative overflow-hidden group">
        <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -mr-16 -mt-16 blur-2xl group-hover:scale-150 transition-transform duration-1000"></div>
        <div className="relative z-10">
          <p className="text-blue-100 text-[10px] mb-1 font-black uppercase tracking-[0.2em]">إجمالي المبلغ للفترة</p>
          <h3 className="text-4xl font-black tabular-nums">{totalAmount.toLocaleString()} <span className="text-sm font-normal opacity-70">ر.ي</span></h3>
        </div>
        <div className="p-4 bg-white/15 rounded-3xl relative z-10 backdrop-blur-xl border border-white/10 shadow-lg group-hover:rotate-12 transition-transform"><TrendingUp size={28}/></div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <button onClick={() => setShowPdfMenu(true)} disabled={filteredExpenses.length === 0} className="px-4 py-5 rounded-3xl font-black flex flex-col items-center justify-center gap-2 bg-slate-900 border border-slate-800 text-white hover:border-blue-500 hover:shadow-lg hover:shadow-blue-900/10 transition-all active:scale-95 disabled:opacity-30 shadow-md">
          <div className="p-3 bg-blue-600/10 rounded-2xl"><FileDown size={24} className="text-blue-500"/></div>
          <span className="text-[11px] uppercase tracking-wider">تصدير PDF</span>
        </button>
        <button 
          onClick={shareViaWhatsApp} 
          disabled={!canShareWhatsApp || filteredExpenses.length === 0} 
          className={`px-4 py-5 rounded-3xl font-black flex flex-col items-center justify-center gap-2 border transition-all active:scale-95 shadow-md ${canShareWhatsApp ? 'bg-slate-900 border-slate-800 text-white hover:border-green-500 hover:shadow-green-900/10' : 'bg-slate-900/40 border-slate-800/50 text-slate-600 opacity-50 cursor-not-allowed'}`}
        >
          <div className={`p-3 rounded-2xl ${canShareWhatsApp ? 'bg-green-600/10 text-green-500' : 'bg-slate-800 text-slate-700'}`}>
            <MessageCircle size={24} />
          </div>
          <span className="text-[11px] uppercase tracking-wider">مشاركة واتساب</span>
        </button>
      </div>

      <div className="space-y-4">
        <div className="flex justify-between items-center px-1">
          <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.25em] flex items-center gap-2">
            <Layers size={12} className="text-blue-500" />
            السندات المفلترة ({filteredExpenses.length})
          </h4>
        </div>

        {displayedExpenses.length > 0 ? (
          <div className="space-y-3">
            {displayedExpenses.map(exp => {
              const cat = categories.find(c => c.id === exp.categoryId);
              return (
                <div 
                  key={exp.id} 
                  className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30 cursor-pointer active:bg-slate-800 transition-all relative overflow-hidden group hover:border-slate-700" 
                  onClick={() => onExpenseSelect?.(exp)}
                >
                  {exp.isFavorite && <div className="absolute top-0 right-0 p-2 bg-yellow-400/10 rounded-bl-2xl"><Star size={12} className="text-yellow-400 fill-yellow-400" /></div>}
                  <div className="flex gap-4 items-center">
                    <div className="w-11 h-11 rounded-2xl bg-slate-800 flex items-center justify-center text-[10px] text-blue-500 font-black border border-slate-700 group-hover:border-blue-500/50 transition-colors shadow-inner">
                      {exp.serialNumber || '0'}
                    </div>
                    <div>
                      <p className="font-black tabular-nums text-slate-200 text-base">{exp.amount.toLocaleString()} ر.ي</p>
                      <p className="text-[10px] text-slate-500 font-bold mt-0.5">{exp.date} • {cat?.name}</p>
                      {exp.tags && exp.tags.length > 0 && (
                        <div className="flex gap-1.5 mt-2 overflow-x-auto no-scrollbar">
                          {exp.tags.map(t => <span key={t} className="text-[8px] font-black bg-blue-600/10 text-blue-400 border border-blue-600/20 px-2 py-0.5 rounded-full">{t}</span>)}
                        </div>
                      )}
                    </div>
                  </div>
                  <ChevronRight size={16} className="text-slate-700 rotate-180 group-hover:text-blue-500 transition-all"/>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="text-center py-20 bg-slate-900/20 border border-dashed border-slate-800 rounded-[2.5rem]">
            <Search size={40} className="text-slate-800 mx-auto mb-4" />
            <p className="text-slate-500 text-sm font-bold">لا توجد نتائج تطابق بحثك</p>
            <p className="text-[10px] text-slate-700 mt-2">جرب البحث بكلمات مختلفة أو تغيير الفترة</p>
          </div>
        )}

        {!showAll && filteredExpenses.length > 15 && (
          <button 
            onClick={() => setShowAll(true)} 
            className="w-full py-5 mt-2 flex flex-col items-center justify-center gap-1 text-[11px] font-black text-blue-500 bg-blue-600/5 border border-dashed border-blue-600/20 rounded-3xl active:scale-95 transition-all"
          >
            <span>عرض كافة النتائج المتبقية ({filteredExpenses.length - 15})</span>
            <ChevronDown size={14} className="animate-bounce mt-1" />
          </button>
        )}
      </div>

      {isGenerating && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[200] flex flex-col items-center justify-center p-8">
          <div className="w-full max-w-xs space-y-8 text-center">
            <div className="relative flex items-center justify-center">
              <div className="w-24 h-24 rounded-full border-4 border-slate-800 border-t-blue-500 animate-spin shadow-2xl shadow-blue-500/20"/>
              <FileText className="absolute text-blue-500" size={32}/>
            </div>
            <div className="space-y-4">
              <div className="flex justify-between items-end mb-2 px-1">
                <span className="text-blue-400 text-xs font-black uppercase tracking-widest">{statusMessage}</span>
                <span className="text-slate-500 text-[10px] font-mono font-bold">{progress}%</span>
              </div>
              <div className="w-full h-2 bg-slate-800 rounded-full overflow-hidden shadow-inner">
                <div className="h-full bg-blue-500 transition-all duration-500 shadow-lg shadow-blue-500/50" style={{ width: `${progress}%` }}/>
              </div>
            </div>
          </div>
        </div>
      )}

      {showPdfMenu && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[200] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm rounded-[3rem] p-8 shadow-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center mb-8">
              <div className="flex items-center gap-3">
                <div className="p-3 bg-blue-600/20 text-blue-500 rounded-2xl shadow-lg">
                  <FileDown size={24} />
                </div>
                <div>
                  <h3 className="text-xl font-black text-white">تصدير الكشف</h3>
                  <p className="text-[10px] text-slate-500 mt-0.5">اختر كيفية معالجة التقرير</p>
                </div>
              </div>
              <button onClick={() => setShowPdfMenu(false)} className="p-2 text-slate-500 hover:text-white transition-colors">
                <X size={24}/>
              </button>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <button onClick={() => processPDF('view')} className="group bg-slate-800/50 hover:bg-slate-800 text-white p-7 rounded-[2.5rem] flex flex-col items-center gap-3 border border-slate-800 transition-all active:scale-95">
                <div className="p-4 bg-blue-600/10 text-blue-500 rounded-2xl group-hover:scale-110 transition-transform">
                  <ExternalLink size={28}/>
                </div>
                <span className="font-black text-xs uppercase tracking-wider">فتح فوري</span>
              </button>
              <button onClick={() => processPDF('download')} className="group bg-blue-600 hover:bg-blue-500 text-white p-7 rounded-[2.5rem] flex flex-col items-center gap-3 shadow-2xl shadow-blue-900/20 transition-all active:scale-95 border border-blue-500/20">
                <div className="p-4 bg-white/20 text-white rounded-2xl group-hover:scale-110 transition-transform">
                  <Download size={28}/>
                </div>
                <span className="font-black text-xs uppercase tracking-wider">تحميل PDF</span>
              </button>
            </div>
          </div>
        </div>
      )}

      <div ref={reportRef} dir="rtl" style={{ display: 'none', width: '210mm', padding: '15mm', backgroundColor: '#ffffff', color: '#000000', fontFamily: 'Tajawal' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '2px solid #000', paddingBottom: '10px', marginBottom: '20px' }}>
          <div><h1 style={{ margin: 0, fontSize: '24px', color: '#000000' }}>كشف مصروفات</h1><p style={{ margin: 0, fontSize: '12px', color: '#000000' }}>القسم: {selectedCategoryId === 'all' ? 'الكل' : categories.find(c => c.id === selectedCategoryId)?.name}{searchQuery ? ` | بحث: ${searchQuery}` : ''}</p></div>
          <div style={{ textAlign: 'left' }}><p style={{ margin: 0, fontSize: '10px', color: '#000000' }}>الفترة: {fromDate} إلى {toDate}</p></div>
        </div>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '10px', color: '#000000' }}>
          <thead><tr style={{ backgroundColor: '#f0f0f0' }}><th style={{ border: '1px solid #000', padding: '5px' }}>رقم السند</th><th style={{ border: '1px solid #000', padding: '5px' }}>القسم</th><th style={{ border: '1px solid #000', padding: '5px' }}>المبلغ</th><th style={{ border: '1px solid #000', padding: '5px' }}>التاريخ</th><th style={{ border: '1px solid #000', padding: '5px' }}>البيان والوسوم</th></tr></thead>
          <tbody>{sortedExpensesForPdf.map(exp => (<tr key={exp.id}><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center' }}>SRF-{exp.serialNumber}</td><td style={{ border: '1px solid #000', padding: '5px' }}>{categories.find(c => c.id === exp.categoryId)?.name}</td><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center' }}>{exp.amount.toLocaleString()}</td><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center' }}>{exp.date}</td><td style={{ border: '1px solid #000', padding: '5px' }}>{exp.notes}{exp.tags && exp.tags.length > 0 && ` [${exp.tags.join(' ')}]`}</td></tr>))}</tbody>
        </table>
        <div style={{ marginTop: '20px', textAlign: 'left', fontWeight: 'bold' }}>إجمالي المبلغ: {totalAmount.toLocaleString()} ريال يمني</div>
      </div>
    </div>
  );
};
export default ReportsView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Category, Expense, AppSettings } from '../types';
import { X, Camera, Calendar, Trash2, Check, Star, Hash, Tag } from 'lucide-react';
import ConfirmModal from './ConfirmModal';

interface AddExpenseViewProps {
  onClose: () => void;
  initialData?: Expense | null;
  preselectedCategoryId?: string;
}

const AddExpenseView: React.FC<AddExpenseViewProps> = ({ onClose, initialData, preselectedCategoryId }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [amount, setAmount] = useState(initialData?.amount.toString() || '');
  const [categoryId, setCategoryId] = useState(initialData?.categoryId || preselectedCategoryId || 'default_general');
  const [notes, setNotes] = useState(initialData?.notes || '');
  const [tagsInput, setTagsInput] = useState(initialData?.tags?.join(' ') || '');
  const [suggestedTags, setSuggestedTags] = useState<string[]>([]);
  const [date, setDate] = useState(initialData?.date || new Date().toISOString().split('T')[0]);
  const [image, setImage] = useState<string | null>(initialData?.image || null);
  const [isFavorite, setIsFavorite] = useState(initialData?.isFavorite || false);
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    db.categories.toArray().then(setCategories);

    // جلب الوسوم المستخدمة سابقاً للاقتراح
    db.expenses.toArray().then(exps => {
      const allTags = exps.flatMap(e => e.tags || []);
      const uniqueTags = Array.from(new Set(allTags)).slice(0, 10);
      setSuggestedTags(uniqueTags);
    });

    if (!initialData && preselectedCategoryId) {
      setCategoryId(preselectedCategoryId);
    }
  }, [preselectedCategoryId, initialData]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleSave = async () => {
    const numAmount = parseFloat(amount);
    if (!numAmount || numAmount <= 0) {
      alert('الرجاء إدخال مبلغ صحيح أكبر من صفر');
      return;
    }

    // تنظيف الوسوم وتحويلها لمصفوفة
    const tags = tagsInput
      .split(/[\s,،]+/)
      .filter(t => t.trim() !== '')
      .map(t => t.startsWith('#') ? t : `#${t}`);

    let serialNumber = initialData?.serialNumber;

    if (!initialData) {
      const settings = await db.settings.get('app_settings') as AppSettings;
      const nextSerial = (settings?.lastSerialNumber || 0) + 1;
      serialNumber = nextSerial;
      await db.settings.update('app_settings', { lastSerialNumber: nextSerial });
    }

    const expenseData: Expense = {
      id: initialData?.id || Date.now().toString(),
      amount: numAmount,
      categoryId,
      notes,
      tags,
      date,
      image: image || undefined,
      createdAt: initialData?.createdAt || Date.now(),
      serialNumber,
      isFavorite
    };

    if (initialData) {
      await db.expenses.put(expenseData);
    } else {
      await db.expenses.add(expenseData);
    }
    onClose();
  };

  const handleDeleteToTrash = async () => {
    if (initialData) {
      await db.trash.add(initialData);
      await db.expenses.delete(initialData.id);
      setIsConfirmOpen(false);
      onClose();
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const addSuggestedTag = (tag: string) => {
    const currentTags = tagsInput.split(/[\s,،]+/).filter(t => t.trim() !== '');
    if (!currentTags.includes(tag)) {
      setTagsInput(prev => (prev.trim() + ' ' + tag).trim());
    }
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="flex items-center justify-between mb-4 sticky top-0 bg-slate-950/80 backdrop-blur-md z-10 py-2 -mx-4 px-4 border-b border-slate-800/50">
        <button onClick={onClose} className="p-2 text-slate-400 hover:text-white transition-colors">
          <X size={24} />
        </button>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => setIsFavorite(!isFavorite)}
            className={`p-2 transition-all active:scale-125 ${isFavorite ? 'text-yellow-400 drop-shadow-[0_0_8px_rgba(250,204,21,0.5)]' : 'text-slate-600'}`}
          >
            <Star size={24} fill={isFavorite ? "currentColor" : "none"} />
          </button>
          <h2 className="text-lg font-bold text-slate-100">{initialData ? 'تعديل مصروف' : 'إضافة مصروف'}</h2>
        </div>
        <button onClick={handleSave} className="bg-blue-600 hover:bg-blue-500 text-white font-bold px-5 py-2 rounded-xl shadow-lg shadow-blue-900/40 active:scale-95 transition-all flex items-center gap-2">
          <Check size={18} />
          <span>حفظ</span>
        </button>
      </div>

      <div className="space-y-6">
        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">المبلغ (ريال يمني)</label>
          <input 
            type="number" 
            pattern="[0-9]*"
            inputMode="decimal"
            autoFocus
            className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-4 py-6 text-4xl font-black text-center text-blue-500 outline-none focus:ring-2 focus:ring-blue-500 tabular-nums shadow-inner"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            placeholder="0.00"
          />
        </div>

        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">القسم الضريبي / المالي</label>
          <div className="flex gap-2 overflow-x-auto pb-3 no-scrollbar">
            {categories.map(cat => (
              <button
                key={cat.id}
                onClick={() => setCategoryId(cat.id)}
                className={`flex-shrink-0 px-6 py-2.5 rounded-2xl border transition-all text-sm font-bold ${
                  categoryId === cat.id 
                    ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-900/40' 
                    : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-700'
                }`}
              >
                {cat.name}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 gap-4">
          <div>
            <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">تاريخ العملية</label>
            <div className="relative group">
              <input 
                type="date"
                className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-4 py-4 outline-none focus:ring-2 focus:ring-blue-500 text-white font-bold"
                value={date}
                onChange={(e) => setDate(e.target.value)}
              />
              <Calendar className="absolute left-4 top-4 text-slate-500 pointer-events-none" size={20} />
              <div className="absolute right-4 top-4 bg-blue-600/10 text-blue-500 px-3 py-1 rounded-lg text-[10px] font-black pointer-events-none border border-blue-500/20">
                {getDayName(date)}
              </div>
            </div>
          </div>
        </div>

        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">البيان / ملاحظات إضافية</label>
          <textarea 
            className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-4 py-4 outline-none focus:ring-2 focus:ring-blue-500 resize-none h-28 text-sm font-medium"
            placeholder="اكتب تفاصيل المصروف هنا..."
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
          />
        </div>

        {/* حقل الوسوم (ذكرى) المحدث */}
        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1 flex items-center gap-1">
            <Tag size={12} className="text-blue-500"/>
            ذكرى (اختياري)
          </label>
          <div className="relative">
            <input 
              className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-4 py-4 text-sm font-bold text-blue-400 outline-none focus:ring-2 focus:ring-blue-500 shadow-inner"
              placeholder=""
              value={tagsInput}
              onChange={(e) => setTagsInput(e.target.value)}
            />
            <Hash className="absolute right-4 top-4 text-slate-500" size={18} />
          </div>

          {suggestedTags.length > 0 && (
            <div className="mt-3 flex flex-wrap gap-2">
              <span className="text-[9px] text-slate-600 font-bold uppercase py-1.5 ml-1">اقتراحات:</span>
              {suggestedTags.map(tag => (
                <button
                  key={tag}
                  onClick={() => addSuggestedTag(tag)}
                  className="px-3 py-1 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-lg text-[10px] font-bold transition-colors border border-slate-700/50"
                >
                  {tag}
                </button>
              ))}
            </div>
          )}
        </div>

        <div>
          <label className="block text-slate-500 text-[10px] font-black uppercase tracking-widest mb-2 px-1">المرفقات والصور</label>
          {image ? (
            <div className="relative group rounded-2xl overflow-hidden border border-slate-800 aspect-video bg-slate-900 shadow-xl">
              <img src={image} className="w-full h-full object-contain" alt="Expense attachment" />
              <button onClick={() => setImage(null)} className="absolute top-3 right-3 bg-red-600 text-white p-2.5 rounded-xl shadow-lg active:scale-90 transition-all"><Trash2 size={18} /></button>
            </div>
          ) : (
            <button onClick={() => fileInputRef.current?.click()} className="w-full border-2 border-dashed border-slate-800 rounded-2xl p-10 flex flex-col items-center justify-center gap-3 text-slate-500 hover:border-blue-500 hover:text-blue-500 transition-all active:scale-[0.98] bg-slate-900/50">
              <div className="p-4 bg-slate-800 rounded-2xl"><Camera size={32} /></div>
              <div className="text-center"><span className="font-bold text-sm block">تصوير فاتورة</span><span className="text-[10px] opacity-60">أو اختيار من الاستوديو</span></div>
            </button>
          )}
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
        </div>

        {initialData && (
          <div className="pt-4">
            <button onClick={() => setIsConfirmOpen(true)} className="w-full p-4 bg-red-600/10 text-red-500 rounded-2xl hover:bg-red-600 hover:text-white transition-all font-bold flex items-center justify-center gap-2 border border-red-500/20 shadow-lg shadow-red-900/5"><Trash2 size={20} /><span>حذف السند (أرشفة بالسلة)</span></button>
          </div>
        )}
      </div>

      <ConfirmModal isOpen={isConfirmOpen} title="أرشفة السند" message="هل أنت متأكد من حذف هذا السند؟ سيتم نقله إلى سلة المهملات." onConfirm={handleDeleteToTrash} onCancel={() => setIsConfirmOpen(false)} />
    </div>
  );
};

export default AddExpenseView;

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Expense, Category, AppSettings } from '../types';
import { CalendarDays, History, ChevronLeft, Star, Zap, X, Plus, Check } from 'lucide-react';

interface HomeViewProps {
  onExpenseSelect: (exp: Expense) => void;
}

const HomeView: React.FC<HomeViewProps> = ({ onExpenseSelect }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [todayExpenses, setTodayExpenses] = useState(0);
  const [recentExpenses, setRecentExpenses] = useState<Expense[]>([]);

  // حالات الإضافة السريعة
  const [isQuickAddOpen, setIsQuickAddOpen] = useState(false);
  const [selectedQuickCat, setSelectedQuickCat] = useState<Category | null>(null);
  const [quickAmount, setQuickAmount] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  const loadData = async () => {
    const cats = await db.categories.toArray();
    cats.sort((a, b) => (a.order || 0) - (b.order || 0));
    setCategories(cats);

    const expenses = await db.expenses.toArray();
    let dailyTotal = 0;
    const todayStr = new Date().toISOString().split('T')[0];
    expenses.forEach(exp => { if (exp.date === todayStr) dailyTotal += exp.amount; });
    setTodayExpenses(dailyTotal);

    const sorted = [...expenses].sort((a, b) => b.createdAt - a.createdAt).slice(0, 10);
    setRecentExpenses(sorted);
  };

  useEffect(() => { loadData(); }, []);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleQuickAdd = (cat: Category) => {
    setSelectedQuickCat(cat);
    setIsQuickAddOpen(true);
  };

  const saveQuickExpense = async (amountToSave?: number) => {
    const finalAmount = amountToSave || parseFloat(quickAmount);
    if (!finalAmount || finalAmount <= 0 || !selectedQuickCat) return;

    setIsSaving(true);
    try {
      const settings = await db.settings.get('app_settings') as AppSettings;
      const nextSerial = (settings?.lastSerialNumber || 0) + 1;

      const newExpense: Expense = {
        id: Date.now().toString(),
        amount: finalAmount,
        categoryId: selectedQuickCat.id,
        date: new Date().toISOString().split('T')[0],
        createdAt: Date.now(),
        serialNumber: nextSerial,
        notes: 'إضافة سريعة'
      };

      await db.expenses.add(newExpense);
      await db.settings.update('app_settings', { lastSerialNumber: nextSerial });

      setIsQuickAddOpen(false);
      setQuickAmount('');
      setSelectedQuickCat(null);
      loadData();
    } catch (error) {
      console.error(error);
    } finally {
      setIsSaving(false);
    }
  };

  const suggestedAmounts = [500, 1000, 2000, 5000, 10000];

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* بطاقة الإجمالي */}
      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-8 rounded-[2.5rem] shadow-2xl shadow-blue-900/30 text-white text-center relative overflow-hidden">
        <div className="absolute top-0 right-0 w-40 h-40 bg-white/10 rounded-full -mr-20 -mt-20 blur-3xl opacity-50"></div>
        <div className="absolute bottom-0 left-0 w-32 h-32 bg-indigo-400/10 rounded-full -ml-16 -mb-16 blur-2xl opacity-40"></div>
        <div className="relative z-10">
          <div className="flex items-center justify-center gap-2 mb-2"><CalendarDays size={16} className="text-blue-100" /><p className="text-blue-100 text-sm font-bold uppercase tracking-widest">إجمالي مصاريف اليوم</p></div>
          <h2 className="text-5xl font-black mb-3 tabular-nums">{todayExpenses.toLocaleString('ar-SA')} <span className="text-xl mr-2 font-normal opacity-70">ر.ي</span></h2>
          <div className="inline-flex items-center px-4 py-1.5 bg-white/15 rounded-full text-[11px] font-bold backdrop-blur-sm border border-white/10">{new Date().toLocaleDateString('ar-YE', { weekday: 'long', day: 'numeric', month: 'long' })}</div>
        </div>
      </div>

      {/* ميزة الإضافة السريعة */}
      <div className="space-y-3">
        <div className="flex items-center justify-between px-2">
          <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
            <Zap size={14} className="text-yellow-500 fill-yellow-500" />
            الإضافة السريعة
          </h3>
        </div>
        <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar px-1">
          {categories.map(cat => (
            <button
              key={cat.id}
              onClick={() => handleQuickAdd(cat)}
              className="flex-shrink-0 flex flex-col items-center gap-2 group"
            >
              <div 
                className="w-14 h-14 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-black/20 group-active:scale-90 transition-all border border-white/5"
                style={{ backgroundColor: cat.color }}
              >
                <Plus size={24} />
              </div>
              <span className="text-[9px] font-bold text-slate-400 truncate w-14 text-center">{cat.name}</span>
            </button>
          ))}
        </div>
      </div>

      {/* أحدث العمليات */}
      <div className="space-y-4">
        <div className="flex justify-between items-center px-2"><h3 className="text-lg font-black text-slate-300 flex items-center gap-2"><History size={18} className="text-blue-500" />أحدث العمليات</h3><span className="text-[10px] font-bold text-slate-600 bg-slate-900 px-2 py-0.5 rounded-full border border-slate-800">آخر ١٠ قيود</span></div>
        <div className="space-y-3">
          {recentExpenses.map((exp) => {
            const cat = categories.find(c => c.id === exp.categoryId);
            return (
              <div key={exp.id} onClick={() => onExpenseSelect(exp)} className="bg-slate-900/60 border border-slate-800/50 p-4 rounded-2xl flex justify-between items-center active:scale-[0.98] transition-all cursor-pointer hover:bg-slate-900 group relative overflow-hidden">
                {exp.isFavorite && <div className="absolute top-0 right-0 w-8 h-8 bg-yellow-400/10 rounded-bl-2xl flex items-center justify-center"><Star size={12} className="text-yellow-400 fill-yellow-400 drop-shadow-[0_0_5px_rgba(250,204,21,0.5)]" /></div>}
                <div className="flex gap-3 items-center">
                  <div className="w-10 h-10 rounded-xl flex items-center justify-center text-[10px] font-black shadow-lg" style={{ backgroundColor: `${cat?.color}15`, color: cat?.color, border: `1px solid ${cat?.color}30` }}>{cat?.name?.charAt(0) || 'ص'}</div>
                  <div>
                    <h4 className="font-bold text-slate-200 text-sm">{cat?.name || 'بدون قسم'}</h4>
                    <p className="text-[10px] text-slate-500 mt-0.5">{exp.date} • {getDayName(exp.date)}</p>
                    {exp.tags && exp.tags.length > 0 && (
                      <div className="flex gap-1 mt-1 overflow-x-auto no-scrollbar max-w-[150px]">
                        {exp.tags.map(t => <span key={t} className="text-[7px] text-blue-400 font-bold bg-blue-600/5 px-1 py-0.5 rounded border border-blue-500/10">{t}</span>)}
                      </div>
                    )}
                  </div>
                </div>
                <div className="text-left flex items-center gap-2"><div className="flex flex-col items-end"><span className="font-bold text-blue-400 tabular-nums">{exp.amount.toLocaleString()}</span><span className="text-[8px] text-slate-600 font-bold">ر.ي</span></div><ChevronLeft size={14} className="text-slate-700 group-hover:text-blue-500 transition-colors" /></div>
              </div>
            );
          })}
          {recentExpenses.length === 0 && <div className="text-center py-10 bg-slate-900/30 rounded-3xl border border-dashed border-slate-800"><p className="text-slate-600 text-xs font-bold">لا توجد عمليات مسجلة بعد</p></div>}
        </div>
      </div>

      {/* نافذة الإضافة السريعة المنبثقة */}
      {isQuickAddOpen && selectedQuickCat && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-in fade-in zoom-in duration-300">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm rounded-[2.5rem] p-8 space-y-6 shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/10 rounded-full -mr-16 -mt-16 blur-3xl"></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl flex items-center justify-center text-white font-black" style={{ backgroundColor: selectedQuickCat.color }}>
                  {selectedQuickCat.name.charAt(0)}
                </div>
                <div>
                  <h3 className="text-lg font-black text-white">{selectedQuickCat.name}</h3>
                  <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">إضافة سريعة اليوم</p>
                </div>
              </div>
              <button onClick={() => setIsQuickAddOpen(false)} className="p-2 text-slate-500 hover:text-white bg-slate-800 rounded-full transition-colors">
                <X size={20} />
              </button>
            </div>

            <div className="space-y-4 relative z-10">
              <div className="grid grid-cols-3 gap-2">
                {suggestedAmounts.map(amt => (
                  <button
                    key={amt}
                    onClick={() => saveQuickExpense(amt)}
                    disabled={isSaving}
                    className="py-3 bg-slate-800 hover:bg-blue-600 text-slate-300 hover:text-white rounded-xl text-xs font-black transition-all active:scale-95 border border-slate-700/50 tabular-nums"
                  >
                    {amt.toLocaleString()}
                  </button>
                ))}
              </div>

              <div className="pt-2">
                <label className="text-[10px] text-slate-500 font-black uppercase tracking-widest mb-2 block px-1">أو أدخل مبلغ مخصص</label>
                <div className="relative">
                  <input
                    type="number"
                    pattern="[0-9]*"
                    inputMode="decimal"
                    autoFocus
                    className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-4 py-4 text-2xl font-black text-center text-blue-500 outline-none focus:ring-2 focus:ring-blue-500 tabular-nums shadow-inner"
                    value={quickAmount}
                    onChange={(e) => setQuickAmount(e.target.value)}
                    placeholder="0.00"
                  />
                  {quickAmount && (
                    <button 
                      onClick={() => saveQuickExpense()}
                      disabled={isSaving}
                      className="absolute left-2 top-2 bottom-2 bg-blue-600 text-white px-4 rounded-xl flex items-center justify-center active:scale-90 transition-all shadow-lg shadow-blue-900/40"
                    >
                      {isSaving ? <Zap size={18} className="animate-pulse" /> : <Check size={20} />}
                    </button>
                  )}
                </div>
              </div>
            </div>

            <p className="text-center text-[9px] text-slate-600 font-bold uppercase tracking-widest">سيتم الحفظ بتوقيت الآن تلقائياً</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default HomeView;

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Expense, Category, AppSettings } from '../types';
import { CalendarDays, History, ChevronLeft, Star, Zap, X, Plus, Check } from 'lucide-react';

interface HomeViewProps {
  onExpenseSelect: (exp: Expense) => void;
